#include <stddef.h> // for size_t
#include <string.h> // for memmove and strlen

char** safe_string_array_alloc_and_copy(const char** input_strings, size_t num_strings) {
    size_t total_length = 0;
    for (size_t i = 0; i < num_strings; ++i) {
        total_length += strlen(input_strings[i]) + 1; // +1 for null terminator
    }

    char** output_strings = malloc(num_strings * sizeof(char*));
    if (!output_strings) {
        free(input_strings); // free any previously allocated resources if malloc fails
        return NULL;
    }

    char* current_string_start = malloc(total_length);
    if (!current_string_start) {
        free(output_strings); // free any previously allocated resources if malloc fails
        free(input_strings); // free any previously allocated resources if malloc fails
        return NULL;
    }

    for (size_t i = 0, current_index = 0; i < num_strings; ++i) {
        size_t string_length = strlen(input_strings[i]);
        memcpy(current_string_start + current_index, input_strings[i], string_length + 1);
        current_index += string_length + 1;
    }

    for (size_t i = 0; i < num_strings; ++i) {
        output_strings[i] = current_string_start + i * (strlen(input_strings[i]) + 1);
    }

    free(current_string_start);

    return output_strings;
}
