#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <locale.h>
#include <errno.h>

#define MAX_BUNDLE_SIZE 1024
#define MAX_ITEM_NAME_LENGTH 256

typedef struct {
    char name[MAX_ITEM_NAME_LENGTH];
    void *data;
    size_t size;
} ResourceItem;

typedef struct {
    size_t item_count;
    ResourceItem *items;
    int error_code;
} ResourceBundle;

int load_resource_bundle(const char *path, ResourceBundle **bundle) {
    FILE *file;
    size_t name_length, data_length;
    char name[MAX_ITEM_NAME_LENGTH];
    char *data;
    ResourceBundle *new_bundle;
    size_t i = 0;

    *bundle = NULL;

    file = fopen(path, "rb");
    if (!file) {
        *bundle = NULL;
        return errno;
    }

    new_bundle = (ResourceBundle *) malloc(sizeof(ResourceBundle));
    if (!new_bundle) {
        fclose(file);
        return ENOMEM;
    }

    new_bundle->items = (ResourceItem *) malloc(MAX_BUNDLE_SIZE * sizeof(ResourceItem));
    if (!new_bundle->items) {
        free(new_bundle);
        fclose(file);
        return ENOMEM;
    }

    new_bundle->error_code = 0;

    while (fscanf(file, "%s %ld %ld", name, &data_length, &name_length) != EOF) {
        if (i >= MAX_BUNDLE_SIZE) {
            free(new_bundle->items);
            free(new_bundle);
            fclose(file);
            return ENOMEM;
        }

        data = malloc(data_length);
        if (!data) {
            free(new_bundle->items);
            free(new_bundle);
            fclose(file);
            return ENOMEM;
        }

        strncpy(new_bundle->items[i].name, name, MAX_ITEM_NAME_LENGTH);
        new_bundle->items[i].size = data_length;
        new_bundle->items[i].data = data;

        i++;
    }

    new_bundle->item_count = i;

    fclose(file);

    *bundle = new_bundle;

    return 0;
}
