char *safe_string_append(const char *input, size_t size_limit) {
    size_t input_len = strnlen(input, size_limit);

    if (input_len >= size_limit) {
        free(input); // Free any previously allocated memory for input
        return NULL;
    }

    size_t new_size = input_len + strlen("/") + 1; // Plus one for null terminator
    char *output = malloc(new_size);

    if (output == NULL) {
        free(input); // Free any previously allocated memory for input
        return NULL;
