#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

#define MAX_DNS_BUFFER_SIZE 1024

struct dns_result {
    int error_code;
    size_t ip_address_length;
    u_char ip_address[MAX_DNS_BUFFER_SIZE];
};

int dns_resolve(const char *hostname, struct dns_result *result) {
    int h_err;
    struct hostent *host_entry;

    if (!hostname) {
        result->error_code = 1;
        return -1;
    }

    host_entry = gethostbyname(hostname);

    if (!host_entry) {
        h_err = h_errno;
        result->error_code = h_err;

        if (h_err == HOST_NOT_FOUND) {
            result->error_code = 2;
        } else if (h_err == TRY_AGAIN) {
            result->error_code = 3;
        } else if (h_err == NO_RECOVERY) {
            result->error_code = 4;
        } else {
            // Unknown error
            result->error_code = 5;
        }

        return -1;
    }

    if (!host_entry->h_addr) {
        free(host_entry);
        result->error_code = 6;
        return -1;
    }

    result->ip_address_length = sizeof(struct in_addr);
    memcpy(result->ip_address, &((struct in_addr *)host_entry->h_addr)->s_addr,
           result->ip_address_length);

    free(host_entry);
    return 0;
}

int main() {
    struct dns_result result;
    int error_code;
    size_t ip_address_length;
    u_char ip_address[MAX_DNS_BUFFER_SIZE];

    error_code = dns_resolve("example.com", &result);

    if (error_code) {
        printf("Error: %d\n", error_code);
    } else {
        ip_address_length = result.ip_address_length;
        printf("IP address: ");
        for (int i = 0; i < ip_address_length; ++i) {
            printf("%.2X%s", result.ip_address[i], (i + 1) % 3 == 0 ? "\n." : "");
        }
    }

    return 0;
}

// Function to limit capabilities of the process
void set_process_capabilities(capability_t old_capabilities, capability_t new_capabilities) {
    if (new_capabilities & ~old_capabilities) {
        // Clear capabilities that are not a subset of the old capabilities
        cap_value_t old_cap_value = cap_get_value(old_capabilities);
        cap_value_t new_cap_value = cap_get_value(new_capabilities);
        cap_value_t difference = old_cap_value & ~new_cap_value;

        cap_set_flag(CAP_PERMITTED, difference, CAP_SET);
    }

    // Set new capabilities
    cap_set_flag(CAP_PERMITTED, new_capabilities, CAP_SET);
}
