#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define MAX_LINE_LENGTH 4096

bool is_comment(const char *line) {
    return (strncmp(line, "#", 1) == 0 || strncmp(line, "!", 1) == 0);
}

size_t extract_string_count(const char *line, size_t *strings_len, size_t *num_strings) {
    size_t i = 0, count = 0;
    bool in_string = false;

    while (line[i] != '\0') {
        if (line[i] == '\'' && !in_string) {
            if (++*num_strings >= MAX_STRINGS) {
                free(*strings_len);
                return 0;
            }
            *strings_len = realloc(*strings_len, (*num_strings + 1) * sizeof(char*));
            (*strings_len)[*num_strings - 1] = malloc(MAX_LINE_LENGTH);
            in_string = true;
        }
        if (in_string && line[i] != '\'' && line[i] != '\0') {
            (*strings_len)[*num_strings - 1][count++] = line[i];
        }
        i++;
    }

    if (in_string) {
        (*strings_len)[*num_strings - 1][count] = '\0';
        count++;
    }

    (*strings_len) = realloc(*strings_len, ((*num_strings) + 1) * sizeof(char*));
    (*strings_len)[*num_strings] = NULL;

    return count;
}

size_t process_file(const char *filename, size_t *num_strings, size_t *strings_len) {
    FILE *file = fopen(filename, "r");
    size_t line_length = 0, strings_count = 0, strings_index = 0;
    char line[MAX_LINE_LENGTH] = {0};

    if (!file) {
        perror("Error opening file");
        return 0;
    }

    while (fgets(line, MAX_LINE_LENGTH, file) != NULL) {
        if (is_comment(line)) continue;

        strings_count += extract_string_count(line, strings_len, num_strings);
    }

    fclose(file);

    return *num_strings;
}
