#include <stdio.h>
#include <stdlib.h>
#include "tiff.h"

void compress_tiff_data(TIFF *in_tiff, uint8 *buffer, char *out_filename) {
    TIFF *out_tiff = TIFFOpen(out_filename, "w");
    int row;
    size_t bytes_per_line;
    int sample_format;
    uint16 num_scanlines;
    uint16 rows_per_strip;
    uint16 strip_bytes;
    uint8 *out_buffer = NULL;
    int result;

    if (out_tiff == NULL) {
        TIFFError(in_tiff, "Error: Could not open output file for writing.");
        free(buffer);
        return;
    }

    if (TIFFGetField(in_tiff, TIFFTAG_IMAGEWIDTH, &bytes_per_line) != SUCCESS ||
        TIFFGetField(in_tiff, TIFFTAG_IMAGELENGTH, &num_scanlines) != SUCCESS ||
        TIFFGetField(in_tiff, TIFFTAG_SAMPLEFORMAT, &sample_format) != SUCCESS) {
        TIFFError(in_tiff, "Error: Failed to retrieve image dimensions or sample format.");
        TIFFClose(out_tiff);
        free(buffer);
        return;
    }

    rows_per_strip = TIFFDefaultStripSize(in_tiff);
    strip_bytes = rows_per_strip * bytes_per_line;

    out_buffer = malloc(strip_bytes);
    if (out_buffer == NULL) {
        TIFFError(in_tiff, "Error: Failed to allocate memory for output buffer.");
        TIFFClose(out_tiff);
        free(buffer);
        return;
    }

    for (row = num_scanlines - 1; row >= 0; row--) {
        size_t src_index = row * bytes_per_line;
        size_t dst_index = (num_scanlines - row - 1) * bytes_per_line;

        result = TIFFWriteScanline(out_tiff, buffer + src_index, row, 0);
        if (result != row) {
            TIFFError(out_tiff, "Error: Failed to write scanline to output file.");
            free(out_buffer);
            TIFFClose(out_tiff);
            free(buffer);
            return;
        }

        // Reverse the order of pixels in the buffer for this scanline
        for (size_t i = 0; i < bytes_per_line / 2; i++) {
            uint8 temp = buffer[dst_index + i];
            buffer[dst_index + i] = buffer[src_index + bytes_per_line - i - 1];
            buffer[src_index + bytes_per_line - i - 1] = temp;
        }

        // Write the reversed scanline to the output buffer
        memcpy(out_buffer, buffer + src_index, strip_bytes);

        result = TIFFWriteScanline(out_tiff, out_buffer, row, 0);
        if (result != row) {
            TIFFError(out_tiff, "Error: Failed to write compressed scanline to output file.");
            free(out_buffer);
            TIFFClose(out_tiff);
            free(buffer);
            return;
        }
    }

    TIFFClose(out_tiff);
    free(out_buffer);
    free(buffer);
}
