#include <stdint.h>
#include <stdlib.h>

#define MAX_DATASET_SIZE (UINT64_MAX / 2) // Maximum dataset size, adjust as needed
#define DISTRIBUTION_SIZE 1024 // Size of the distribution array

typedef struct {
    uint64_t size;
    uint8_t data[1];
} Block;

void calculate_average_size_and_allocate_distribution(const uint8_t* dataset, size_t dataset_size, size_t* average_size, size_t* distribution) {
    size_t total_size = 0;
    size_t num_blocks = 0;
    size_t items_per_block = 0;
    size_t reserved_size = 0;
    size_t i = 0;
    Block* blocks = NULL;

    if (dataset_size > MAX_DATASET_SIZE) {
        // Handle error: dataset size exceeds the maximum allowed
        return;
    }

    items_per_block = dataset_size / DISTRIBUTION_SIZE;
    reserved_size = dataset_size % DISTRIBUTION_SIZE;
    num_blocks = (items_per_block > 0) ? (dataset_size / items_per_block) : 0;
    num_blocks += (reserved_size > 0) ? 1 : 0;

    total_size = sizeof(Block) * num_blocks;
    blocks = (Block*) calloc(num_blocks, sizeof(Block));

    if (blocks == NULL) {
        // Handle error: memory allocation failed
        return;
    }

    for (i = 0; i < num_blocks; i++) {
        size_t block_size = (i < num_blocks - 1) ? items_per_block * sizeof(uint8_t) : items_per_block * sizeof(uint8_t) + reserved_size;
        Block* current_block = &blocks[i];

        if (i < num_blocks - 1) {
            current_block->size = items_per_block * sizeof(uint8_t);
            memcpy(current_block->data, dataset + (i * items_per_block * sizeof(uint8_t)), current_block->size);
        } else {
            current_block->size = block_size;
            memcpy(current_block->data, dataset + (i * items_per_block * sizeof(uint8_t)), reserved_size * sizeof(uint8_t));
            memset(current_block->data + reserved_size, 0, (DISTRIBUTION_SIZE - reserved_size) * sizeof(uint8_t));
        }

        total_size += current_block->size;
    }

    *average_size = total_size / num_blocks;

    // Allocate distribution array
    distribution = (size_t*) calloc(DISTRIBUTION_SIZE, sizeof(size_t));
    if (distribution == NULL) {
        // Handle error: memory allocation failed
        free(blocks);
        return;
    }

    for (i = 0; i < DISTRIBUTION_SIZE; i++) {
        size_t index = i * items_per_block;
        distribution[i] = 0;

        if (i < num_blocks - 1) {
            distribution[i] = ((size_t*) dataset)[index];
        } else {
            distribution[i] = ((size_t*) dataset)[index] + reserved_size;
        }
    }

    free(blocks);
}
