cl_command_queue create_command_queue(cl_context context, cl_device_id device_id) {
    cl_command_queue cmd_queue = NULL;
    cl_int cl_err;

    // Validate context and device ID
    if (context == NULL || device_id == NULL) {
        fprintf(stderr, "Invalid input: context or device_id is NULL\n");
        return NULL;
    }

    // Get number of devices in context
    cl_uint num_devices;
    cl_err = clGetContextInfo(context, CL_CONTEXT_NUM_DEVICES, sizeof(cl_uint), &num_devices, NULL);
    if (cl_err != CL_SUCCESS) {
        fprintf(stderr, "Error retrieving number of devices: %s\n", clGetErrorName(cl_err));
        return NULL;
    }

    // Check if device_id is valid
    cl_device_id *devices = malloc(num_devices * sizeof(cl_device_id));
    cl_err = clGetContextInfo(context, CL_CONTEXT_DEVICES, num_devices * sizeof(cl_device_id), devices, NULL);
    if (cl_err != CL_SUCCESS) {
        fprintf(stderr, "Error retrieving devices: %s\n", clGetErrorName(cl_err));
        free(devices);
        return NULL;
    }

    cl_bool is_match = CL_FALSE;
    cl_size index;
    for (index = 0; index < num_devices; index++) {
        if (device_id == devices[index]) {
            is_match = CL_TRUE;
            break;
        }
    }

    free(devices);
    if (!is_match) {
        fprintf(stderr, "Invalid device ID\n");
        return NULL;
    }

    // Create command queue
    cmd_queue = clCreateCommandQueue(context, device_id, 0, &cl_err);
    if (cl_err != CL_SUCCESS) {
        fprintf(stderr, "Error creating command queue: %s\n", clGetErrorName(cl_err));
        return NULL;
    }

    return cmd_queue;
}
