    // Add file-specific options
    tr_dictAdd(newOptionsDict, "filename", tr_variantNewString(fileInfo->filename));
    tr_dictAdd(newOptionsDict, "directory", tr_variantNewString(fileInfo->directory));

    return newOptionsDict;
}
