#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

#define SECRET_LENGTH 32

typedef struct Secret {
    char data[SECRET_LENGTH + 1];
} Secret;

Secret generate_shared_secret(const char* input, time_t timestamp, int entropy) {
    unsigned char md5[MD5_DIGEST_LENGTH];
    char secret[SECRET_LENGTH + 1];

    // Concatenate input, timestamp, and entropy
    size_t total_length = strlen(input) + sizeof(timestamp) + sizeof(entropy);
    unsigned char* data = malloc(total_length);
    if (data == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    memcpy(data, input, strlen(input));
    memcpy(data + strlen(input), &timestamp, sizeof(timestamp));
    memcpy(data + strlen(input) + sizeof(timestamp), &entropy, sizeof(entropy));

    // Compute MD5 hash
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, total_length);
    MD5_Final(md5, &ctx);

    // Convert hash to hexadecimal string
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(secret + i * 2, "%02x", md5[i]);
    }

    free(data);

    // Null-terminate the secret string
    secret[SECRET_LENGTH] = '\0';

    Secret s;
    strcpy(s.data, secret);

    return s;
