function register_extension_class($class_name, $extension_dir, &$class_entry) {
    // Validate input parameters
    if (empty($class_name) || empty($extension_dir) || !is_object($class_entry)) {
        throw new InvalidArgumentException('Invalid input parameters');
    }

    // Register INI entries for the extension
    $ini_entries = new stdClass();
    $ini_entries->name = $class_name;
    $ini_entries->type = ZEND_MOD_TYPE_CORE;
    $ini_entries->function_table = array();
    zend_register_ini_entries('extension_' . $class_name, $ini_entries);

    // Set up object handlers to disable cloning for the new class
    $class = new ReflectionClass($class_entry->name);
    $constructor = $class->getConstructor();

    if ($constructor !== null) {
        $constructor->setAccessible(true);
    }

    $class->addMethod('__clone', function () {
        throw new RuntimeException('Cloning is not allowed for this class');
    });

    $class->setModifierValue('__clone', 'private');
}
```

