    if (t->buffer == NULL) {
        perror("Memory allocation failed for log message buffer.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for arrays
    int *array = calloc(MAX_ARRAY_ELEMENTS, sizeof(int));

    if (array == NULL) {
        perror("Memory allocation failed for array.\n");
        free(t->buffer);
        exit(EXIT_FAILURE);
    }

    t->arraysize = MAX_ARRAY_ELEMENTS;

    // Log message with dimensions of buffers and arrays
    sprintf((char *)t->buffer, "Log message:\nDimensions of log message buffer: (%d, %d)\nDimensions of array: (%d)\n",
            t->dimensions[0], t->dimensions[1], t->arraysize);

    // Validate log message length before writing to file
    if (strlen(t->buffer) > available_space) {
        fprintf(stderr, "Log message is too long.\n");
        free(t->buffer);
        free(array);
        exit(EXIT_FAILURE);
    }

    // Write log message to file
    FILE *log_file = fopen("debug.log", "a");

    if (log_file == NULL) {
        perror("Failed to open log file.\n");
        free(t->buffer);
        free(array);
        exit(EXIT_FAILURE);
    }

    fwrite(t->buffer, strlen(t->buffer), 1, log_file);
    fclose(log_file);

    free(t->buffer);
    free(array);
