int parse_time(const char *input, struct tm *tm, int *timezone) {
    char time_str[32];
    char timezone_str[16];
    size_t time_len = sizeof(time_str);
    ssize_t time_pos = 0;
    ssize_t timezone_pos = 0;

    if (sscanf(input, "%s%n%[^:]+:%[^:]+:%[^:]+%n", time_str, &time_pos, timezone_str, &timezone_pos) != 3) {
