#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

#define BUFFER_SIZE 256

typedef struct line_buffer {
    size_t size;
    size_t capacity;
    char data[BUFFER_SIZE];
} line_buffer;

void push_back(line_buffer *buffer, char c) {
    if (buffer->size == buffer->capacity) {
        size_t new_capacity = buffer->capacity + BUFFER_SIZE;
        buffer->data = realloc(buffer->data, new_capacity * sizeof(char));
        buffer->capacity = new_capacity;
    }
    buffer->data[buffer->size++] = c;
}

char pop_next(line_buffer *buffer) {
    if (buffer->size == 0) {
        return '\0';
    }
    return buffer->data[--buffer->size];
}

int get_next_line(FILE *file, line_buffer *buffer) {
    char c;
    size_t i = 0;

    buffer->size = 0;
    buffer->capacity = BUFFER_SIZE;

    while ((c = fgetc(file)) != EOF && i < BUFFER_SIZE - 1) {
        push_back(buffer, c);
        i++;
    }

    if (feof(file)) {
        return EOF;
    }

    push_back(buffer, '\n');

    return i;
}

void discard_line(line_buffer *buffer) {
    size_t i = 0;

    while (i < buffer->size && buffer->data[i] != '\n') {
        i++;
    }

    buffer->size -= i;
    memmove(buffer->data, buffer->data + i, buffer->size * sizeof(char));
}
