    /* Create the dynamic thread vector. */
    dtv = malloc(static_dtv_size * sizeof(ptr_t));
    if(!dtv)
        return STATUS_NO_MEMORY;

    /* Store the current size. */
    dtv[0] = static_dtv_size;

    /* Allocate the TLS block. */
