typedef struct HelpEntry {
    char *key;
    char *description;
    struct HelpEntry *next;
} HelpEntry;

void print_help_entry(HelpEntry *entry) {
    if (entry == NULL) {
        return;
    }

    printf("Key: %s\nDescription: %s\n---\n", entry->key, entry->description);
}

bool str_equal(char *str1, char *str2) {
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);

    if (len1 != len2) {
        return false;
    }

    return strncmp(str1, str2, len1) == 0;
}

HelpEntry *search_help_list(HelpEntry *head, char *keyword) {
    HelpEntry *current = head;

    while (current != NULL) {
        pthread_mutex_lock(&current->lock);
        bool match = str_equal(current->key, keyword);
        pthread_mutex_unlock(&current->lock);

        if (match) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

void print_help_list(HelpEntry *head, char *keyword) {
    HelpEntry *match = search_help_list(head, keyword);

    if (match == NULL) {
        printf("No matching help entries found.\n");
        return;
    }

    print_help_entry(match);
}
