XRegion *reset_book_region(XRegion *region) {
    if (region == NULL) {
        return NULL;
    }

    XClearWindow(XtDisplay(region->window), region->region.x, region->region.y, region->region.width, region->region.height);

    region->booked = FALSE;
    region->booking = NULL;

    return region;
}

char *set_book_region(XRegion *region, const char *name) {
    if (region == NULL || name == NULL) {
        return NULL;
    }

    XClearWindow(XtDisplay(region->window), region->region.x, region->region.y, region->region.width, region->region.height);

    region->booked = TRUE;
    region->booking = XmStringCreate(name, XmSTRING_DEFAULT_CHARSET);

    XmStringDraw(region->booking, XtScreen(region->window), region->region.x, region->region.y, region->region.width, region->region.height, 0);

