#include <stdint.h>
#include <stdlib.h>
#include <time.h>

#define BOARD_SIZE 10

void init_board(int board[BOARD_SIZE][BOARD_SIZE], size_t size) {
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = 0; j < size; ++j) {
            board[i][j] = -1;
        }
    }
}

int find_empty_cell(const int board[BOARD_SIZE][BOARD_SIZE], size_t size) {
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = 0; j < size; ++j) {
            if (board[i][j] == -1) {
                return i * BOARD_SIZE + j;
            }
        }
    }
    return -1;
}

int place_random_number(int board[BOARD_SIZE][BOARD_SIZE], size_t size) {
    if (size == 0) {
        return -1;
    }

    int empty_cell = find_empty_cell(board, size);
    if (empty_cell == -1) {
        return -1;
    }

    int random_number;
    if (arc4random_uniform(BOARD_SIZE * BOARD_SIZE, &random_number) != 0) {
        return -1;
    }

    size_t row = random_number / BOARD_SIZE;
    size_t col = random_number % BOARD_SIZE;

    if (row >= size || col >= size || board[row][col] != -1) {
        return -1;
    }

    board[row][col] = arc4random_uniform(100, &random_number) + 1;

    return random_number;
}
