static int count_files_with_format(const char *path, const char *format, int recursive) {
    int count = 0;
    DIR *dir;
    struct dirent *entry;
    char full_path[1024];

    if (!(dir = opendir(path))) {
        return count;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);
            if (recursive && (strlen(full_path) > 2 && full_path[strlen(full_path) - 1] == '/')) {
                count += count_files_with_format(full_path + strlen(full_path) - 1, format, recursive);
            } else {
                FILE *file = fopen(full_path, "rb");
                if (file != NULL) {
                    char buffer[128];
                    size_t n = fread(buffer, 1, sizeof(buffer), file);
                    if (n > 0 && strstr(buffer, format) != NULL) {
                        count++;
                    }
                    fclose(file);
                }
            }
        }
    }

    closedir(dir);
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <format>\n", argv[0]);
        return 1;
