    if (value < 0) {
        sign = -1;
        value *= -1;
    }

    str[i++] = '0' + sign * value / base;
    value %= base;

    while (value > 0) {
        str[i++] = '0' + value / base;
        value %= base;
    }

    str[i] = '\0';

