#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_NAME_LENGTH 256
#define MAX_PATH_LENGTH 1024

struct dirent {
    char d_name[MAX_NAME_LENGTH];
};

int create_directory_entry(char *file_name, char *file_path) {
    struct dirent new_entry;
    struct stat file_stat;
    int result;

    // Validate file name and path
    if (strlen(file_name) > MAX_NAME_LENGTH || strlen(file_path) > MAX_PATH_LENGTH) {
        perror("Invalid file name or path");
        return -1;
    }

    // Copy file name and path into new_entry
    strcpy(new_entry.d_name, file_name);

    // Concatenate file name and path
    char full_path[MAX_PATH_LENGTH];
    strcpy(full_path, file_path);
    strcat(full_path, "/");
    strcat(full_path, file_name);

    // Check if file already exists
    if (stat(full_path, &file_stat) == 0) {
        fprintf(stderr, "File already exists: %s\n", full_path);
        return -1;
    }

    // Create directory entry
    result = mkdir(full_path, 0755);

    // If successful, copy new_entry into existing directory entry
    if (result == 0) {
        struct dirent *dir_entry = opendir(file_path);
        if (dir_entry != NULL) {
            struct dirent *entry = readdir(dir_entry);
            if (entry != NULL && strcmp(entry->d_name, file_name) == 0) {
                strcpy(entry->d_name, new_entry.d_name);
                closedir(dir_entry);
                return 0;
            }
            closedir(dir_entry);
        }
    }

    // If not successful, remove the created directory
    if (result != -1) {
        rmdir(full_path);
    }

    return result;
}
