#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>

#define MAX_FRAMES 1000
#define BUFFER_SIZE 4096

// Trivial generator function that returns the number of frames as its argument
uint32_t generate_frames(FILE *file, uint32_t nb_frames, int progress);

int main(int argc, char *argv[]) {
    uint32_t nb_frames = 0;
    FILE *output_file = NULL;
    int progress = 1;

    if (argc < 2 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [options] [output_file]\n", argv[0]);
        printf("Options:\n");
        printf("  --help               Display this help message and exit\n");
        printf("  --no-progress        Disable progress meter\n");
        printf("  --nb-frames=N        Generate and write N test frames to output_file\n");
        return EXIT_SUCCESS;
    }

    // Parse command line options
    while (argc > 2 && strncmp(argv[1], "--nb-frames=", 9) != 0) {
        if (strcmp(argv[1], "--no-progress") == 0) {
            progress = 0;
        }
        argv++;
        argc--;
    }

    if (argc < 2) {
        fprintf(stderr, "Error: Missing output file\n");
        return EXIT_FAILURE;
    }

    output_file = fopen(argv[1], "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        return EXIT_FAILURE;
    }

    if (progress) {
        printf("Generating and writing %u test frames to '%s'...\n", MAX_FRAMES, argv[1]);
    }

    nb_frames = generate_frames(output_file, MAX_FRAMES, progress);

    if (progress) {
        printf("%u test frames generated and written to '%s'\n", nb_frames, argv[1]);
    }

    fclose(output_file);
    return EXIT_SUCCESS;
}

// Generates and writes 'nb_frames' test frames to 'file'
// Returns the number of frames generated
uint32_t generate_frames(FILE *file, uint32_t nb_frames, int progress) {
    uint8_t buffer[BUFFER_SIZE];
    uint32_t frames_written = 0;

    for (uint32_t i = 0; i < nb_frames; i++) {
        size_t bytes_written = fwrite(buffer, sizeof(buffer), 1, file);
        if (bytes_written != 1) {
            perror("Error writing to file");
            return frames_written;
        }

        frames_written++;

        if (progress) {
            int percent = (int)((float)frames_written / nb_frames * 100.0);
            printf("\rProgress: %3d%%", percent);
            fflush(stdout);
        }
    }

    return frames_written;
}
```

