function printErrorMessage(errorValue) {
  if (!Jerry.isError(errorValue)) {
    console.error("Invalid error value.");
    Jerry.releaseValue(errorValue);
    return;
  }

  const errorMessage = Jerry.getErrorMessage(errorValue);
  const MAX_MESSAGE_LENGTH = 255;

  if (errorMessage.length > MAX_MESSAGE_LENGTH) {
    const suffix = "... (truncated)";
    const truncatedMessage = errorMessage.substring(0, MAX_MESSAGE_LENGTH - suffix.length);
    console.error(`Error message too long: ${truncatedMessage}${suffix}`);
  } else {
    console.error("Error message:", errorMessage);
  }

  Jerry.releaseValue(errorValue);
}
