```c
#include <stdio.>
#include <stdlib.>
#include <ncurses.h>
#include <pthread.h>

#define PROGRESS_BAR_HEIGHT 3
#define PROGRESS_BAR_WIDTH 50
#define PROGRESS_BAR_X 10
#define PROGRESS_BAR_Y 10

struct progress_bar {
    WINDOW *progress_bar_window;
    int percentage;
    pthread_mutex_t lock;
};

void init_progress_bar(struct progress_bar *progress_bar) {
    progress_bar->progress_bar_window = newwin(PROGRESS_BAR_HEIGHT, PROGRESS_BAR_WIDTH, PROGRESS_BAR_Y, PROGRESS_BAR_X);
    if (!progress_bar->progress_bar_window) {
        fprintf(stderr, "Error creating progress bar window\n");
        exit(-1);
    }

    draw_box(progress_bar->progress_bar_window, 0, 0, PROGRESS_BAR_HEIGHT, PROGRESS_BAR_WIDTH, dialog_attr, border_attr);
    draw_shadow(stdscr, PROGRESS_BAR_Y, PROGRESS_BAR_X, PROGRESS_BAR_HEIGHT, PROGRESS_BAR_WIDTH);

    progress_bar->lock = PTHREAD_MUTEX_INITIALIZER;
}

void display_progress_bar(struct progress_bar *progress_bar, int percentage) {
    pthread_mutex_lock(&progress_bar->lock);
    progress_bar->percentage = percentage;

    wmove(progress_bar->progress_bar_window, 5, (PROGRESS_BAR_WIDTH-3)/2);
    wclrtoeol(progress_bar->progress_bar_window);
    wprintw(progress_bar->progress_bar_window, "%3d%%", percentage);

    int progress_bar_width = (PROGRESS_BAR_WIDTH-6) * percentage / 100;
    wmove(progress_bar->progress_bar_window, 3, 3);
    wclrtoeol(progress_bar->progress_bar_window);
    wprintw(progress_bar->progress_bar_window, "[");
    wmove(progress_bar->progress_bar_window, 3, PROGRESS_BAR_WIDTH - progress_bar_width - 2);
    wprintw(progress_bar->progress_bar_window, "]");

    wrefresh(progress_bar->progress_bar_window);
    pthread_mutex_unlock(&progress_bar->lock);
}

void cleanup_progress_bar(struct progress_bar *progress_bar) {
    delwin(progress_bar->progress_bar_window);
}

int main() {
    initscr();
    raw();
    keypad(stdscr, TRUE);
    noecho();

    struct progress_bar progress_bar;
    init_progress_bar(&progress_bar);

    int total_work = 100;
    int current_work = 0;

    while (current_work < total_work) {
        current_work += 10;
        display_progress_bar(&progress_bar, current_work);
        usleep(100000); // simulate work
    }

    display_progress_bar(&progress_bar, 100);
    cleanup_progress_bar(&progress_bar);

    endwin();

    return 0;
}
```

This code initializes a progress bar using curses library functions and a mutex to ensure proper synchronization when updating the progress bar. The progress bar is displayed with its percentage complete, and the window is refreshed after each update. The progress bar is properly cleaned up when the function exits. The code also simulates work by using a sleep statement in the main loop, but in a real-world scenario, this work would be performed in another thread or process.

