#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RESPONSE_SIZE 4096

typedef struct {
    int http_code;
    int error_counter;
    pthread_mutex_t mutex;
} HttpResponseParser;

void init_parser(HttpResponseParser *parser) {
    pthread_mutex_init(&parser->mutex, NULL);
    parser->error_counter = 0;
}

void parse_response(HttpResponseParser *parser, const char *response) {
    int status_code_len = 3;
    char status_code[status_code_len + 1];
    int i;

    pthread_mutex_lock(&parser->mutex);

    for (i = 0; i < MAX_RESPONSE_SIZE && response[i] != '\0'; i++) {
        if (i < status_code_len && isdigit(response[i])) {
            status_code[i] = response[i];
        } else if (i >= status_code_len && response[i] == ' ') {
            status_code[i] = '\0';
            break;
        }
    }

    if (i < status_code_len) {
        parser->error_counter++;
        fprintf(stderr, "Warning: Invalid HTTP response code: %.*s\n", (int)(i + 1), response);
    } else {
        parser->http_code = atoi(status_code);
        if (parser->http_code < 200 || parser->http_code > 299) {
            parser->error_counter++;
            fprintf(stderr, "Warning: Non-2xx HTTP response code: %d\n", parser->http_code);
        }
    }

    pthread_mutex_unlock(&parser->mutex);
}

int is_valid_response(HttpResponseParser *parser) {
    pthread_mutex_lock(&parser->mutex);
    int ret = parser->http_code >= 200 && parser->http_code <= 299;
    pthread_mutex_unlock(&parser->mutex);
    return ret;
}

int get_error_counter(HttpResponseParser *parser) {
    pthread_mutex_lock(&parser->mutex);
    int counter = parser->error_counter;
    pthread_mutex_unlock(&parser->mutex);
    return counter;
}

void destroy_parser(HttpResponseParser *parser) {
    pthread_mutex_destroy(&parser->mutex);
}
