#include <stdlib.h> // for realloc
#include <string.h> // for memmove and strlen

char *safe_trim_and_append(char *input, size_t *input_len) {
    size_t len = *input_len;
    size_t i;

    // Check input string for null pointer
    if (input == NULL) {
        return NULL;
    }

    // Trim newline and carriage return characters
    for (i = len - 1; i > 0 && (input[i] == '\r' || input[i] == '\n'); --i) {
        memmove(&input[i], &input[i - 1], len - i);
        --len;
    }

    // Allocate new memory for the appended newline character
    char *new_input = realloc(input, len + 1);
    if (new_input == NULL) {
        free(input);
        return NULL;
    }

    input = new_input;

    // Append a newline character
    input[len++] = '\n';
    input[len] = '\0';

    // Update input length
    *input_len = len;

    return input;
}
