        goto error;
    }

    /* Write table image data to the file */
    ret = write(file_fd, data, data_size);
    if (ret != data_size) {
        perror("Error writing table image data to file");
        goto error;
    }

    close(header_fd);
    close(file_fd);
    ret = 0;

error:
    if (file_fd >= 0) close(file_fd);
    if (header_fd >= 0) close(header_fd);
    return ret;
