#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_BUFFER_SIZE 1024

typedef enum Rule {
    RULE_NONE,
    RULE_UPPERCASE,
    RULE_LOWERCASE,
    RULE_REVERSE
} Rule;

void apply_rule(char *str, Rule rule) {
    size_t i;
    for (i = 0; str[i] != '\0'; i++) {
        if (rule == RULE_UPPERCASE) {
            str[i] = (char)toupper((unsigned char)str[i]);
        } else if (rule == RULE_LOWERCASE) {
            str[i] = (char)tolower((unsigned char)str[i]);
        } else if (rule == RULE_REVERSE) {
            str[i] = str[strlen(str) - i - 1];
        }
    }
}

int process_file(const char *input_file, const char *output_file, const char *rules_str) {
    FILE *input_fp = NULL, *output_fp = NULL;
    char buffer[MAX_BUFFER_SIZE];
    char *rules = strdup(rules_str);
    Rule current_rule = RULE_NONE;
    size_t rules_len = strlen(rules);
    int ret = 0;

    input_fp = fopen(input_file, "rb");
    if (input_fp == NULL) {
        perror("Error opening input file");
        goto error;
    }

    output_fp = fopen(output_file, "wb");
    if (output_fp == NULL) {
        perror("Error opening output file");
        goto error;
    }

    while (fgets(buffer, MAX_BUFFER_SIZE, input_fp) != NULL) {
        size_t len = strlen(buffer);
        if (rules_len > len) {
            current_rule = (Rule)(rules[len]);
            apply_rule(buffer, current_rule);
        }
        fwrite(buffer, len + 1, 1, output_fp);
    }

    free(rules);
    fclose(input_fp);
    fclose(output_fp);

error:
    if (output_fp != NULL) {
        fclose(output_fp);
    }
    if (input_fp != NULL) {
        fclose(input_fp);
    }
    return ret;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules>\n", argv[0]);
        return 1;
    }

    int ret = process_file(argv[1], argv[2], argv[3]);
    return ret;
}
