typedef struct {
    unsigned char data[SHA_DIGEST_LENGTH];
} sha1_checksum;

int calculate_sha1_checksum(const unsigned char *buffer, size_t buffer_length, sha1_checksum *checksum) {
    SHA_CTX sha1_context;

    // Initialize SHA-1 context
    SHA1_Init(&sha1_context);

    // Update SHA-1 context with buffer data
    SHA1_Update(&sha1_context, buffer, buffer_length);

    // Get SHA-1 checksum
    SHA1_Final(checksum->data, &sha1_context);

