#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAX_LINE_LENGTH 80
#define MAX_BUFFER_SIZE 1024

void display_message(const char *message, int importance) {
    size_t message_len = strlen(message);
    char buffer[MAX_BUFFER_SIZE];
    char *current_line = buffer;
    int remaining_space = MAX_LINE_LENGTH;
    int line_break_needed = 0;

    if (importance > 5) {
        printf("\033[1;31m"); // Set color to red for high importance messages
    }

    if (message_len > MAX_LINE_LENGTH) {
        // Handle messages that don't fit on the current line
        while (*message) {
            size_t space_needed = strlen(current_line) + strlen(message) + 1;
            if (space_needed > MAX_LINE_LENGTH) {
                // Display the current line and start a new one
                if (current_line != buffer) {
                    printf("%s\n", current_line);
                }
                current_line = buffer + strlen(buffer);
                remaining_space = MAX_LINE_LENGTH;
            }

            strncpy(current_line, message, remaining_space - 1);
            current_line += strlen(message);
            *current_line = '\0';
            message += strlen(message);

            if (*message) {
                // Add a space between messages, except for the last one
                if (message[1] != '\0') {
                    *current_line++ = ' ';
                    remaining_space--;
                }
            }

            line_break_needed = 1;
        }
    } else {
        // Display the message on the current line without line wrapping
        strncpy(buffer, message, MAX_LINE_LENGTH);
        buffer[MAX_LINE_LENGTH] = '\0';
        printf("%s\n", buffer);
    }

    if (importance > 5) {
        printf("\033[0m"); // Reset color to default
    }

    if (line_break_needed) {
        printf("\033[A"); // Move the cursor up one line
        printf("\033[K"); // Clear the current line
    }
}
```

