    return (uint64_t)value % order;
}

size_t hashmask(size_t order) {
    return order - 1;
}

bool hashtable_init(hashtable_t *hashtable) {
    hashtable->buckets = calloc(HASH_TABLE_SIZE, sizeof(bucket_t));
    if (!hashtable->buckets)
        return false;

    return true;
}

pair_t *hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
