#define CHUNK_SIZE 1024

// Density-based compression safe size calculation
uint64_t density_compress_safe_size(uint64_t uncompressed_size) {
    uint64_t safe_size = uncompressed_size;
    safe_size += (safe_size >> 1) + (safe_size >> 2);
    return safe_size;
}

// Density-based compression function
uint8_t* density_compress(const char* input_file_path, uint64_t* compressed_size) {
