#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <sys/mman.h> // For vm_iomap_memory

#define RECORD_COUNT 100
#define LONG_ARRAY_SIZE (RECORD_COUNT * sizeof(long))
#define INT_ARRAY_SIZE (RECORD_COUNT * sizeof(int))
#define RECORD_SIZE sizeof(struct record)

typedef struct record {
    int key;
    int value;
} record;

bool check_memory(void *ptr, size_t size) {
    if (ptr == NULL) {
        perror("Memory allocation failed.");
        return false;
    }

    if (munmap(ptr, size) < 0) {
        perror("Failed to free memory.");
        return false;
    }

    return true;
}

void init_arrays(long *long_array, int *int_array) {
    long_array = vm_iomap_memory(LONG_ARRAY_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    int_array = vm_iomap_memory(INT_ARRAY_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (!check_memory(long_array, LONG_ARRAY_SIZE) || !check_memory(int_array, INT_ARRAY_SIZE)) {
        return;
    }

    memset(long_array, 0, LONG_ARRAY_SIZE);
    memset(int_array, 0, INT_ARRAY_SIZE);
}

void init_records(record *records) {
    records = calloc(RECORD_COUNT, sizeof(record));

    if (records == NULL) {
        perror("Failed to allocate memory for records.");
        exit(EXIT_FAILURE);
    }

    memset(records, 0, RECORD_COUNT * sizeof(record));
}

void set_random_values(record *records) {
    srand(time(NULL));

    for (size_t i = 0; i < RECORD_COUNT; i++) {
        records[i].key = i;
        records[i].value = rand() % 10 + 1;
    }
}

