    int *int_array = NULL;
    record *records = NULL;

    init_arrays(long_array, int_array);
    init_records(records);

    set_random_values(records);

    // Use the arrays as needed

    check_memory(long_array, LONG_ARRAY_SIZE);
    check_memory(int_array, INT_ARRAY_SIZE);
    check_memory(records, RECORD_COUNT * sizeof(record));

    return 0;
}
