int mqtt_exponential_backoff(struct mqtt_client *context) {
    static bool first_time = true; // Flag to check if it's the first retry
    static uint32_t base_delay = 100; // Base delay for backoff in milliseconds
    static uint32_t max_delay = 5000; // Maximum delay for backoff in milliseconds
