void safe_insert_line(HWND hWnd, const char *new_line) {
    HANDLE hFile;
    LPSTR lpText;
    size_t len, pos, new_len;

    // Get the current text in the edit control
    hFile = _get_ptext(hWnd);
    if (hFile == HANDLE_ERROR) {
        // Handle error
        return;
    }

    fseek(hFile, 0, SEEK_END);
    len = ftell(hFile);
    rewind(hFile);

    // Allocate memory for the new text
    lpText = (LPSTR) malloc(len + strlen(new_line) + 2); // +2 for '\r\n'
    if (!lpText) {
        // Handle memory allocation error
        fcloseall();
        return;
    }

    // Read the current text into the new buffer
    fread(lpText, 1, len, hFile);
    fclose(hFile);

    // Calculate the new length and position
    pos = _get_textlength(hWnd);
    new_len = strlen(lpText) + strlen(new_line) + pos + 1;

    // Insert the new line at the current position
    memmove(lpText + pos + strlen(new_line), lpText + pos, strlen(lpText) + 1);
    strcat(lpText, new_line);
    strcat(lpText, "\r\n");

