#include <des.h> // Assuming you have the DES library installed

void encryptDES(unsigned char key[3][KEYSIZE], unsigned char plaintext[PLAINTEXT_LENGTH], unsigned char result[3][BLOCK_SIZE]) {
    unsigned char iv[BLOCK_SIZE] = {0}; // Initialize IV with zeros
    DES_cblock tplaintext[PLAINTEXT_LENGTH / 8]; // Initialize plaintext block
    DES_cblock tkey[2]; // Initialize key block
    DES_cblock tresult[3]; // Initialize result block
    int i;

    // Initialize key
    for (i = 0; i < 3; i++) {
        memcpy(tkey[i / 8], key[i], KEYSIZE);
    }

    // Initialize plaintext
    for (i = 0; i < PLAINTEXT_LENGTH / 8; i++) {
        memcpy(tplaintext[i], plaintext + i * 8, 8);
    }

    // Encrypt each block in ECB mode
    for (i = 0; i < 3; i++) {
        DES_set_iv(des_ede3_cbc(), iv); // Set IV to zeros for ECB mode
        DES_encrypt3_cbc(des_ede3_cbc(), tkey, tplaintext[i], tresult[i], NULL);
        memcpy(result[i], tresult[i], BLOCK_SIZE);
    }
}
