#if defined(_WIN32) || defined(_WIN64)
#define CODEPAGE_LENGTH 32
static char codepage[CODEPAGE_LENGTH];
int get_codepage(char *buffer, size_t size) {
    GetLocaleInfoA(LOCALE_SYSTEM_DEFAULT, LOCALE_ILANGUID, codepage, CODEPAGE_LENGTH);
    strncpy(buffer, codepage, size);
    return strlen(codepage);
}
