#include <vector>

void generateWireframeIndices(const int* inputArray, size_t size, int*& points, int*& lines, int*& faces, int*& lineWireframe, std::vector<int>& primitivesCounter) {
    std::vector<int> tempIndices(3 * size); // Preallocate memory for temporary indices

    points = new int[3 * size];
    lines = new int[2 * size];
    faces = new int[3 * size];
    lineWireframe = new int[2 * size];

    for (size_t i = 0; i < size; ++i) {
        points[3 * i] = i;
        points[3 * i + 1] = i + 1;
        points[3 * i + 2] = i + 1;

        tempIndices[3 * i] = i;
        tempIndices[3 * i + 1] = i + 1;
        tempIndices[3 * i + 2] = i;
        lines[2 * i] = i;
        lines[2 * i + 1] = i + 1;

        for (size_t j = i + 1; j < size; ++j) {
            tempIndices[3 * i + 1] = j;
            tempIndices[3 * j] = i;
            tempIndices[3 * j + 1] = j;
            lines[2 * i + 1] = j;
            lines[2 * j] = i;

            if (i < j && j < size - 1 && i + 1 < size && j + 1 < size) {
                faces[3 * (primitivesCounter.size())] = i;
                faces[3 * (primitivesCounter.size()) + 1] = j;
                faces[3 * (primitivesCounter.size()) + 2] = j + 1;
                faces[3 * (primitivesCounter.size()) + 3] = i + 1;
                primitivesCounter.push_back(3);
            }
        }
    }

    std::copy(tempIndices.begin(), tempIndices.end(), std::begin(points) + 3 * size);
    std::copy(lines, lines + 2 * size, lineWireframe);
}
