#include <cerrno>

const int MAX_CONNECTIONS = 10;
const int MAX_QUEUE_SIZE = 100;

struct Connection {
    int sockfd;
    struct sockaddr_in addr;
    std::deque<char> rx_queue;
    std::mutex rx_mutex;
    bool connected = false;
};

std::deque<Connection> connections;
std::mutex connections_mutex;

void handle_connection(Connection& conn) {
    char rx_buf[4096];
    int bytes_received;
    while (true) {
        if (!conn.connected) {
            continue;
        }

        bytes_received = recv(conn.sockfd, rx_buf, sizeof(rx_buf), 0);
        if (bytes_received <= 0) {
            if (bytes_received == EOF) {
                close(conn.sockfd);
                connections_mutex.lock();
                connections.pop_back();
                connections_mutex.unlock();
                break;
            } else {
                perror("recv()");
                close(conn.sockfd);
                connections_mutex.lock();
                connections.pop_back();
                connections_mutex.unlock();
                break;
            }
        }

        std::lock_guard<std::mutex> lock(conn.rx_mutex);
        conn.rx_queue.push_back(rx_buf[0]);
    }
}

void accept_connections() {
    int listener_sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (listener_sockfd < 0) {
        perror("socket()");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in listener_addr;
    memset(&listener_addr, 0, sizeof(listener_addr));
    listener_addr.sin_family = AF_INET;
    listener_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    listener_addr.sin_port = htons(8080);

    if (bind(listener_sockfd, (struct sockaddr *) &listener_addr, sizeof(listener_addr)) < 0) {
        perror("bind()");
        close(listener_sockfd);
        exit(EXIT_FAILURE);
    }

    if (listen(listener_sockfd, MAX_CONNECTIONS) < 0) {
        perror("listen()");
        close(listener_sockfd);
        exit(EXIT_FAILURE);
    }

    while (true) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int new_sockfd = accept(listener_sockfd, (struct sockaddr *) &client_addr, &client_len);
        if (new_sockfd < 0) {
            perror("accept()");
            continue;
        }

        Connection new_conn;
        new_conn.sockfd = new_sockfd;
        new_conn.addr = client_addr;
        connections_mutex.lock();
        connections.push_back(new_conn);
        connections_mutex.unlock();

        std::thread thread(handle_connection, ref(new_conn));
        thread.detach();
    }
}

int main() {
    accept_connections();
    return 0;
}
