namespace fs = std::filesystem;

// Function to read descriptors from a file
std::vector<uint8_t> readDescriptors(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    std::vector<uint8_t> descriptors;
    descriptors.assign((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    return descriptors;
}

// Function to check if a path is within a safe directory
bool isSafePath(const std::string& basePath, const std::string& filePath) {
    fs::path absPath(filePath);
    absPath = absPath.relative_to(fs::path(basePath));
    return absPath.string().find("../") == std::string::npos;
}

// Function to load descriptors from files and store them in a 2D matrix
std::vector<std::vector<uint8_t>> loadDescriptors(const std::vector<std::string>& filePaths, bool includeAlpha) {
    size_t numFiles = filePaths.size();
    size_t numDescriptors = 0;
    std::vector<std::vector<uint8_t>> descriptorsMatrix(numFiles, std::vector<uint8_t>(DescriptorsSize, 0));

    for (size_t i = 0; i < numFiles; ++i) {
        std::string filePath = filePaths[i];
        if (isSafePath(SafeBasePath, filePath)) {
            std::vector<uint8_t> descriptors = readDescriptors(filePath);
            if (descriptors.size() != DescriptorsSize) {
                std::cerr << "Invalid descriptor size in file: " << filePath << std::endl;
                continue;
            }

            if (includeAlpha) {
                size_t alphaSize = DescriptorsSize * 2;
                if (descriptors.size() < alphaSize) {
                    std::cerr << "Missing alpha channel data in file: " << filePath << std::endl;
                    continue;
                }
                descriptors.resize(alphaSize);
                descriptorsMatrix[i].assign(descriptors.begin() + DescriptorsSize, descriptors.end());
