#include <vector>
#include <list>
#include <algorithm>
#include <atomic>

std::map<int, int> counting_sort(const std::list<int>& input) {
    std::map<int, int> countingMap;
    std::vector<int> bucket(input.size());

    std::atomic<int> total{0}; // Atomic counter for the total number of elements

    std::for_each(input.begin(), input.end(), [&](const int element) {
        countingMap[element]++;
        total++;
    });

    std::for_each(input.begin(), input.end(), [&](const int element) {
        bucket[countingMap[element] - 1] = element;
        countingMap[element]--;
    });

    std::list<int> sortedList(bucket.begin(), bucket.begin() + total);

    return countingMap;
}
