typedef void (*connection_callback)(int socket_fd);

int init_library() {
    int library_initialized = 0;
    if (initialize_library(&library_initialized) < 0) {
        fprintf(stderr, "Library initialization failed.\n");
        exit(EXIT_FAILURE);
    }
    return library_initialized;
}

int establish_connection(const char *hostname, int port, connection_callback callback) {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Failed to create socket.");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(port);

    if (inet_pton(AF_INET, hostname, &server_address.sin_addr) <= 0) {
        perror("Invalid server address.");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    if (connect(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Failed to connect to the server.");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    callback(socket_fd);

    close(socket_fd);

    return EXIT_SUCCESS;
}

void display_error_message(const char *message) {
    size_t message_length = strlen(message);
    char error_message[MAX_ERROR_MESSAGE_LENGTH];

