#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <limits.h>

#define MAX_NODES 1000

typedef struct {
    int num_nodes;
    bool *visited;
    int *component;
} graph_t;

void init_graph(graph_t *graph, int num_nodes) {
    graph->num_nodes = num_nodes;
    graph->visited = calloc(num_nodes, sizeof(bool));
    graph->component = calloc(num_nodes, sizeof(int));
    for (int i = 0; i < num_nodes; ++i) {
        graph->component[i] = -1;
    }
}

void free_graph(graph_t *graph) {
    free(graph->visited);
    free(graph->component);
}

bool valid_edge(const char *str, int num_nodes) {
    if (strlen(str) != 3 || (str[0] < 'A' || str[0] > 'Z' + num_nodes) ||
        (str[1] != '-' && str[1] != ' ') ||
        (str[2] < 'A' || str[2] > 'Z' + num_nodes)) {
        return false;
    }
    return true;
}

int build_graph(graph_t *graph, const char *str, int num_nodes) {
    int node1 = str[0] - 'A';
    int node2 = str[2] - 'A';

    if (node1 >= 0 && node1 < num_nodes && node2 >= 0 && node2 < num_nodes) {
        if (!graph->visited[node1]) {
            dfs(graph, node1, node1);
            graph->component[node1] = graph->num_components++;
        }

        if (!graph->visited[node2]) {
            graph->adj_matrix[node1][node2] = 1;
            graph->adj_matrix[node2][node1] = 1;
            dfs(graph, node2, node1);
        }

        return graph->num_components;
    }

    return -1;
}

void dfs(graph_t *graph, int node, int parent) {
    graph->visited[node] = true;

    for (int i = 0; i < graph->num_nodes; ++i) {
        if (graph->adj_matrix[node][i] && i != parent) {
            dfs(graph, i, node);
        }
    }
}

