    for (int i = 0; i < num_edges; ++i) {
        char str[10];
        scanf("%s", str);

        int result = build_graph(&graph, str, num_nodes);
        if (result >= 0) {
            connected_components++;
        }
    }

    free_graph(&graph);
    printf("%d\n", connected_components);

    return 0;
}
