#include <cstring>
#include <stdexcept>
#include <string>
#include <netdb.h>
#include <arpa/inet.h>

std::string HostAddressToString(const HostAddress& address) {
    if (!address.isValid()) {
        throw std::invalid_argument("Invalid address");
    }

    char ipv4[INET_ADDRSTRLEN];
    char ipv6[INET6_ADDRSTRLEN];

    if (address.isIPv4()) {
        inet_ntop(AF_INET, &address.toIPv4().s_addr, ipv4, sizeof(ipv4));
        return std::string(ipv4);
    } else {
