    return std::rand();
}

// Function to calculate the index of a cell in a toroidal grid
int index(int x, int y, int width) {
    int idx = x + y * width;
    if (x < 0) idx += width * (abs(x) % width);
    if (y < 0) idx += width * (abs(y) % width);
    return idx;
}

// Function to generate a unique identifier for a cell in a toroidal grid
int generate_cell_identifier(int x, int y) {
    // Validate input parameters
    if (x < 0 || x >= GRID_WIDTH || y < 0 || y >= GRID_HEIGHT) {
