#include <vector>
#include <string>
#include <cstring>
#include <cstdlib>

std::vector<std::string> extractTokens(const char* buffer, size_t bufferSize, const char* delimiter, const char specialValue) {
    std::vector<std::string> tokens;
    size_t pos = 0;
    size_t len = 0;
    char token[bufferSize];

    while (pos < bufferSize) {
        // Find the next token or special value
        len = std::strcspn(buffer + pos, delimiter);
        if (len > 0 && (buffer[pos + len] != specialValue || (len < bufferSize - 1 && buffer[pos + len + 1] != *delimiter))) {
            // If this is not a special value, add the token to the vector
            tokens.push_back(std::string(buffer + pos, len));
        }

        // Move the read position to the next token or special value
        pos += len + (len < bufferSize - 1 && buffer[pos + len] != specialValue ? 1 : len + 1);
    }

    return tokens;
}
