#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <openssl/md5.h>

int validate_input(const unsigned char *input, size_t length) {
    if (length < 32) {
        return -2;
    }
    if (length > 64) {
        return -3;
    }
    return 0;
}

int hash_input(const unsigned char *input, size_t length, unsigned char output[16]) {
    if (validate_input(input, length) < 0) {
        return -1;
    }

    MD5_CTX md5;
    MD5_Init(&md5);
