class gles_error : public std::runtime_error {
public:
    gles_error(const char* message) : std::runtime_error(message) {}
};

GLuint create_shader(GLenum shader_type, const std::string& source) {
    GLuint shader = glCreateShader(shader_type);

    if (shader == GL_INVALID_VALUE) {
        throw gles_error("Error creating shader: GL_INVALID_VALUE");
    }

    const GLsizei source_length = static_cast<GLsizei>(source.length());
    glShaderSource(shader, 1, &source.c_str(), NULL);

    GLint is_shader_compiled = GL_FALSE;
    glCompileShader(shader);

    glGetShaderiv(shader, GL_COMPILE_STATUS, &is_shader_compiled);

    if (!is_shader_compiled) {
        GLint info_log_length = 0;
        glGetShaderiv(shader, GL_INFO_LOG_LENGTH, &info_log_length);

        if (info_log_length > 0) {
            std::unique_ptr<char[]> info_log(new char[info_log_length]);
            glGetShaderInfoLog(shader, info_log_length, NULL, info_log.get());

            glDeleteShader(shader);
            throw gles_error(info_log.get());
        }
    }

    return shader;
}
