size_t message_append(unsigned char* toSign, const char* message) {
    size_t len = strlen(message);
    toSign = realloc(toSign, sizeof(unsigned char) * (sizeof(unsigned char) * (1 + len) + 1));
    memcpy(toSign + sizeof(unsigned char) * (1 + len), message, len);
    toSign[sizeof(unsigned char) * (1 + len)] = '\0';
