size_t hmac_sha256(unsigned char* message, size_t message_len, const unsigned char* key, size_t key_len, unsigned char* output) {
    HMAC_CTX ctx;
    int ret;

    HMAC_Init_ex(&ctx, key, key_len, EVP_sha256(), NULL);
    ret = HMAC_Update(&ctx, message, message_len);
    if (ret < 0) {
        fprintf(stderr, "Error: HMAC initialization failed.\n");
        exit(EXIT_FAILURE);
    }
    ret = HMAC_Final(output, &ctx);
    if (ret < 0) {
        fprintf(stderr, "Error: HMAC computation failed.\n");
        exit(EXIT_FAILURE);
    }
    return EVP_MD_size(EVP_sha256());
}

size_t base64_encode(unsigned char* output, const unsigned char* input, size_t length) {
    BIO *bio, *b64;
    BUF_MEM *bptr;

    bio = BIO_new(BIO_s_mem());
    b64 = BIO_new(BIO_f_base64());
    bptr = BUF_MEM_new(length * 3);

