const size_t SHA1_DIGEST_LENGTH = 20;

std::string kdf2_sha1(const std::string& password,
                      const std::string& master_key,
                      size_t output_length) {
  std::unique_ptr<EVP_CIPHER_CTX, decltype(&EVP_CIPHER_CTX_free)> kdf_ctx(
      EVP_KDF_CTX_new(), EVP_CIPHER_CTX_free);

