#include <stdio.h>
#include <stdlib.h>
#include <string.h>

size_t CountLines(const char *filename) {
    FILE *file;
    size_t lines = 0;
    char c;

    if (!(file = fopen(filename, "r"))) {
        perror("Error opening file");
        return 0;
    }

    while (fgetc(file) != EOF) {
        if (++lines == 0 && feof(file)) {
            break;
        }
    }

    fclose(file);

    return lines;
}

