#include <vector>
#include <random>
#include <cinttypes>

static int64_t FindBestCombination(const std::vector<std::pair<int64_t, bool>>& values, int64_t target) {
    std::vector<bool> selected(values.size(), false);
    int64_t current_sum = 0;

    std::mt19937 engine; // Use a cryptographically secure random number generator
    std::uniform_int_distribution<std::mt19937::result_type> distribution(0, values.size() - 1);

    for (size_t iteration = 0; current_sum <= target && iteration < 1000; ++iteration) {
        size_t index = distribution(engine);

        if (!selected[index]) {
            current_sum += values[index].first;
            selected[index] = true;
        }
    }

    if (current_sum > target) {
        for (size_t i = values.size() - 1; i > 0; --i) {
            if (selected[i]) {
                current_sum -= values[i].first;
                selected[i] = false;
            }
            if (current_sum <= target) {
                break;
            }
        }
    }

    if (current_sum == target) {
        return current_sum;
    }

    return -1;
}
