#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define SERVER_NAME_REGEX "^[^:]+(?=:|$)"

typedef struct {
    char *server_name;
    char *password;
} server_info_t;

server_info_t extract_server_info(const char *input) {
    server_info_t result = {NULL, NULL};
    size_t server_name_len = 0;
    size_t password_start = 0;
    size_t password_len = 0;

    // Validate input string is not empty
    if (!input || strlen(input) < 2) {
        free(result.server_name);
        free(result.password);
        return (server_info_t){NULL, NULL};
    }

    // Extract server name using regex
    regmatch_t match;
    regex_t regex;
    int rc = regcomp(&regex, SERVER_NAME_REGEX, REG_EXTENDED);
    if (rc) {
        free(result.server_name);
        free(result.password);
        regfree(&regex);
        perror("Error compiling regular expression");
        exit(EXIT_FAILURE);
    }

    rc = regexec(&regex, input, 1, &match, 0);
    if (rc == REG_NOMATCH) {
        free(result.server_name);
        free(result.password);
        regfree(&regex);
        perror("Error extracting server name");
        exit(EXIT_FAILURE);
    }

    server_name_len = match.rm_eo - match.rm_so;
    result.server_name = malloc(server_name_len + 1);
    strncpy(result.server_name, input + match.rm_so, server_name_len);
    result.server_name[server_name_len] = '\0';

    // Extract password, if present
    password_start = match.rm_eo;
    while (input[password_start] != ':' && password_start < strlen(input)) {
        password_start++;
    }

    if (password_start < strlen(input)) {
        password_len = strlen(input + password_start + 1);
        result.password = malloc(password_len + 1);
        strncpy(result.password, input + password_start + 1, password_len);
        result.password[password_len] = '\0';
    }

    regfree(&regex);
    return result;
}
