#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRING_LENGTH 1024

typedef struct {
    int width;
    int height;
    double frame_rate;
    int gop_size;
    int keyint_min;
    int pts_timebase_num;
    int pts_timebase_den;
    int codec_id;
} VideoConfig;

