void generate_video_config_string(const VideoConfig *config, FILE *log_file) {
    char width_str[16], height_str[16], framerate_str[32], gopsize_str[16], keyint_str[16];
    char aspect_ratio_str[32], frame_count_str[16], seek_info_str[128];
    int i;

    snprintf(width_str, sizeof(width_str), "%d", config->width);
    snprintf(height_str, sizeof(height_str), "%d", config->height);
    snprintf(framerate_str, sizeof(framerate_str), "%.2f", config->frame_rate);
    snprintf(gopsize_str, sizeof(gopsize_str), "%d", config->gop_size);
    snprintf(keyint_str, sizeof(keyint_str), "%d", config->keyint_min);

    // Calculate aspect ratio
    double aspect_ratio = (double)config->width / (double)config->height;
    snprintf(aspect_ratio_str, sizeof(aspect_ratio_str), "%.2f:%.2f", 1.0, aspect_ratio);

    // Calculate frame count
    int frame_count = config->width * config->height * config->gop_size;
    snprintf(frame_count_str, sizeof(frame_count_str), "%d", frame_count);

    // Calculate seek information
    int seek_pts_num = config->pts_timebase_num * config->keyint_min;
    int seek_pts_den = config->pts_timebase_den * config->keyint_min;
    snprintf(seek_info_str, sizeof(seek_info_str), "seek_pts=%d/%d", seek_pts_num, seek_pts_den);

