    {
        x265_log(NULL, X265_LOG_ERROR, "vmaf data alloc failed\n");
        return true;
    }
#endif

    if (api->param_default_preset(param, preset, tune) < 0)
    {
        x265_log(NULL, X265_LOG_ERROR, "preset or tune unrecognized\n");
        return true;
    }

    if (bShowHelp)
    {
        printVersion(param, api);
        showHelp(param);
