#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

struct Option {
    std::string key;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& input) {
    std::vector<Option> options;
    std::istringstream iss(input);
    std::string optionStr;

    while (std::getline(iss, optionStr, ',')) {
        if (optionStr.empty()) {
            throw std::invalid_argument("Malformed options string: empty option");
        }

        std::stringstream optionStream(optionStr);
        std::string key, value;

        if (!(std::getline(optionStream, key, ':'))) {
