#define MAX_NAME_LENGTH 100

// Helper function to validate read operation within bounds
bool is_read_within_bounds(const unsigned char *s, size_t size, size_t max_size) {
    return (s <= (const unsigned char *)malloc(max_size) && (s + size) <= (const unsigned char *)malloc(max_size));
}

int main() {
    char name[MAX_NAME_LENGTH];
    size_t name_len = 0;
    bool read_success = false;

    printf("Please enter your name: ");
    read_success = fgets(name, sizeof(name), stdin) != NULL;

    if (!read_success) {
        perror("Error reading input");
        return 1;
    }

    // Remove newline character from fgets input
    name[strcspn(name, "\n")] = '\0';

    // Calculate length using switch statement for first character and while loop for remaining characters
    unsigned char first_char = name[0];
    int length = 0;

    switch (first_char) {
        case '\0':
            length = 0;
            break;
        case '\'':
            // Handle octal escape sequences
            if (name[1] != '\0') {
                unsigned int octal_value = 0;
                sscanf(&name[1], "%o", &octal_value);
                length = 1 + (sizeof(unsigned int) * 2) + name_len_from_octal(octal_value);
                name += 2; // Move past the backslash and the octal number
            } else {
                length = 1;
            }
            break;
        default:
            // Calculate length using while loop for remaining characters
            const unsigned char *s = name;
            while (*s) {
                if (!is_read_within_bounds(s, sizeof(unsigned char), (size_t)(MAX_NAME_LENGTH - name_len))) {
                    fprintf(stderr, "Error: name goes past the end of the buffer\n");
                    return 1;
                }
                name_len += (*s) < 0x80 ? 1 : 2; // Handle multi-byte characters
                s++;
            }
            length = name_len + 1;
            break;
    }

    printf("The length of your name is: %d\n", length);
    return 0;
}

// Helper function to calculate length from an octal value
size_t name_len_from_octal(unsigned int octal_value) {
    size_t length = 0;

    while (octal_value > 0) {
        length++;
        octal_value = octal_value & 0x7F;
        octal_value >>= 7;
    }

    return length;
}
