/**
 * \brief Performs a percolation step on a given set of sites
 *
 * \param sites Pointer to the vector of sites
 * \param p Probability
 * \param time_step Time step
 */
void percolation_step(std::vector<int32_t>* sites, double p, int32_t time_step) {
    std::mt19937 rng(std::random_device{}()); // Seed random number generator
    std::uniform_int_distribution<> dis(0, sites->size() - 1); // Generate random index distribution

    for (int32_t i = 0; i < sites->size(); ++i) {
        if (sites->at(i) == -1) { // Empty site
            int32_t index = dis(rng); // Select random site
            if (std::bernoulli_distribution(p)(rng)) { // Apply percolation rule
                sites->at(index) = 1; // Mark site as occupied
                for (int32_t j = i + 1; j < sites->size(); ++j) {
                    if (sites->at(j) == -1 && std::abs(i - j) <= static_cast<int32_t>(time_step)) { // Check neighboring sites
                        sites->at(j) = 1; // Mark neighboring site as occupied
                    }
                }
            }
        }
    }
}
