#include <string>
#include <vector>
#include <stdexcept>

std::vector<std::string> extractUrlComponents(const std::string& url) {
    if (url.empty()) {
        throw std::invalid_argument("URL cannot be empty");
    }

    std::vector<std::string> components;
    size_t schemeEnd = url.find(":/");

    if (schemeEnd == std::string::npos) {
        throw std::runtime_error("Invalid URL format: no scheme found");
    }

    components.push_back(url.substr(0, schemeEnd));
    url.erase(0, schemeEnd + 2); // remove scheme and '://'

    size_t hostPortBegin = url.find("/");
    if (hostPortBegin != std::string::npos) {
        size_t portBegin = url.find(":");
        std::string host;
        std::string port;

        if (portBegin != std::string::npos && portBegin < hostPortBegin) {
            host = url.substr(0, portBegin);
            port = url.substr(portBegin + 1);
        } else {
            host = url.substr(0, hostPortBegin);
        }

        components.push_back(host);
        components.push_back(port);
        url.erase(0, hostPortBegin + 1); // remove host:port or just host
    }

    components.push_back(url); // path
    return components;
}
