OGSTRCCHAR ToWkbString(OGRwkbGeomType geomType, const OGRGeometry *geom);

std::string OGRGeometryToString(OGRGeometry *geom, int dimension) {
    OGRSpatialReference *sr = geom->getSpatialRef();
    std::string wkbString;

    if (geom == nullptr) {
        return "";
    }

