    if (dimension == 2) {
        format = "POLYGON(%s)";
    } else if (dimension == 3) {
        format = "MULTIPOLYGON(%s)";
    }

    std::string result = std::string(format.c_str(), srid.c_str()) + "\n" +
                         "COORDINATES (\n";

    int i = 0;
    std::vector<double> coordinates;
    geom->getEnvelope(&coordinates[i++], &coordinates[i++], &coordinates[i++],
                      &coordinates[i++]);

    if (dimension == 3) {
        geom->getEnvelope(&coordinates[i++], &coordinates[i++], &coordinates[i++],
                          &coordinates[i++], &coordinates[i++]);
    }

    result += "(";
    for (size_t j = 0; j < coordinates.size(); j += dimension) {
        if (j > 0) {
            result += ", ";
        }
        result += std::to_string(coordinates[j]) + ", ";
        result += std::to_string(coordinates[j + 1]);
        if (dimension == 3) {
            result += ", ";
            result += std::to_string(coordinates[j + 2]);
        }
        result += ")\n";
    }

    result += ")\n";

    OGR_DESTROY(geom);
    return result;
}
