#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>

#define MAX_CMD_LEN 1024

int
run_command_in_background(const char *cmd) {
    pid_t child_pid;
    int status;

    if (strlen(cmd) > MAX_CMD_LEN) {
        perror("Command too long");
        return 1;
    }

    if ((child_pid = fork()) < 0) {
        perror("Fork failed");
        return 1;
    }

    if (child_pid == 0) {
        setsid(); // create a new session
        if (execvp(cmd, (char *const *) &cmd, NULL) < 0) {
            perror("Execvp failed");
            exit(1);
        }
    }

    if (waitpid(child_pid, &status, WNOHANG) <= 0) {
        perror("Waitpid failed");
        return 1;
    }

    return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
}
