// Function to compute differences for a given direction
std::vector<std::vector<float>> computeDifferences(const std::vector<std::vector<float>>& input) {
    size_t rows = input.size();
    size_t cols = input[0].size();

    std::vector<std::vector<float>> differences(rows, std::vector<float>(cols));

    for (size_t i = 0; i < rows; ++i) {
        for (size_t j = 0; j < cols; ++j) {
            if (i > 0) {
                differences[i][j] = input[i][j] - input[i - 1][j];
            } else {
                differences[i][j] = 0.0f;
            }

            if (j > 0) {
                differences[i][j] += differences[i][j - 1];
            }

            if (i < rows - 1) {
                differences[i + 1][j] += differences[i][j];
            }
        }
    }

    return differences;
}

