#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define NUM_POINTS 10

typedef struct {
    float x, y, z;
} Point;

float length(Point p1, Point p0) {
    return sqrtf(powf(p1.x - p0.x, 2.0f) + powf(p1.y - p0.y, 2.0f) + powf(p1.z - p0.z, 2.0f));
}

Point* compute_normals(Point points[]) {
    Point* normals;
    int i, j;

    normals = (Point*)alloca(NUM_POINTS * sizeof(Point));

    for (i = 0; i < NUM_POINTS; i++) {
        if (i == 0) {
            normals[i].x = 0.0f;
            normals[i].y = 0.0f;
            normals[i].z = 0.0f;
            continue;
        }

        normals[i].x = (points[i].x - points[i - 1].x);
        normals[i].y = (points[i].y - points[i - 1].y);
        normals[i].z = (points[i].z - points[i - 1].z);

        float len = length(points[i], points[i - 1]);

        if (len > 0.0f) {
            normals[i].x /= len;
            normals[i].y /= len;
            normals[i].z /= len;
        }
    }

    return normals;
}
