#include <iostream>
#include <string>
#include <filesystem>
#include <random>
#include <chrono>

namespace fs = std::filesystem;

std::string tmpfile() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 999999999);
    std::string suffix = std::to_string(dis(gen));

    fs::path temp_dir = fs::temp_directory_path();
    fs::path file_path = temp_dir / ("vm-" + suffix + ".tmp");

    if (fs::exists(file_path)) {
        suffix = std::to_string(dis(gen));
        file_path = temp_dir / ("vm-" + suffix + ".tmp");
    }

    if (!fs::create_directory(temp_dir.parent_path())) {
        std::cerr << "Failed to create temporary directory." << std::endl;
        throw std::runtime_error("Failed to create temporary directory.");
    }

    std::ofstream ofs(file_path.string(), std::ios::out | std::ios::trunc);
    if (!ofs.is_open()) {
        std::cerr << "Failed to create temporary file." << std::endl;
        throw std::runtime_error("Failed to create temporary file.");
    }

    ofs.close();

    return file_path.string();
}
```

