#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>

#define MAX_NODES 1024

typedef unsigned int NodeID;

void bfs(NodeID start, NodeID num_nodes, bool visited[MAX_NODES],
         int dist[MAX_NODES], int adj_matrix[MAX_NODES][MAX_NODES],
         NodeID parent[MAX_NODES]) {
    bool queue_full = false;
    NodeID queue[MAX_NODES];
    NodeID front = 0, rear = 0;
    NodeID current;

    visited[start] = true;
    dist[start] = 0;
    parent[start] = -1;

    queue[rear++] = start;

    while (front < rear) {
        current = queue[front++];

        for (NodeID i = 0; i < num_nodes; i++) {
            if (adj_matrix[current][i] != 0 && !visited[i]) {
                visited[i] = true;
                dist[i] = dist[current] + 1;
                parent[i] = current;
                queue[rear++] = i;

                if (rear >= MAX_NODES) {
                    queue_full = true;
                    break;
                }
            }
        }

        if (queue_full) {
            break;
        }
    }
}

NodeID* find_shortest_path(int adj_matrix[MAX_NODES][MAX_NODES],
                           NodeID num_nodes, NodeID start, NodeID end) {
    bool visited[MAX_NODES] = {0};
    int dist[MAX_NODES] = {INT_MAX,};
    int parent[MAX_NODES] = {-1,};

    bfs(start, num_nodes, visited, dist, adj_matrix, parent);

    if (dist[end] == INT_MAX) {
        return NULL;
    }

    NodeID* path = malloc((sizeof(NodeID) * (dist[end] + 1)));
    NodeID current = end;

    path[dist[end]] = current;
    for (int i = dist[end] - 1; i >= 0; i--) {
        path[i] = parent[current];
        current = parent[current];
    }

    return path;
}
