#define ALPHABET_SIZE 26
#define MAX_STRING_LENGTH 1000

typedef struct TrieNode {
    int count;
    struct TrieNode *children[ALPHABET_SIZE];
    struct TrieNode *fail;
} TrieNode;

void init_trie(TrieNode *root) {
    root->fail = root;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        root->children[i] = NULL;
    }
}

void insert(TrieNode *current, char c, int length) {
    int index = c - 'a';

    if (current->children[index] == NULL) {
        current->children[index] = malloc(sizeof(TrieNode));
        init_trie(current->children[index]);
        current->children[index]->fail = current;
    }

    current = current->children[index];
    current->count++;

    if (length > 0) {
        insert(current, c, length - 1);
    }
}

int *count_characters(char *str) {
    TrieNode *root = malloc(sizeof(TrieNode));
    init_trie(root);

    int length = strlen(str);
    int *counts = calloc(ALPHABET_SIZE, sizeof(int));

    for (int i = 0; i < length; i++) {
        insert(root, str[i], length - i - 1);
    }

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        TrieNode *current = root->children[i];
        counts[i] = current ? current->count : 0;
    }

