int remove_file(const char *path) {
    int fd;
    char normalized_path[1024];
    ssize_t normalized_path_len;

    memset(normalized_path, 0, sizeof(normalized_path));

    if (realpath(path, normalized_path) == NULL) {
        perror("Error getting realpath");
        return -1;
    }

    normalized_path_len = strlen(normalized_path);

    if (normalized_path[normalized_path_len - 1] == '/') {
        normalized_path[--normalized_path_len] = '\0';
    }

    if (chdir(normalized_path) < 0) {
        perror("Error changing directory");
        free(normalized_path);
        return -1;
    }

    if ((fd = open(path, O_RDONLY)) >= 0) {
        close(fd);
    }

    if (unlinkat(AT_FDIRST, path, 0) < 0) {
        perror("Error removing file");
        free(normalized_path);
        return -1;
    }

    free(normalized_path);
    return 0;
}
