typedef struct {
    int value;
    bool unique;
} entry_t;

int reduce_list(int* input, int size, int* output, int* num_unique) {
    entry_t* entries = calloc(size, sizeof(entry_t));
    if (entries == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    int index = 0;
    for (int i = 0; i < size; ++i) {
        int key = input[i];
        bool found = false;
        for (int j = 0; j < index; ++j) {
            if (entries[j].value == key) {
                found = true;
                break;
            }
        }

        if (!found) {
            entries[index].value = key;
            entries[index].unique = true;
            ++index;
        }
    }

    *num_unique = index;

    *output = malloc(index * sizeof(int));
    if (*output == NULL) {
        perror("Memory allocation failed");
        free(entries);
        return -1;
    }

    for (int i = 0; i < index; ++i) {
        (*output)[i] = entries[i].value;
    }

    free(entries);

    return index;
}
