class AlertHandler : public enable_shared_from_this<AlertHandler> {
public:
    AlertHandler(io_service& io_service, session& ses, int poll_interval)
        : _io_service(io_service), _ses(ses), _poll_interval(poll_interval), _timer(io_service) {
        _timer.expires_from_now(boost::posix_time::seconds(poll_interval));
        _timer.async_wait(bind(&AlertHandler::handle_timer, shared_from_this(), _1));
    }

    void start() {
        _io_service.run();
    }

private:
    void handle_timer(const boost::system_error& error) {
        if (error) {
            std::cerr << "Error in timer: " << error.what() << std::endl;
            return;
        }

        std::auto_ptr<alert> a(dynamic_cast<alert*>(_ses.pop_alert()));
        if (!a.get()) {
            _timer.expires_from_now(boost::posix_time::seconds(_poll_interval));
            _timer.async_wait(bind(&AlertHandler::handle_timer, shared_from_this(), _1));
            return;
        }

        std::cout << "Received alert: ";
        ::print_alert(a.get(), std::cout);
        std::cout << std::endl;

        save_resume_data(*a);
        _ses.pop_alert();

        _timer.expires_from_now(boost::posix_time::seconds(_poll_interval));
        _timer.async_wait(bind(&AlertHandler::handle_timer, shared_from_this(), _1));
    }

    void save_resume_data(alert& a) {
        if (a.type() != alert::save_resume_data) {
            std::cerr << "Unexpected alert type: " << a.type() << std::endl;
            return;
        }

        save_resume_data_alert const& rda = static_cast<save_resume_data_alert&>(a);
        torrent_handle h = rda.handle;
        if (!h.is_valid()) {
            std::cerr << "Invalid torrent handle" << std::endl;
            return;
