        boost::filesystem::ofstream out(h.save_path() / (h.get_torrent_info().name() + ".fastresume"), std::ios_base::binary);
        out.unsetf(std::ios_base::skipws);
        bencode(std::ostream_iterator<char>(out), *rda.resume_data);
        out.close();
    }

    io_service& _io_service;
    session& _ses;
    int _poll_interval;
    deadline_timer _timer;
};

void process_alerts(session& ses) {
    io_service io_service;
    AlertHandler handler(io_service, ses, 1000);
