CREATE FUNCTION dbo.SafeFunctionName (@ArrayParam int[], @ScalarParam int)
RETURNS int AS
BEGIN
 DECLARE @EncodedArrayParam SQLTCHAR(MAX), @EncodedScalarParam SQLTCHAR(10);
 SET @EncodedArrayParam = QCS_SQLVARBINARY_ARRAY(@ArrayParam, LEN(@ArrayParam), 0); -- Ensure proper length calculation for array
 SET @EncodedScalarParam = QCS_SQLINT(@ScalarParam); -- Ensure proper handling of scalar integer

 DECLARE @stmt NVARCHAR(MAX) = 'SELECT col1, col2, ... FROM table_name WHERE param1 = @ScalarParam AND param2 IN (@ArrayParam)';

 DECLARE @PreparedStatement INT;
 SET @PreparedStatement = sqlprepare(@stmt, N'@ScalarParam int, @ArrayParam int[]', @EncodedScalarParam, @EncodedArrayParam);

