void topic_modeling(int64_t *wp, int64_t *dp, int64_t *probs, int64_t *sumdp, int64_t *ztot, int32_t num_topics, int32_t num_words) {
    int64_t *wp_row, *dp_row, *probs_row, *sumdp_row, *ztot_row;
    int64_t *temp_probs, *temp_ztot;
    int32_t i, j, topic;
    int64_t num_entries = num_topics * num_words;

