    for (i = 0; i < num_entries; i++) {
        probs[i] = 0;
    }

    for (i = 0; i < num_words; i++) {
        sumdp[i] = 0;
    }

    // Calculate topic probabilities
    temp_probs = (int64_t *) calloc(num_entries, sizeof(int64_t));
    temp_ztot = (int64_t *) calloc(num_topics, sizeof(int64_t));

    if (!temp_probs || !temp_ztot) {
