	if(fp==0)
		{
		printf("\ncannot open index file %s",idxfilename);
		return -1;
		}

	while (1) {

		// At this point it has to be a BASE line or else end of file. 
		stat = fscanf(fp, " BASE%i,%i,%i,%i,%i,%i,%c:",
				&bm, &bk, &wm, &wk, &bmrank, &wmrank, &colorchar);

