#include <vector>
#include <cstddef>
#include <iostream>

using namespace std;

// Function to apply Gaussian filter to an image using a separable filter
void gaussian_filter(const int width, const int height, const int kernel_size, const float* kernel, uchar image[][width], uchar filtered_image[][width]) {
    // Check if image and filtered image pointers are valid
    if (!image || !filtered_image) {
        cerr << "Invalid image or filtered image pointer!" << endl;
        return;
    }

    // Allocate memory for intermediate results
    vector<vector<float>> intermediate_result(height, vector<float>(width));

    // Apply horizontal filter
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float sum = 0.0f;
            for (int ky = 0; ky < kernel_size; ky++) {
                int sy = y + ky - (kernel_size / 2);
                if (sy >= 0 && sy < height) {
                    for (int sx = 0; sx < kernel_size; sx++) {
                        int sx_corrected = x + sx - (kernel_size / 2);
                        if (sx_corrected >= 0 && sx_corrected < width) {
                            sum += image[sy][sx_corrected] * kernel[ky * kernel_size + sx];
                        }
                    }
                }
            }
            intermediate_result[y][x] = sum;
        }
    }

    // Apply vertical filter
    for (int x = 0; x < width; x++) {
        for (int y = 0; y < height; y++) {
            float sum = 0.0f;
            for (int sx = 0; sx < kernel_size; sx++) {
                int sx_corrected = x + sx - (kernel_size / 2);
                if (sx_corrected >= 0 && sx_corrected < width) {
                    for (int sy = 0; sy < height; sy++) {
                        int sy_corrected = y + sy - (kernel_size / 2);
                        if (sy_corrected >= 0 && sy_corrected < height) {
                            sum += intermediate_result[sy_corrected][sx_corrected] * kernel[sx * kernel_size + sy];
                        }
                    }
                }
            }
            filtered_image[y][x] = static_cast<uchar>(sum);
        }
    }
}
