template <typename T, typename... Ts>
class variant {
private:
    std::unique_ptr<T> data_;
    std::size_t type_index_;

    template <std::size_t I>
    struct index_helper {
        static constexpr std::size_t value = I;
    };

    template <typename U>
    struct type_index {
        static constexpr std::size_t value = meta::index_of<U, Ts...>::value;
    };

    template <typename U>
    bool is_supported_type() const {
        return type_index<U>::value < sizeof...(Ts);
    }

public:
    variant() = default;

    template <typename U>
    variant(U&& value) {
        if constexpr (std::is_constructible_v<T, U&&>) {
            new (data_.release()) T(std::forward<U>(value));
            type_index_ = meta::index_of<T, Ts...>::value;
        } else {
            throw std::runtime_error("Unsupported type");
        }
    }

    template <typename U>
    variant(std::unique_ptr<U>&& value) {
        if constexpr (is_supported_type<U>()) {
            data_ = std::move(value);
            type_index_ = type_index<U>::value;
        } else {
            throw std::runtime_error("Unsupported type");
        }
    }

    template <typename U>
    variant& operator=(U&& value) {
        if constexpr (std::is_constructible_v<T, U&&>) {
            if (type_index_ == type_index<T>::value) {
                new (data_.get()) T(std::forward<U>(value));
            } else {
                if (data_) {
                    data_->~T();
                    data_.reset();
                }
                new (data_.release()) T(std::forward<U>(value));
                type_index_ = type_index<T>::value;
            }
        } else {
            if (data_) {
                data_->~T();
                data_.reset();
            }
            throw std::runtime_error("Unsupported type");
        }
        return *this;
    }

    template <typename U>
    variant& operator=(std::unique_ptr<U>&& value) {
        if constexpr (is_supported_type<U>()) {
