using System;
using System.Collections.Generic;
using System.Security.Cryptography;

public static void GenerateAndTestShuffledSort(int minElements, int maxElements, Action<List<int>> customSorter)
{
    if (minElements <= 0 || maxElements <= 0)
        throw new ArgumentOutOfRangeException(nameof(minElements), "Minimum number of elements must be positive.");
    if (maxElements < minElements)
        throw new ArgumentOutOfRangeException(nameof(maxElements), "Maximum number of elements must be greater than or equal to the minimum number of elements.");

    using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
    {
        int numberOfElements = minElements + rng.Next(maxElements - minElements + 1);
        List<int> originalElements = new List<int>(numberOfElements);

        for (int i = 0; i < numberOfElements; i++)
        {
            originalElements.Add(rng.Next(int.MinValue, int.MaxValue));
        }

        List<int> shuffledElements = new List<int>(originalElements);

        Shuffle(shuffledElements, rng);

        List<int> sortedElements = new List<int>(numberOfElements);
        sortedElements.AddRange(originalElements);
        sortedElements.Sort();

        customSorter(sortedElements);

        List<int> shuffledAndSortedElements = new List<int>(shuffledElements);
        shuffledAndSortedElements.Sort();

        if (!sortedElements.SequenceEqual(shuffledAndSortedElements))
        {
            throw new Exception("The shuffled list was not correctly sorted.");
        }
    }
}

private static void Shuffle<T>(List<T> list, RNGCryptoServiceProvider rng)
{
    int n = list.Count;
    while (n > 1)
    {
        n--;
        int k = rng.Next(n + 1);
        T temp = list[k];
        list[k] = list[n];
        list[n] = temp;
    }
}
