using System;
using System.Security.Cryptography;
using System.Text;

public static class DatagramGenerator
{
    private static readonly RandomNumberGenerator _random = new RNGCryptoServiceProvider();

    public static Datagram GenerateRandomDatagram(int size)
    {
        if (size < 0)
            throw new ArgumentOutOfRangeException(nameof(size), "Size must be non-negative.");

        byte[] data = new byte[size];
        _random.NextBytes(data);

        return new Datagram(data);
    }
}

public class Datagram
{
    private readonly byte[] _data;

    public static Datagram Empty { get; } = new Datagram(new byte[0]);

    public int Length => _data.Length;

    public Datagram(byte[] data)
    {
        _data = data;
    }

    public override bool Equals(object obj)
    {
        if (obj is Datagram datagram)
            return Equals(datagram);

        return false;
    }

    public bool Equals(Datagram other)
    {
        if (other is null)
            return false;

        return _data.SequenceEqual(other._data);
    }

    public override int GetHashCode()
    {
        return _data.Aggregate(0, (h, b) => h ^ b);
    }

    public override string ToString()
    {
        return Encoding.ASCII.GetString(_data);
    }
}
