using System;
using System.Security.Cryptography;

public static T[,] CreateAndFillRandomMatrix<T>(int rows, int columns, int minValue, int maxValue) where T : new()
{
    if (rows <= 0 || columns <= 0)
        throw new ArgumentException("Both rows and columns must be positive integers.");

    var random = new RNGCryptoServiceProvider();
    var elementSize = sizeof(T);
    var length = rows * columns;

    T[] elements = new T[length];

    for (int i = 0; i < length; i++)
    {
        T newElement = default(T);
        newElement = (T)(object)new Random().Next(minValue, maxValue + 1);
        elements[i] = newElement;
    }

    T[,] matrix = new T[rows, columns];

    for (int i = 0; i < rows; i++)
        for (int j = 0; j < columns; j++)
            matrix[i, j] = elements[i * columns + j];

    return matrix;
}
