using System;
using System.Security.Cryptography;
using MinecraftMapEditor.Blocks;

public static TEE_Result GenerateTree(Vector3 position, out int treeHeight)
{
    treeHeight = 0;

    RandomNumberGenerator rng = new RNGCryptoServiceProvider();

    // Generate trunk length
    int trunkLength = 5;
    byte[] lengthBytes = new byte[4];
    rng.GetBytes(lengthBytes);
    trunkLength = BitConverter.ToInt32(lengthBytes, 0);
    treeHeight += trunkLength;

    // Create trunk
    for (int y = (int)position.Y; y < (int)position.Y + trunkLength; y++)
    {
        if (IsCollision(position, new Vector3(position.X, y, position.Z)))
            return TEE_Result.ACCESS_DENIED;

        mWorldRef.SetBlock(position.X, y, position.Z, new LogBlock());
    }

    // Generate branches
    for (int branchAttempts = 0; branchAttempts < 10; branchAttempts++)
    {
        // Generate random direction
        byte[] directionBytes = new byte[3];
        rng.GetBytes(directionBytes);
        Vector3 direction = new Vector3(directionBytes[0], directionBytes[1], directionBytes[2]);

        // Generate random branch length
        byte[] lengthBytes = new byte[4];
        rng.GetBytes(lengthBytes);
        int branchLength = BitConverter.ToInt32(lengthBytes, 0);

        // Create branch
        Vector3 branchStart = position + new Vector3(0, (float)treeHeight, 0);
        for (int y = (int)branchStart.Y; y < (int)branchStart.Y + branchLength; y++)
        {
            if (IsCollision(branchStart + new Vector3(0, 1, 0), 1))
                continue;

            mWorldRef.SetBlock(branchStart.X, y, branchStart.Z, new LeavesBlock());
            branchStart.Y++;
            treeHeight++;
        }

        // Break if a branch was successfully created
        if (branchLength > 0)
            break;
    }

    return TEE_Result.SUCCESS;
}

private static bool IsCollision(Vector3 position, int blockSize = 1)
{
    int x = (int)position.X / blockSize;
    int y = (int)position.Y / blockSize;
    int z = (int)position.Z / blockSize;

    return mWorldRef.GetBlock(x, y, z) != null;
}
