using System.IO;
using System.Diagnostics;

public static string AddWebsiteToDirectory(string directoryPath, string siteName)
{
    if (string.IsNullOrEmpty(directoryPath) || string.IsNullOrEmpty(siteName))
    {
        return null;
    }

    string webConfigPath = Path.Combine(directoryPath, "web.config");

    if (!File.Exists(webConfigPath))
    {
        return null;
    }

    string newDirectoryPath = Path.Combine(directoryPath, siteName);

    if (Directory.Exists(newDirectoryPath))
    {
        throw new ArgumentException("A website with the given name already exists in the directory.");
    }

    Directory.CreateDirectory(newDirectoryPath);

    string iisExpressPath = Environment.GetEnvironmentVariable("IISExpressPath");

    if (string.IsNullOrEmpty(iisExpressPath))
    {
        throw new PlatformNotSupportedException("IIS Express is not installed on this system.");
    }

    string iisExpressCommand = $"{iisExpressPath} /site /name:{siteName} /physicalPath:{newDirectoryPath}";

    Process process = new Process();
    process.StartInfo.FileName = "cmd.exe";
    process.StartInfo.Arguments = $"/c {iisExpressCommand}";
    process.StartInfo.UseShellExecute = false;
    process.StartInfo.RedirectStandardOutput = true;

    process.Start();

    string output = process.StandardOutput.ReadToEnd();

    process.WaitForExit();

    if (process.ExitCode != 0)
    {
        throw new Exception($"Failed to add website to directory: {output}");
    }

    return newDirectoryPath;
}
