public class Resource
{
    public string Name { get; set; }
    public string Type { get; set; }
    public string Version { get; set; }
}

public class UpdateResourceRequest
{
    public string OldName { get; set; }
    public Resource NewResource { get; set; }
}

public string UpdateResource(UpdateResourceRequest request)
{
    string connectionString = "Data Source=(local);Initial Catalog=MyDatabase;Integrated Security=True";
    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        connection.Open();

        string newName = request.NewResource.Name;
        string oldName = request.OldName;
        string type = request.NewResource.Type;
        string version = request.NewResource.Version;

        // Validate request
        if (string.IsNullOrEmpty(newName) || string.IsNullOrEmpty(type) || string.IsNullOrEmpty(version))
        {
            return JsonConvert.SerializeObject(new { error = "Invalid request" });
        }

        // Validate ownership and uniqueness of resource name
        using (SqlCommand command = new SqlCommand("SELECT COUNT(*) FROM Resources WHERE Name = @Name AND Type = @Type AND Version = @Version AND Name != @OldName", connection))
        {
            command.Parameters.AddWithValue("@Name", newName);
            command.Parameters.AddWithValue("@Type", type);
            command.Parameters.AddWithValue("@Version", version);
            command.Parameters.AddWithValue("@OldName", oldName);

            int count = (int)command.ExecuteScalar();
            if (count > 0)
            {
                return JsonConvert.SerializeObject(new { error = "Resource already exists" });
            }
        }

        // Update resource
        using (SqlCommand command = new SqlCommand("UPDATE Resources SET Name = @Name, Type = @Type, Version = @Version WHERE Name = @OldName AND Type = @Type AND Version = @Version", connection))
        {
            command.Parameters.AddWithValue("@Name", newName);
            command.Parameters.AddWithValue("@Type", type);
            command.Parameters.AddWithValue("@Version", version);
            command.Parameters.AddWithValue("@OldName", oldName);

            try
            {
                command.ExecuteNonQuery();

                // Persist changes to database
                using (SqlTransaction transaction = connection.BeginTransaction())
                {
                    command.Transaction = transaction;
                    command.ExecuteNonQuery();
                    transaction.Commit();
                }

                return JsonConvert.SerializeObject(new { updatedResource = request.NewResource });
            }
            catch (SqlException e)
            {
                return JsonConvert.SerializeObject(new { error = "Database error: " + e.Message });
            }
        }
    }
}
