using System;

public enum IntersectionTypes {
    fourWay,
    threeWay,
    turn
}

public void RotateTransform(Transform transform, IntersectionTypes intersectionType) {
    if (intersectionType == IntersectionTypes.fourWay) {
        int dir = new Random().Next(2) * 2 - 1; // Generates 1 or -1
        transform.Rotate(0, dir * 90, 0);
    } else if (intersectionType == IntersectionTypes.threeWay) {
