public static void InsertCassandraData(ISession session, IDictionary<string, byte[]> outgoingPayload)
{
    if (session == null) throw new ArgumentNullException(nameof(session));
    if (outgoingPayload == null) throw new ArgumentNullException(nameof(outgoingPayload));

    using (var batch = new BatchStatement())
    {
        var insertStatement = new InsertIntoStatement("KeyspaceName", "TableName", new[] { "Column1", "Column2" })
