        batch.SetOutgoingPayload(outgoingPayload);

        var result = session.Execute(batch);
        var incomingPayload = result.Info.IncomingPayload;

        if (incomingPayload == null)
        {
            throw new Exception("Incoming payload is null.");
        }

        if (incomingPayload.Count != outgoingPayload.Count)
        {
            throw new Exception("Incoming payload has a different number of elements than outgoing payload.");
