public Entity CreateEntity(string inputName, int inputValue, SqlConnection connection)
{
    if (string.IsNullOrWhiteSpace(inputName))
        throw new ArgumentException("Name cannot be null or whitespace.");

    if (inputName.Length > 50)
        throw new ArgumentOutOfRangeException("Name cannot be longer than 50 characters.");

    if (!char.IsLetterOrDigit(inputName[0]) && inputName[0] != '_')
        throw new ArgumentException("Name must start with a letter or an underscore.");

    if (!int.TryParse(inputValue.ToString(), out int validInputValue))
    {
        throw new ArgumentOutOfRangeException("InputValue must be an integer.");
    }

    using (var command = new SqlCommand("INSERT INTO Entities (Name, Value) VALUES (@Name, @Value)", connection))
    {
        command.Parameters.AddWithValue("@Name", inputName);
        command.Parameters.AddWithValue("@Value", inputValue);

        try
        {
            command.ExecuteNonQuery();
        }
        catch (SqlException ex)
        {
            if (ex.Number == 2627) // Unique constraint violation
                throw new ArgumentException("Entity with this Name already exists.");

            throw;
        }
    }

    using (var command = new SqlCommand("SELECT Id FROM Entities WHERE Name = @Name", connection))
    {
        command.Parameters.AddWithValue("@Name", inputName);

        using (var reader = command.ExecuteReader())
        {
            if (!reader.Read())
                throw new Exception("Failed to retrieve newly created Entity.");

            return new Entity { Id = reader.GetInt32(0), Name = inputName };
        }
    }
}
