    public class PartyController : Controller
    {
        [HttpGet]
        public ActionResult Index()
        {
            return View();
        }

        [HttpGet]
        public ActionResult Rsvp(string partyId)
        {
            if (string.IsNullOrEmpty(partyId))
            {
                return new HttpStatusCodeResult(400, "Invalid party ID.");
            }

            return View("Rsvp", new { PartyId = partyId });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult Rsvp(string partyId, FormCollection form)
        {
            if (string.IsNullOrEmpty(partyId))
            {
                return new HttpStatusCodeResult(400, "Invalid party ID.");
            }

            if (!IsPostRequestOrJson(Request))
            {
                return new HttpStatusCodeResult(405);
            }

            string name = form["Name"];
            string email = form["Email"];

            if (string.IsNullOrEmpty(name) || string.IsNullOrEmpty(email))
            {
                ModelState.AddModelError("", "Name and Email are required.");
                return View("Rsvp", new { PartyId = partyId, Form = form });
            }

            if (!IsValidEmailAddress(email))
            {
                ModelState.AddModelError("Email", "Invalid email address.");
                return View("Rsvp", new { PartyId = partyId, Form = form });
            }

            try
            {
                MailMessage mail = new MailMessage();
                mail.To.Add(new MailboxAddress("Party Organizer", "party.organizer@example.com"));
                mail.Subject = "New RSVP for Party " + partyId;
                mail.Body = "A new RSVP has been received for Party " + partyId + ". Name: " + name + " Email: " + email;
                SmtpClient client = new SmtpClient();
                client.Send(mail);
            }
            catch (Exception ex)
            {
                ModelState.AddModelError("", "An error occurred while sending the email. " + ex.Message);
                return View("Rsvp", new { PartyId = partyId, Form = form });
            }

            ViewBag.Message = "Your RSVP was successful!";
            return View("Result", new { PartyId = partyId });
        }

        private bool IsValidEmailAddress(string email)
        {
            try
            {
                var addr = new System.Net.Mail.MailAddress(email);
                return addr.Address == email;
            }
            catch
            {
                return false;
            }
        }
    }
}
