public static async Task<EditElementResponse> EditElement(int pageSectionId, string elementId, string elementHtml)
{
    if (string.IsNullOrWhiteSpace(elementId) || string.IsNullOrWhiteSpace(elementHtml))
    {
        throw new ArgumentException("ElementId and ElementHtml are required.");
    }

    if (!IsValidHexadecimal(elementId))
    {
        throw new ArgumentException("ElementId must be a valid hexadecimal value.");
    }

    if (elementHtml.Length > 1024)
    {
        throw new ArgumentException("ElementHtml cannot exceed 1024 characters.");
    }

    try
    {
        await EditElementAsync(pageSectionId, elementId, elementHtml);
        return new EditElementResponse { State = true };
    }
    catch (Exception ex)
    {
        return new EditElementResponse { State = false, Message = ex.InnerException?.Message ?? ex.Message };
    }
}

private static bool IsValidHexadecimal(string input)
{
    return Regex.IsMatch(input, "^[0-9A-Fa-f]+$");
}
