using System.Threading;
using System.Threading.Tasks;

public static async Task StartProcessWithTrackingAndSentinel(ProcessStartInfo psi, string trackingFolder, int timeoutMilliseconds)
{
    if (!Directory.Exists(trackingFolder))
    {
        throw new InvalidOperationException($"Invalid tracking folder. Set the 'TrackingFolder' property to a valid folder.");
    }

    string pidFilePath = Path.Combine(trackingFolder, "pid_{0}.txt");
    string pidString = null;

    using (var process = new Process())
    {
        process.StartInfo = psi;
        process.Start();

        pidString = await WriteTrackingFileAsync(pidString, trackingFolder, process);

        using (var sentinelProcess = new Process())
        {
            sentinelProcess.StartInfo.FileName = "SentinelProcess.exe"; // Replace with the path to your sentinel process
            sentinelProcess.StartInfo.Arguments = $"{psi.FileName} {pidString} {timeoutMilliseconds}";
            sentinelProcess.Start();

            CancellationTokenSource cts = new CancellationTokenSource();
            CancellationToken token = cts.Token;

            await Task.Delay(timeoutMilliseconds, token);

            if (process.HasExited)
            {
                return;
            }

            cts.Cancel();
            await sentinelProcess.WaitForExitAsync();

            if (sentinelProcess.ExitCode != 0)
            {
                await CleanupTrackingFileAsync(pidString, trackingFolder);
                throw new TimeoutException($"Process '{psi.FileName}' did not complete within the specified timeout.");
            }
        }
    }
}

private static async Task<string> WriteTrackingFileAsync(string pidString, string trackingFolder, Process process)
{
    using (var file = File.CreateText(Path.Combine(trackingFolder, "pid_{0}.txt".Replace("{0}", process.Id.ToString()))))
    {
        await file.WriteAsync(pidString ?? process.Id.ToString() + Environment.NewLine);
    }

    return process.Id.ToString();
}

private static async Task CleanupTrackingFileAsync(string pidString, string trackingFolder)
{
    string filePath = Path.Combine(trackingFolder, "pid_{0}.txt".Replace("{0}", pidString));

    if (File.Exists(filePath))
    {
        await File.DeleteAsync(filePath);
    }
}
