import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public int addTown(String townName, Connection connection) {
    int lastInsertedId = 0;
    try {
        String query = "INSERT INTO Towns(name) VALUES(?)";
        PreparedStatement statement = connection.prepareStatement(query, PreparedStatement.RETURN_GENERATED_KEYS);
        statement.setString(1, townName);
        statement.executeUpdate();
        ResultSet generatedKeys = statement.getGeneratedKeys();
        if (generatedKeys.next()) {
            lastInsertedId = generatedKeys.getInt(1);
        }
        statement.close();

        // Start transaction
        connection.setAutoCommit(false);

        // Perform other database operations within the transaction
        // ...

        // Commit transaction
        connection.commit();
        connection.setAutoCommit(true);

    } catch (SQLException e) {
        try {
            // Rollback transaction in case of error
            connection.rollback();
            connection.setAutoCommit(true);
            throw new RuntimeException("Error adding town: " + e.getMessage());
        } catch (SQLException ex) {
            throw new RuntimeException("Error during rollback: " + ex.getMessage());
        }
    }

    return lastInsertedId;
}
