using System;
using System.IO;
using System.Xml.Linq;

public static Font CreateFontFromXml(Device device, string fontName)
{
    XDocument xmlDocument;
    using (Stream stream = typeof(Program).Assembly.GetManifestResourceStream($"FontConfigs.{fontName}.xml"))
    {
        if (stream == null)
        {
            throw new FileNotFoundException($"Font configuration file '{fontName}.xml' not found.");
        }

        xmlDocument = XDocument.Load(stream);
    }

    XElement fontElement = xmlDocument.Descendants("Font").FirstOrDefault(e => (string)e.Element("Name") == fontName);

    if (fontElement == null)
    {
        throw new ArgumentException($"Font with name '{fontName}' not found in the XML configuration file.");
    }

    float fontSize = (float)fontElement.Element("Size");
    float fontWidth = (float)fontElement.Element("Width");
    float fontHeight = (float)fontElement.Element("Height");

    return new Font(fontName, fontSize, FontStyle.Regular, GraphicsUnit.Point, 0, new FontFamily(fontName), fontWidth, fontHeight);
}

