    for (int i = 0; i < pixels.Length; i++)
    {
        Marshal.StructureToPtr(pixels[i], new IntPtr(buffer.ToInt64() + i * elementSize), false);
    }

    return new Matrix<LabPixel>(buffer, rows, columns, elementSize);
