public class CacheController : Controller
{
    private readonly IDictionary<string, object> _cache = new Dictionary<string, object>();

    [HttpGet, HttpPost, HttpDelete]
    public ActionResult ProcessRequestAndUpdateCache(string key, string value)
    {
        if (string.IsNullOrEmpty(key))
        {
            return new BadRequestResult();
        }

        if (!IsValidRequestMethod() || !IsValidKey(key))
        {
            return new HttpStatusCodeResult(403);
        }

        if (HttpContext.Request.HttpMethod == "DELETE")
        {
            if (_cache.ContainsKey(key))
            {
                _cache.Remove(key);
                return new OkResult();
            }
            else
            {
                return new HttpStatusCodeResult(404);
            }
        }
        else
        {
            if (_cache.ContainsKey(key))
            {
                _cache[key] = value;
            }
            else
            {
                _cache.Add(key, value);
            }

            return new OkResult();
        }
    }

    private bool IsValidRequestMethod()
    {
        var allowedMethods = new[] { "GET", "POST", "DELETE" };
        return allowedMethods.Contains(HttpContext.Request.HttpMethod);
    }

    private bool IsValidKey(string key)
    {
        // Validate key against a catalog of valid keys.
        // Replace this condition with your own validation logic.
        return key.Length > 0 && key.Length <= 100;
    }
}
