        public static void PublishOversizedMessages()
        {
            try
            {
                _publisher = new ROSBridge.RosBridgeServer().Advertise<Complex>("complex", new ROSBridge.MessageFields<Complex>());

                const int messageSizeLimit = 1024; // Set a reasonable limit
                byte[] oversizedMessageData;

                using (var ms = new MemoryStream())
                {
                    var binaryFormatter = new BinaryFormatter();
                    var oversizedMessage = new Complex { Real = float.MaxValue, Imaginary = float.MaxValue };
                    binaryFormatter.Serialize(ms, oversizedMessage);
                    oversizedMessageData = ms.ToArray();
                }

                while (true)
                {
                    if (oversizedMessageData.Length > messageSizeLimit)
                    {
                        try
                        {
                            _publisher.Publish(Encoding.ASCII.GetString(oversizedMessageData));
                            throw new Exception("Expected publication exception");
                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine($"Caught expected exception: {ex.Message}");
                        }
