                    _publisher.Publish(Encoding.ASCII.GetString(oversizedMessageData));
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Unexpected exception: {ex.Message}");
            }
            finally
            {
                _publisher?.Dispose();
            }
        }
    }
}
