using System;
using System.IO;
using System.Xml.XPath;
using System.Xml.XDocument;

public class ConfigFileUpdater
{
    private readonly XDocument _configDocument;

    public ConfigFileUpdater(XDocument configDocument)
    {
        _configDocument = configDocument;
    }

    public XDocument UpdateXmlFile(string xpathToSearchersSection, string newSearcherXml, string xpathToInsertAfter)
    {
        if (File.Exists(_configDocument.BaseUri.LocalPath))
        {
            XElement searchersSection = _configDocument.XPathSelectElement(xpathToSearchersSection);

            if (searchersSection != null)
            {
                XElement newSearcherElement = XElement.Parse(newSearcherXml);

                if (!searchersSection.Elements().Any(e => e.Value == newSearcherElement.Value("id")))
                {
                    searchersSection.Add(newSearcherElement);
                }
                else
                {
                    throw new ArgumentException("A searcher with the same ID already exists.");
                }

                XElement nodeToInsertAfter = _configDocument.XPathSelectElement(xpathToInsertAfter);

                if (nodeToInsertAfter != null)
                {
                    searchersSection.AddAfterSelf(newSearcherElement);
                    searchersSection.RemoveNodes();
                    searchersSection.AddBeforeSelf(newSearcherElement);
                    searchersSection.Remove();
                    _configDocument.Root.Add(searchersSection);
                }
                else
                {
                    throw new ArgumentException("The specified node to insert after does not exist.");
                }
            }
            else
            {
                throw new ArgumentException("The specified searchers section does not exist.");
            }
        }
        else
        {
            throw new FileNotFoundException("The configuration file does not exist.");
        }

        using (File.Create(_configDocument.BaseUri.LocalPath).Dispose())
        {
            _configDocument.Save(_configDocument.CreateWriter());
        }

        return XDocument.Load(_configDocument.BaseUri.LocalPath);
    }
}
