public void EnsureValidConnections(object[,] board) {
    int Width = board.GetLength(1);
    int Height = board.GetLength(0);

    for (int i = 0; i < Height; i++) {
        for (int j = 0; j < Width; j++) {
            if (board[i, j] is ITank tank && !tank.IsSink) {
                if (tank.Outputs.Length == 0) {
                    int row, col;
                    do {
                        row = new Random().Next(Utilities.BoundedInt(i - 1, 0, Height), Utilities.BoundedInt(i + 1, 0, Height));
                        col = j;
                    } while (board[row, col] is not ITank _ || _ == tank);

                    tank.ConnectTo((ITank)board[row, col]);
                    tank.Update();
                    ((ITank)board[row, col]).Update();
                }
