```csharp using System; using System.Threading;

public class Observation
{
    public int Sequence { get; set; }
    public int Producer { get; set; }
    public int Latency { get; set; }
}

public class DemuxProducer<T, U> where T : new()
{
    private int _sequence = 0;
    private SemaphoreSlim _semaphore = new SemaphoreSlim(1);

    public U Produce(T arg)
    {
        _semaphore.Wait();

        try
        {
            var wait = new Random().Next(10);
            Thread.Sleep(wait);

            var observation = new Observation
            {
                Sequence = Interlocked.Increment(ref _sequence),
                Producer = Thread.CurrentThread.ManagedThreadId,
                Latency = wait
            };

            return (U)observation;
        }
        finally
        {
            _semaphore.Release();
        }
    }
}

public class ProducerConsumerDemux
{
    private DemuxProducer<int, Observation> _producer;

    public ProducerConsumerDemux()
    {
        _producer = new DemuxProducer<int, Observation>();
    }

    public Observation Produce(int arg)
    {
        return _producer.Produce((int)arg);
    }
}
```

