        session = sessionFactory.openSession();
        Query query = session.createSQLQuery(queryString).addEntity(resultClass);
        query.executeUpdate();
        session.close();
    }

    public void clearSession() {
        if (session != null && session.isOpen()) {
            session.clear();
            session.close();
            session = null;
        }
    }

