def verify_request(req):
    allowed_methods = ["POST", "PUT", "DELETE"]
    content_type = req.headers.get("Content-Type")
    if not content_type or content_type.startswith("application/json") or content_type.startswith("text/plain"):
        return False
    if req.method not in allowed_methods:
        return False
    request_body = req.body.decode("utf-8")
    request_hash = hmac.new(b"secret_key", msg=request_body.encode("utf-8"), digestmod=hashlib.sha256).digest()
    request_signature = base64.b64encode(request_hash).decode()
    auth_header = req.headers.get("Authorization")
    if not auth_header or auth_header.startswith("Bearer ") or not req.headers.get("X-Hub-Signature"):
        return False
    auth_signature = auth_header[len("Bearer "):]
    return hmac.compare_digest(request_signature.encode("utf-8"), auth_signature.encode("utf-8"))

def handle_request(req):
    if not verify_request(req):
        return http.client.HTTPResponse(
            b"Unauthorized",
            status=http.client.HTTPStatus.UNAUTHORIZED,
            reason="Unauthorized",
        )

    user_data = None
    if req.method == "PUT":
        user_data = json.load(req.body)
    elif req.method != "DELETE":
        return http.client.HTTPResponse(
            b"Bad Request",
            status=http.client.HTTPStatus.BAD_REQUEST,
            reason="Invalid request method",
        )

    if user_data is not None:
        # Perform user data validation and update here
        updated_user_data = process_user_data(user_data)
        return http.client.HTTPResponse(
            json.dumps(updated_user_data).encode("utf-8"),
            status=http.client.HTTPStatus.OK,
            headers={"Content-type": "application/json"},
        )

    # For DELETE requests, return a success message
    return http.client.HTTPResponse(
        b"User deleted successfully",
        status=http.client.HTTPStatus.OK,
    )

def process_user_data(user_data):
    # User data processing logic goes here
    return user_data

def main():
    conn = http.client.HTTPConnection("localhost:8000")
    conn.ssl_context = ssl.create_default_context()
    while True:
        req = conn.request(method="GET", url="/api/v1/handle_request")
        res = conn.getresponse()
        if res.status == http.client.HTTPStatus.OK:
            data = json.loads(res.read().decode("utf-8"))
            if data["method"] in ["POST", "PUT", "DELETE"]:
                req = http.client.HTTPRequest(
                    method=data["method"],
                    uri="/api/v1/handle_request",
                    headers={
                        "Content-Type": "application/json",
                        "X-Hub-Signature": f"Bearer {generate_signature(data)}",
                    },
                    body=json.dumps(data["data"]).encode("utf-8"),
                )
                handle_request(req)
        else:
            print(f"Received unexpected response: {res.status} {res.reason}")

if __name__ == "__main__":
