using System;
using System.Net.NetworkInformation;
using System.Text;

private static string GetProjectStartupPath(Project project)
{
    string startupFile = project.StartupFile;

    if (!string.IsNullOrEmpty(startupFile))
    {
        return startupFile;
    }

    int availablePort;
    Random random = new Random();

    do
    {
        availablePort = random.Next(1200, 60001);
    } while (IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpConnections()
             .Any(connection => connection.LocalEndPoint.Port == availablePort));

    string basePath = Path.GetDirectoryName(project.FileProperties.Path);
    string startupFileName = Path.GetFileNameWithoutExtension(project.Name) + "_" + availablePort.ToString() + Path.GetExtension(project.FileProperties.Path);
    string startupFileFullPath = Path.Combine(basePath, startupFileName);

    return startupFileFullPath;
}
