using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class ProcessManager
{
    public async Task<ProcessResult> StartProcessAsync(string fileName, string arguments, string workingDirectory, Func<byte[], Task<int>> writeInput = null)
    {
        var processInfo = new ProcessStartInfo
        {
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
            FileName = fileName,
            Arguments = arguments,
            WorkingDirectory = workingDirectory
        };

        using (var process = new Process())
        {
            process.StartInfo = processInfo;
            process.Start();

            using var outputStream = new MemoryStream();
            process.OutputDataReceived += (sender, e) =>
            {
                if (e.Data != null)
                {
                    await outputStream.WriteAsync(e.Data, 0, e.Data.Length);
                }
            };
            process.BeginOutputReadLine();

            using var errorStream = new MemoryStream();
            process.ErrorDataReceived += (sender, e) =>
            {
                if (e.Data != null)
                {
                    await errorStream.WriteAsync(e.Data, 0, e.Data.Length);
                }
            };
            process.BeginErrorReadLine();

            if (writeInput != null)
            {
                using var inputStream = process.StandardInput.BaseStream;
                await writeInput(await inputStream.ToArrayAsync());
            }

            var result = await process.WaitForExitAsync();

            return new ProcessResult(await outputStream.ToArrayAsync(), await errorStream.ToArrayAsync(), result);
        }
    }
}

