```csharp
using System;
using System.Configuration;
using System.Diagnostics;
using System.Net;

private void SetAppSettingsAndOpenUrl(string settingName, string userInput, string url)
{
    if (string.IsNullOrWhiteSpace(settingName) || string.IsNullOrWhiteSpace(userInput))
    {
        throw new ArgumentException("Setting name and user input cannot be null or whitespace.");
    }

    int configValue;
    if (!Int32.TryParse(userInput, out configValue) || configValue < 0)
    {
        throw new ArgumentException("User input must be a non-negative integer.");
    }

    Configuration config = ConfigurationManager.OpenExeConfiguration(ApplicationPath.GetExecutablePath());
    config.AppSettings.Settings[settingName].Value = userInput;
    config.Save();
    ConfigurationManager.RefreshSection("appSettings");

    Uri uri;
    if (!Uri.TryCreate(url, UriKind.Absolute, out uri))
    {
        throw new ArgumentException("Invalid URL format.");
    }

    string allowedSchemes = "http,https";
    string[] schemeParts = uri.Scheme.Split(':');
    if (!allowedSchemes.Split(',').Contains(schemeParts[0]))
    {
        throw new ArgumentException("URL scheme not allowed.");
    }

    Process.Start(url);
}
```

