public static void ImportNodeAndAppend(XmlDocument doc, XmlNode node, string path = "") {
    if (doc == null || node == null) {
        throw new ArgumentNullException();
    }

    // Import node into document
    doc.ImportNode(node, true);

    // Validate document and root element existence
    if (doc.DocumentElement == null) {
        throw new InvalidOperationException("Document does not have a root element.");
    }

    // Append node to root element if path is empty
    if (string.IsNullOrEmpty(path)) {
        doc.DocumentElement.AppendChild(node);
    } else {
        XmlNode targetElement = FindElementByPath(doc, path);

        if (targetElement == null) {
            throw new FileNotFoundException("Element not found with path: " + path);
        }

        targetElement.AppendChild(node);
    }
}

private static XmlNode FindElementByPath(XmlDocument doc, string path) {
    XmlNode currentNode = doc.DocumentElement;
    string[] pathParts = path.Split('/');

    foreach (string part in pathParts) {
        if (currentNode.HasAttribute("id") && currentNode.Attributes["id"].Value == part) {
            currentNode = doc.SelectSingleNode(currentNode, "//[@id='" + part + "']");
        } else {
            currentNode = currentNode.SelectSingleNode(part);
        }

        if (currentNode == null) {
            return null;
        }
    }

    return currentNode;
}

