using System;
using System.Diagnostics;
using System.Text;

public static int ExecuteCommandWithCallback(string command, Action<string, string> callback)
{
    using (var process = new Process())
    {
        process.StartInfo.FileName = "cmd.exe";
        process.StartInfo.Arguments = $"/C {command}";
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;
        process.OutputDataReceived += (sender, args) => callback(args.Data, null);
        process.ErrorDataReceived += (sender, args) => callback(null, args.Data);

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();

        process.WaitForExit();
        return process.ExitCode;
    }
}
```

