using System;
using System.IO;
using System.Xml.XPath;
using System.Xml.XDocument;

public class ConfigFileUpdater
{
    private readonly XDocument _configDocument;

    public ConfigFileUpdater(XDocument configDocument)
    {
        _configDocument = configDocument;
    }

    public XDocument UpdateXmlFile(string xpathToExistingSection, string newSectionXml, string xpathToInsertAfter)
    {
        if (!File.Exists(_configDocument.Root.Name.LocalName.ToString() + ".xml"))
        {
            throw new FileNotFoundException("The configuration file does not exist.");
        }

        XElement existingSection = _configDocument.XPathSelectElement(xpathToExistingSection);

        if (existingSection == null)
        {
            throw new XPathException("The specified existing section was not found.");
        }

        XElement newSection = XElement.Parse(newSectionXml);

        XElement elementToInsertAfter = _configDocument.XPathSelectElement(xpathToInsertAfter);

        if (elementToInsertAfter == null)
        {
            throw new XPathException("The specified element to insert after was not found.");
        }

        existingSection.AddAfterSelf(newSection);

        using (var writer = new XmlTextWriter(Path.ChangeExtension(Path.GetTempFileName(), ".xml"), null))
        {
            _configDocument.Save(writer);
            writer.Close();
        }

        File.Delete(Path.GetFileNameWithoutExtension(_configDocument.Root.Name.ToString()) + ".xml");
        File.Move(Path.GetTempFileName(), Path.GetFileNameWithoutExtension(_configDocument.Root.Name.ToString()) + ".xml");

        return XDocument.Load(Path.GetFileNameWithoutExtension(_configDocument.Root.Name.ToString()) + ".xml");
    }
}
