public class DatabaseWrapper
{
    private IDbConnection _connection;
    private IDbTransaction _transaction;

    public DatabaseWrapper(Guid instanceId)
    {
        _connection = DbFactory.CreateConnection();
        _connection.Open();
    }

    public int ExecuteNonQuery(Guid instanceId, byte[] sqlCommand, IsolationLevel isolationLevel)
    {
        using (IDbCommand cmd = _connection.CreateCommand())
        {
            cmd.CommandText = Encoding.UTF8.GetString(sqlCommand);
            int result;

            if (_transaction != null)
            {
                cmd.Transaction = _transaction;
            }

            try
            {
                _transaction = _connection.BeginTransaction(isolationLevel);
                cmd.ExecuteNonQuery();
                _transaction.Commit();
                result = cmd.RecordsAffected;
            }
            catch
            {
                _transaction.Rollback();
                throw;
            }

            return result;
        }
    }

    public object ExecuteScalar(Guid instanceId, byte[] sqlCommand, IsolationLevel isolationLevel)
    {
        using (IDbCommand cmd = _connection.CreateCommand())
        {
            cmd.CommandText = Encoding.UTF8.GetString(sqlCommand);

            if (_transaction != null)
            {
                cmd.Transaction = _transaction;
            }

            object result = cmd.ExecuteScalar();
            return result;
        }
    }

    public byte[] DeriveParameters(Guid instanceId, byte[] sqlCommand)
    {
        using (IDbCommand cmd = _connection.CreateCommand())
        {
            cmd.CommandText = Encoding.UTF8.GetString(sqlCommand);
            IDataParameter[] parameters = cmd.Parameters.OfType<IDbDataParameter>();

            byte[] result = new byte[cmd.Parameters.Count * (IntPtr.Size / 8)];

            for (int i = 0; i < parameters.Length; i++)
            {
                byte[] parameterBytes = BitConverter.GetBytes(parameters[i].ParameterName.GetHashCode());
                Buffer.BlockCopy(parameterBytes, 0, result, i * (IntPtr.Size / 8), parameterBytes.Length);
            }

            return result;
        }
    }

