```csharp using System;
using System.Xml;

public static Dictionary<string, string> LoadConfiguration(string configFilePath)
{
    if (string.IsNullOrEmpty(configFilePath))
    {
        throw new ArgumentNullException(nameof(configFilePath));
    }

    XmlDocument doc = new XmlDocument();

    try
    {
        using (var fileStream = File.OpenRead(configFilePath))
        {
            doc.Load(fileStream);
        }
    }
    catch (XmlException ex)
    {
        throw new ConfigurationException("Error loading XML configuration file.", ex);
    }

    var configuration = new Dictionary<string, string>();
    XmlNode rootNode = doc.DocumentElement;

    if (rootNode == null)
    {
        throw new ConfigurationException("XML document does not have a root element.");
    }

    XmlNodeList nodeList = rootNode.ChildNodes;

    foreach (XmlNode node in nodeList)
    {
        if (node.NodeType != XmlNodeType.Element)
        {
            continue;
        }

        configuration.Add(node.Name, node.InnerText);
    }

    return configuration;
}

public class ConfigurationException : Exception
{
    public ConfigurationException(string message) : base(message)
    {
    }

    public ConfigurationException(string message, Exception innerException) : base(message, innerException)
    {
    }
}
