using System.Diagnostics;
using System.Threading.Tasks;

public delegate string CallbackFunction(string output, string error);

public static Task<int> ExecuteProcessWithCallback(string filePath, string arguments, CallbackFunction callback)
{
    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = filePath,
        Arguments = arguments,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = true
    };

    using (Process process = new Process())
    {
        process.StartInfo = startInfo;
        process.Start();

        CancellationTokenSource cts = new CancellationTokenSource();

        return Task.Factory.StartNew(() =>
        {
            int exitCode = process.ExitCode;
            string output = null;
            string error = null;

            using (AutoResetEvent outputEvent = new AutoResetEvent(false))
            using (AutoResetEvent errorEvent = new AutoResetEvent(false))
            {
                process.OutputDataReceived += (sender, e) =>
                {
                    if (e.Data != null)
                    {
                        output = e.Data;
                        outputEvent.Set();
                    }
                };

                process.ErrorDataReceived += (sender, e) =>
                {
                    if (e.Data != null)
                    {
                        error = e.Data;
                        errorEvent.Set();
                    }
                };

                cts.CancelAfter(TimeSpan.FromSeconds(30));

                process.BeginOutputReadLine();
                process.BeginErrorReadLine();

                WaitHandle waitHandle = WaitHandle.Combine(outputEvent.AsyncWaitHandle, errorEvent.AsyncWaitHandle);
                waitHandle.WaitOne(cts.Token);

                if (callback != null)
                {
                    output = callback(output, error);
                }
            }

            return exitCode;
        }, cts.Token);
    }
}
