public class ApplicationUser : IUser
{
    public string Username { get; set; }
    public string Password { get; set; }
    public string FullName { get; set; }
    public string Email { get; set; }
    public string Role { get; set; }

    public static ApplicationUser Login(string username, string password)
    {
        // Validate username and password against the authentication service.
        if (!IsValidUsername(username) || !IsValidPassword(password))
        {
            return null;
        }

        using (var context = new ApplicationDbContext())
        {
            var user = context.Users.FirstOrDefault(u => u.Username == username);

            if (user == null)
            {
                // User doesn't exist in the database.
                return null;
            }

            if (!VerifyHashedPassword(user.PasswordHash, password))
            {
                // Incorrect password.
                return null;
            }

            // User is authenticated. Add user to roles and insert into database.
            using (var transaction = context.Database.BeginTransaction())
            {
                try
                {
                    // Validate role before assigning it.
                    if (!IsValidRole(user.Role))
                    {
                        throw new ArgumentException("Invalid role.");
                    }

                    // Assign role to the user.
                    user.Role = user.Role; // No need to change it if it's already valid.

                    context.SaveChanges();

                    // Commit the transaction.
                    transaction.Commit();
                }
                catch
                {
                    // Rollback the transaction in case of an error.
                    transaction.Rollback();
                    throw;
                }
            }

            // Create a new view model with the user's information.
