```csharp
using System;
using System.IO;
using System.Text.RegularExpressions;
using System.Xml.Linq;

public class TravelItem
{
    public string GeocacheCode { get; set; }
    public DateTime DateLogged { get; set; }
    public double Lat { get; set; }
    public double Lon { get; set; }
}

public List<TravelItem> ParseGeocacheHtml(string resourceName)
{
    if (string.IsNullOrEmpty(resourceName))
    {
        throw new ArgumentNullException(nameof(resourceName));
    }

    try
    {
        using (Stream stream = typeof(Program).Assembly.GetManifestResourceStream(resourceName))
        {
            if (stream == null)
            {
                throw new FileNotFoundException(resourceName);
            }

            using (StreamReader reader = new StreamReader(stream))
            {
                string htmlContent = reader.ReadToEnd();
                XDocument document = XDocument.Parse(htmlContent);

                List<TravelItem> travelItems = new List<TravelItem>();

                XNamespace ns = "http://www.w3.org/1999/xhtml";
                XElement html = document.Descendants(ns + "div").FirstOrDefault(e => e.Name.LocalName == "div" && e.Attribute("id").Value == "geocache_list");

                if (html != null)
                {
                    foreach (XElement li in html.Descendants(ns + "li"))
                    {
                        TravelItem travelItem = new TravelItem();
                        travelItem.GeocacheCode = li.Descendants(ns + "a").FirstOrDefault()?.Attribute("href")?.Value.Split('/')[1];
                        travelItem.DateLogged = DateTime.Parse(li.Descendants(ns + "span")[1].Value);
                        travelItem.Lat = double.Parse(Regex.Match(li.Descendants(ns + "span")[3].Value, @"\d+(?:\.\d+)?").Value);
                        travelItem.Lon = double.Parse(Regex.Match(li.Descendants(ns + "span")[4].Value, @"\d+(?:\.\d+)?").Value);
                        travelItems.Add(travelItem);
                    }
                }

                return travelItems;
            }
        }
    }
    catch (Exception ex)
    {
        throw new SynapseError("Error parsing geocache HTML", ex);
