public async Task<int> GetNextVersionAsync(int streamId, int currentVersion)
{
    int nextVersion = -1;

    using (var connection = new SqlConnection("YourConnectionStringHere"))
    {
        await connection.OpenAsync();

        using (var command = new SqlCommand("GetNextVersion", connection))
        {
