using System.Diagnostics;
using System.Text;

/// <summary>
/// Establishes a remote connection to a specified host using the 'net use' command.
/// </summary>
/// <param name="remoteHost">The IP address of the remote host.</param>
/// <param name="userName">The user name to use for the connection.</param>
/// <param name="password">The password to use for the connection.</param>
/// <returns>A boolean value indicating whether the connection was successful.</returns>
public static bool ConnectToRemoteHost(string remoteHost, string userName, string password)
{
    bool connectionSuccess = false;
    ProcessStartInfo startInfo = new ProcessStartInfo();
    startInfo.FileName = "cmd.exe";
    startInfo.UseShellExecute = false;
    startInfo.RedirectStandardInput = true;
    startInfo.RedirectStandardOutput = true;
    startInfo.RedirectStandardError = true;
    startInfo.CreateNoWindow = true;

    using (Process process = new Process())
    {
        process.StartInfo = startInfo;
        process.Start();

        string command = $"net use \\{remoteHost} {userName}:{Environment.NewLine} {password} {Environment.NewLine} /persistent:no >NUL 2>&1";
        process.StandardInput.WriteLine(command);
        process.StandardInput.Close();

        string output = process.StandardOutput.ReadToEnd();
        string error = process.StandardError.ReadToEnd();

        if (output.Contains("The network connection could not be found.") || error.Contains("The network path was not found."))
        {
            connectionSuccess = false;
        }
        else
        {
            connectionSuccess = true;
        }

        process.WaitForExit();
    }

    return connectionSuccess;
}
