    public int MinPasswordLength { get; set; } = 8;
    public bool RequireDigit { get; set; } = true;
    public bool RequireUppercase { get; set; } = true;
    public bool RequireLowercase { get; set; } = true;
    public bool RequireSpecialCharacter { get; set; } = true;
    public int PasswordLockoutThreshold { get; set; } = 5;
    public int PasswordLockoutDuration { get; set; } = 30;
}

public class CustomPasswordValidator : IPasswordValidator<IdentityUser>
{
    private readonly ApplicationOptions _options;

    public CustomPasswordValidator(IOptions<ApplicationOptions> options)
    {
        _options = options.Value;
    }

    public virtual Task<IdentityResult> ValidateAsync(IdentityUser user, string password)
    {
        if (string.IsNullOrEmpty(password))
        {
            return Task.FromResult(IdentityResult.Failed("Password cannot be empty."));
        }

        if (!Regex.IsMatch(user.UserName, _options.UsernameRegex))
        {
            return Task.FromResult(IdentityResult.Failed("Invalid username format."));
        }

        if (password.Length < _options.MinPasswordLength)
        {
            return Task.FromResult(IdentityResult.Failed("Password must be at least {0} characters long.", _options.MinPasswordLength));
        }

        if (_options.RequireDigit && !PasswordValidatorHelper.HasDigit(password))
        {
            return Task.FromResult(IdentityResult.Failed("Password must contain at least one digit."));
        }

        if (_options.RequireUppercase && !PasswordValidatorHelper.HasUpper(password))
        {
            return Task.FromResult(IdentityResult.Failed("Password must contain at least one uppercase letter."));
        }

        if (_options.RequireLowercase && !PasswordValidatorHelper.HasLower(password))
        {
            return Task.FromResult(IdentityResult.Failed("Password must contain at least one lowercase letter."));
        }

        if (_options.RequireSpecialCharacter && !PasswordValidatorHelper.HasSpecialCharacters(password))
        {
            return Task.FromResult(IdentityResult.Failed("Password must contain at least one special character."));
        }

        return Task.FromResult(IdentityResult.Success);
    }
}

public class CustomIdentityOptions : IdentityOptions
{
    public CustomIdentityOptions(IOptions<ApplicationOptions> options) : base()
    {
        PasswordValidator = new CustomPasswordValidator(options);
        PasswordLockoutEnabled = true;
        PasswordLockoutThreshold = _options.PasswordLockoutThreshold;
        PasswordLockoutDuration = TimeSpan.FromMinutes(_options.PasswordLockoutDuration);
    }
