namespace SafeProcessRunner
{
    public static class ProcessRunner
    {
        public static void Start(string executablePath, string arguments, TimeSpan timeout)
        {
            if (string.IsNullOrEmpty(executablePath) || string.IsNullOrEmpty(arguments))
            {
                throw new ArgumentException("ExecutablePath and Arguments must not be null or empty.");
            }

            using (var process = new Process())
            {
                process.StartInfo.FileName = executablePath;
                process.StartInfo.Arguments = arguments;
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.RedirectStandardOutput = false;
                process.StartInfo.CreateNoWindow = true;

                process.Start();

                if (!process.WaitForExit(Convert.ToInt32(timeout.TotalMilliseconds)))
                {
                    process.Kill();
                    throw new TimeoutException($"Process '{executablePath}' did not finish executing within the specified timeout '{timeout}'.");
                }
            }
        }
    }
