using System.Xml.XPath;

public static XPathNavigator GetFirstElementByName(XPathDocument document, string elementName)
{
    if (document == null)
    {
        throw new ArgumentNullException(nameof(document));
    }

    XPathNavigator navigator = document.CreateNavigator();
    XPathExpression expression = XPathExpression.Compile(string.Format("//{0}", elementName));

    XPathNodeIterator nodeIterator = navigator.Select(expression, null, XPathResultType.FirstOrDefault);

    if (nodeIterator == null || nodeIterator.MoveNext())
    {
        throw new ElementNotFoundException("Element not found or multiple elements with the same name.");
    }

    return nodeIterator.Current;
}

public class ElementNotFoundException : Exception
{
    public ElementNotFoundException(string message) : base(message)
    {
    }
}
