public static bool RunAsRealUser(string userName, string pathToExecutable, string arguments, out string errorMessage)
{
    errorMessage = string.Empty;

    try
    {
        using (ProcessStartInfo startInfo = new ProcessStartInfo())
        {
            startInfo.FileName = pathToExecutable;
            startInfo.Arguments = arguments;
            startInfo.UseShellExecute = true;
            startInfo.Verb = "runas";
            startInfo.CreateNoWindow = true;
            startInfo.RedirectStandardOutput = false;
            startInfo.RedirectStandardError = true;

