                using (StreamReader errorStream = process.StandardError)
                {
                    string errorOutput = errorStream.ReadToEnd();
                    if (!string.IsNullOrEmpty(errorOutput))
                    {
                        errorMessage = $"Error output from process: {errorOutput}";
                        return false;
                    }
                }

                process.WaitForExit();
                return process.ExitCode == 0;
            }
        }
    }
    catch (Exception ex)
    {
        errorMessage = $"Exception during process startup: {ex.Message}";
        return false;
    }
}
