```csharp using System;
using System.Xml;

public static List<KeyValuePair<string, string>> LoadXmlConfiguration(string filePath)
{
    if (string.IsNullOrEmpty(filePath))
    {
        throw new ArgumentNullException(nameof(filePath));
    }

    XmlDocument document = new XmlDocument();

    try
    {
        using (var stream = File.OpenRead(filePath))
        {
            document.Load(stream);
        }
    }
    catch (XmlException ex)
    {
        throw new ArgumentException("Invalid XML configuration file.", nameof(filePath), ex);
    }

    XmlNode configurationNode = document.DocumentElement.SelectSingleNode("configuration");
    if (configurationNode == null)
    {
        throw new ConfigurationException("XML file does not contain a 'configuration' element.");
    }

    var settings = new List<KeyValuePair<string, string>>();

    foreach (XmlNode settingNode in configurationNode.SelectNodes("setting"))
    {
        if (settingNode == null)
        {
            continue;
        }

        string key = settingNode.Attributes["name"].Value;
        string value = settingNode.InnerText;

        settings.Add(new KeyValuePair<string, string>(key, value));
    }

    return settings;
}
