public class ProcessResult
{
    public string Output { get; }
    public string Error { get; }
    public int ExitCode { get; }

    public ProcessResult(string output, string error, int exitCode)
    {
        Output = output;
        Error = error;
        ExitCode = exitCode;
    }
}

public static async Task<ProcessResult> ExecuteCommandLineUtility(string utilityPath, string arguments, string workingDirectory, params string[] environmentVariables)
{
    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = utilityPath,
        Arguments = arguments,
        UseShellExecute = false,
        RedirectStandardInput = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        CreateNoWindow = true,
        WorkingDirectory = workingDirectory
    };

    if (environmentVariables != null && environmentVariables.Length > 0)
    {
        EnvironmentVariables env = Environment.GetEnvironmentVariables();
        foreach (string envVar in environmentVariables)
        {
            int equalsIndex = envVar.IndexOf('=');
            string name = equalsIndex > 0 ? envVar.Substring(0, equalsIndex) : envVar;
            env[name] = envVar;
        }
        startInfo.EnvironmentVariables = env;
    }

    using (Process process = new Process())
    {
        process.StartInfo = startInfo;
        process.Start();

        using (StreamReader outputReader = new StreamReader(process.StandardOutput.BaseStream))
        using (StreamReader errorReader = new StreamReader(process.StandardError.BaseStream))
        {
            string output = await outputReader.ReadToEndAsync();
            string error = await errorReader.ReadToEndAsync();

            await process.WaitForExitAsync();

            return new ProcessResult(output, error, process.ExitCode);
        }
    }
}
