void ValidateXmlDocument(string xmlData, string xsdData)
{
    XmlReaderSettings settings = new XmlReaderSettings();
    settings.ValidationType = ValidationType.Schema;
    settings.Schemas.Add(new XmlSchema(XmlSchema.Read(new StringReader(xsdData), null)));

    using (XmlReader reader = XmlReader.Create(new StringReader(xmlData), settings))
    {
        if (settings.GetErrorStream() != null)
        {
            string errorMessage = string.Empty;
            using (StreamReader errorReader = new StreamReader(settings.GetErrorStream()))
            {
                errorMessage = errorReader.ReadToEnd();
            }
            settings.GetErrorStream().Close();
            settings.GetErrorStream() = null; // Clear the error stream for reuse
            throw new Exception("XML validation failed: " + errorMessage);
        }

        while (reader.Read()) { }
    }
}
