```csharp using System; using System.Collections.Generic; using System.Security.Cryptography;

public class Resource
{
    public byte[] ByteArray { get; set; }
    public string MimeType { get; set; }
    public string Hash { get; set; }

    public Resource(byte[] byteArray, string mimeType)
    {
        ByteArray = byteArray;
        MimeType = mimeType;
        Hash = ComputeMd5Hash(byteArray);
    }

    private static string ComputeMd5Hash(byte[] data)
    {
        using (MD5 md5Hash = MD5.Create())
        {
            byte[] hash = md5Hash.ComputeHash(data);
            return BitConverter.ToString(hash).Replace("-", "").ToLower();
        }
    }
}

public static List<Resource> ComputeResourcesHashes(List<(byte[] data, string mimeType)> resources)
{
    List<Resource> result = new List<Resource>();

    foreach (var resource in resources)
    {
        if (resource.data == null || resource.mimeType == null)
        {
            throw new ArgumentNullException(nameof(resources), "Both data and mimeType must be provided for each resource.");
        }

        Resource newResource = new Resource(resource.data, resource.mimeType);
        result.Add(newResource);
    }

    return result;
}
