public static async Task<ProcessResult> ExecuteProcessAsync(string fileName, string arguments, string workingDirectory, IDictionary<string, string> environmentVariables = null)
{
    using (Process process = new Process())
    {
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardInput = true;
