        await process.StartAsync();

        using (StreamReader input = process.StandardInput)
        using (StreamReader output = new StreamReader(process.StandardOutput))
        using (StreamReader error = new StreamReader(process.StandardError))
        {
            await process.WaitForExitAsync();

            return new ProcessResult(output.ReadToEnd(), error.ReadToEnd(), process.ExitCode);
        }
    }
}

