using System;
using System.Runtime.Serialization.Formatters.Binary;

public static class BinaryFormatterHelper
{
    public static string SerializeObjectToBase64(object obj)
    {
        if (obj == null)
            throw new ArgumentNullException(nameof(obj));

        using (var memoryStream = new MemoryStream())
        {
            new BinaryFormatter().Serialize(memoryStream, obj);
            memoryStream.Position = 0;
            var base64String = Convert.ToBase64String(memoryStream.ToArray());
            memoryStream.Close();
            return base64String;
        }
    }

    public static T DeserializeObjectFromBase64<T>(string base64EncodedData)
    {
        if (string.IsNullOrEmpty(base64EncodedData))
            throw new ArgumentNullException(nameof(base64EncodedData));

        using (var memoryStream = new MemoryStream(Convert.FromBase64String(base64EncodedData)))
        {
            memoryStream.Position = 0;
            using (var binaryFormatter = new BinaryFormatter())
            {
                object obj = binaryFormatter.Deserialize(memoryStream);
                if (obj is T)
                    return (T)obj;
                else
                    throw new InvalidOperationException("Deserialized object is not of the expected type.");
            }
        }
    }
}
