using System;
using System.Xml;

void ValidateXmlDocument(string xmlData, string xsdData)
{
    XmlReaderSettings readerSettings = new XmlReaderSettings();
    readerSettings.ValidationType = ValidationType.Schema;
    readerSettings.Schemas.Add(new XmlSchema(XmlSchema.Read(new StringReader(xsdData), null)));

    try
    {
        using (XmlReader xmlReader = XmlReader.Create(new StringReader(xmlData), readerSettings))
        {
            if (xmlReader.IsValid)
            {
                Console.WriteLine("XML document is valid.");
            }
            else
            {
                Console.WriteLine("XML document is invalid. Error(s):");
                while (xmlReader.HasErrors)
                {
                    Console.WriteLine($"Line {xmlReader.LineNumber}, position {xmlReader.LinePosition}: {xmlReader.ErrorMessage}");
                    xmlReader.MoveToNextError();
                }
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"An error occurred while validating the XML document: {ex.Message}");
    }
}
