using System.Diagnostics;
using System.Threading.Tasks;

public static async Task<ProcessResult> ExecuteSafeProcess(string fileName, string arguments)
{
    ProcessStartInfo psi = new ProcessStartInfo
    {
        FileName = fileName,
        Arguments = arguments,
        UseShellExecute = false,
        RedirectStandardOutput = true,
        CreateNoWindow = true
    };

    using (Process process = new Process())
    {
        process.StartInfo = psi;
        process.Start();

        using (Task processWaiter = Task.Factory.StartNew(() => process.WaitForExit()))
        using (Task<string> outputReader = Task.Factory.StartNew(() => process.StandardOutput.ReadToEnd()))
        {
            await Task.WhenAll(processWaiter, outputReader);

            return new ProcessResult(outputReader.Result, "", process.ExitCode);
        }
    }
}

public struct ProcessResult
{
    public string Output { get; }
    public string Error { get; }
    public int ExitCode { get; }

    public ProcessResult(string output, string error, int exitCode)
    {
        Output = output;
        Error = error;
        ExitCode = exitCode;
    }
