public static string TripleDesEncrypt(string inputData, Guid key1, Guid key2)
{
    if (string.IsNullOrEmpty(inputData)) return string.Empty;

    using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
    {
        byte[] key1Bytes = key1.ToByteArray();
        byte[] key2Bytes = key2.ToByteArray();

        byte[] inputBytes = Encoding.UTF8.GetBytes(inputData);

        ICryptoTransform cryptoTransform = tripleDes.CreateEncryptor(key1Bytes, key2Bytes);
        byte[] outputBuffer = cryptoTransform.TransformFinalBlock(inputBytes, 0, inputBytes.Length);

        byte[] combinedKeys = new byte[key1Bytes.Length + key2Bytes.Length];
        Buffer.BlockCopy(key1Bytes, 0, combinedKeys, 0, key1Bytes.Length);
        Buffer.BlockCopy(key2Bytes, 0, combinedKeys, key1Bytes.Length, key2Bytes.Length);

        tripleDes.Key = combinedKeys;
        cryptoTransform = tripleDes.CreateEncryptor();

        byte[] finalOutput = cryptoTransform.TransformFinalBlock(outputBuffer, 0, outputBuffer.Length);

        return Convert.ToBase64String(finalOutput);
    }
}

