                    process.Start();

                    process.StandardInput.Write(ms.ToArray(), 0, ms.Length);
                    process.StandardInput.Close();

                    string output = process.StandardOutput.ReadToEnd();
                    Console.WriteLine(output);

                    process.WaitForExit();
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
