using System;
using System.IO;
using System.Xml.XPath;

public class ConfigFileUpdater
{
    private const string ConfigFilePath = "config.xml";

    private XDocument _configDocument;

    public ConfigFileUpdater(XDocument configDocument)
    {
        _configDocument = configDocument;
    }

    public ConfigFileUpdater(string configFilePath)
    {
        _configDocument = XDocument.Load(configFilePath);
    }

    public int RemoveSection(string xpathToSection)
    {
        if (!_configDocument.HasElements)
        {
            throw new ArgumentException("Configuration file is empty.");
        }

        XElement sectionToRemove = _configDocument.XPathSelectElement(xpathToSection);

        if (sectionToRemove == null)
        {
            throw new ArgumentException("Section not found.");
        }

        _configDocument.Root.Element(XName.Element(sectionToRemove.Name))?.Remove();

        int nodesRemoved = _configDocument.XPathSelectElements(xpathToSection).Count();

        SaveConfiguration();

        return nodesRemoved;
    }

    private void SaveConfiguration()
    {
        using (FileStream fileStream = File.OpenWrite(ConfigFilePath))
        using (TextWriter textWriter = new StreamWriter(fileStream))
        {
            _configDocument.Save(textWriter);
        }
    }
}
