using System.Xml.XPath;
using System.IO;

public class ConfigFileUpdater
{
    private readonly XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument;
    }

    public XDocument UpdateXmlFile(string xpathToExistingSection, string xmlElementToInsert, string xpathToInsertAfter)
    {
        XElement existingSection = _xmlDocument.XPathSelectElement(xpathToExistingSection);

        if (existingSection == null)
        {
            throw new ArgumentException("The specified existing section does not exist in the configuration file.");
        }

        XElement newSection = XElement.Parse(xmlElementToInsert);

        existingSection.AddAfterSelf(newSection);

        XElement insertPoint = _xmlDocument.XPathSelectElement(xpathToInsertAfter);

        if (insertPoint == null)
        {
            throw new ArgumentException("The specified insert point does not exist in the configuration file.");
        }

        insertPoint.AddAfterSelf(existingSection);

        return _xmlDocument;
    }
}

