public void StartCommandPrompt()
{
    string cmdExecutable = "cmd.exe";
    string arguments = "/c"; // for running a command and then closing the command prompt

    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = cmdExecutable,
        Arguments = arguments,
        UseShellExecute = false, // false for redirecting input/output streams
        RedirectStandardOutput = false,
        RedirectStandardError = false,
        CreateNoWindow = true // for not displaying the command prompt window
    };

    using (Process process = new Process())
    {
        process.StartInfo = startInfo;
        process.Start();

        process.Exited += (sender, args) =>
        {
            process.Dispose(); // ensure proper cleanup when the parent window is unloaded
        };
    }
}
