public XPathNavigator GetMethodNode(ActionDescriptor actionDescriptor)
{
    if (actionDescriptor == null) return null;

    XPathDocument xmlDocument = XPathDocument.Load(new StringReader(actionDescriptor.ControllerDescriptor.ControllerType.GetType().GetField("ViewData").GetValue(actionDescriptor.ControllerContext.Controller) as string));
