public class SecureHashAlgorithm
{
    public string Name { get; }
    public HashAlgorithm Algo { get; }

    private SecureHashAlgorithm(string algoName, HashAlgorithm algo)
    {
        Name = algoName;
        Algo = algo;
    }

    public static SecureHashAlgorithm MD5 { get { return new SecureHashAlgorithm("MD5", MD5.Create()); } }
    public static SecureHashAlgorithm SHA256 { get { return new SecureHashAlgorithm("SHA256", SHA256.Create()); } }
