```csharp using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public T LastObjectInFile<T>(string filePath) where T : new()
{
    if (!File.Exists(filePath))
    {
        throw new FileNotFoundException("File not found.", filePath);
    }

    using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
    {
        var bFormatter = new BinaryFormatter();
        var objects = new List<object>();

        while (fileStream.Position != fileStream.Length)
        {
            objects.Add(bFormatter.Deserialize(fileStream));
        }

        fileStream.Seek(0, SeekOrigin.Begin);

        if (objects.Count > 0)
        {
            var lastObject = objects[objects.Count - 1];
            if (typeof(T).IsAssignableFrom(lastObject.GetType()))
            {
                return (T)lastObject;
            }
            else
            {
                throw new InvalidOperationException("Last object in file is not of the expected type.");
            }
        }
        else
        {
            throw new InvalidDataException("File is empty.");
        }
    }
}
```

