public static void TestEncryptionDecryption(SymmetricAlgorithm algorithm, byte[] key, byte[] plaintext)
{
    if (algorithm == null) throw new ArgumentNullException(nameof(algorithm));
    if (key == null) throw new ArgumentNullException(nameof(key));
    if (plaintext == null) throw new ArgumentNullException(nameof(plaintext));

    int keySize = algorithm.KeySize;
    int effectiveKeySize = algorithm.BlockSize * 8; // assuming ECB mode and zero padding
