using System;
using System.Xml;

void ValidateXmlAgainstXsd(string xmlData, string xsdData)
{
    XmlReader xmlReader = XmlReader.Create(new StringReader(xmlData));
    XmlReaderSettings settings = new XmlReaderSettings();
    settings.ValidationType = ValidationType.Schema;
    settings.Schemas.Add(new XmlSchema(XmlSchema.Read(new StringReader(xsdData), null)));
    settings.CheckCharacters = false; // Disable checking of individual characters
    settings.ValidationFlags |= XmlSchemaValidationFlags.ReportValidationWarnings;

    using (XmlReader schemaReader = XmlReader.Create(new StringReader(xsdData)))
    {
        XmlSchema schema = XmlSchema.Read(schemaReader, null);
        settings.Schemas.Add(schema);
    }

    bool isValid = false;
    try
    {
        using (XmlReader validatingReader = XmlReader.Create(xmlReader, settings))
        {
            validatingReader.MoveToContent();
            isValid = validatingReader.IsStartElement();
        }
    }
    catch (XmlSchemaValidationException ex)
    {
        Console.WriteLine("Validation failed: " + ex.Message);
    }

    if (isValid)
        Console.WriteLine("XML document is valid against the XSD schema.");
}
