public void shufflePairs(List<Pair> pairs, double percentage) {
    Random random = new Random();
    int totalIterations = (int) Math.ceil(pairs.size() * percentage / 100.0);
    int currentIteration = 0;
    int currentIndex = pairs.size() - 1;

    while (currentIteration < totalIterations) {
        boolean isLastPair = (currentIndex == pairs.size() - 1);
        if (isLastPair) {
            System.out.println("Last pair: " + pairs.get(currentIndex));
        } else {
