```java
import static java.nio.file.StandardOpenOption.*;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileAttribute;
import java.security.SecureRandom;

public static FileStore.FileHandle generateRandomFile(FileSystem fs, Path folder, String fileName, long fileSize) throws IOException {
    SecureRandom random = new SecureRandom();
    Path filePath = folder.resolve(fileName);
    try (FileChannel channel = Files.newByteChannel(filePath, CREATE_NEW, WRITE, READ_ONLY)) {
        ByteBuffer buffer = ByteBuffer.allocate((int) fileSize);
        for (long i = 0; i < fileSize; ) {
            if (random.nextBoolean()) {
                buffer.put((byte) random.nextByte());
                i++;
            } else {
                int len = Math.min((int) (fileSize - i), 32);
                byte[] bytes = new byte[len];
                random.nextBytes(bytes);
                buffer.put(ByteBuffer.wrap(bytes));
                i += len;
            }
        }
        buffer.flip();
        channel.write(buffer);
        FileAttribute<FileTime> lastModified = FileTime.from(System.currentTimeMillis(), ZoneId.systemDefault());
        Files.setLastModifiedTime(filePath, lastModified);
        return channel.size() > 0 ? channel.size() : null;
    }
}
