import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

public class Normalizer<E, T> {
    private final List<WeightedItem<E, T>> weightedItems;
    private final Function<E, Double> elemFunc;
    private final Function<E, Double> weightFunc;
    private final Random rnd;

    public Normalizer(List<WeightedItem<E, T>> weightedItems, Function<E, Double> elemFunc, Function<E, Double> weightFunc) {
        this.weightedItems = weightedItems;
        this.elemFunc = elemFunc;
        this.weightFunc = weightFunc;
        this.rnd = new Random();
    }

    public Map<T, Double> normalize() {
        double totalWeight = 0.0;
        for (WeightedItem<E, T> item : weightedItems) {
            double normalizedWeight = weightFunc.apply(item.getItem()) / calculateTotalWeight();
            totalWeight += normalizedWeight;
            item.setNormalizedWeight(normalizedWeight);
        }
        return createNormalizedMap();
    }

    private double calculateTotalWeight() {
        double sum = 0.0;
        for (WeightedItem<E, T> item : weightedItems) {
            sum += weightFunc.apply(item.getItem());
        }
        return sum;
    }

    private Map<T, Double> createNormalizedMap() {
        Map<T, Double> normalized = new HashMap<>();
        for (WeightedItem<E, T> item : weightedItems) {
            normalized.put(item.getItem(), item.getNormalizedWeight());
        }
        return normalized;
    }

    static class WeightedItem<E, T> {
        private final E item;
        private double normalizedWeight;

        public WeightedItem(E item) {
            this.item = item;
        }

        public E getItem() {
            return item;
        }

        public void setNormalizedWeight(double normalizedWeight) {
            this.normalizedWeight = normalizedWeight;
        }
    }
}
