import java.util.Arrays;
import java.util.Random;
import java.util.concurrent.TimeUnit;

public class DisjointPairs {
    static long pairCheck(int[] arr) {
        int n = arr.length;
        int[] parent = new int[n]; // initialize to zero

        int count = 0;
        long startTime, endTime;

        for (int i = 0; i < n; i++) {
            int rootI = find(i, parent);
            for (int j = i + 1; j < n; j++) {
                startTime = System.nanoTime();
                int rootJ = find(j, parent);
                endTime = System.nanoTime();

                if (rootI != rootJ) {
                    count++;
                }

                if (System.nanoTime() - startTime > 1000000) { // print every 1ms
                    System.out.printf("Pair %d, %d checked in %d ms%n", i, j, (endTime - startTime) / 1000000);
                }

                union(i, j, parent);
            }
        }

        return count;
    }

    static int find(int i, int[] parent) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i], parent);
    }

    static void union(int i, int j, int[] parent) {
        int rootI = find(i, parent);
        int rootJ = find(j, parent);

        if (rootI != rootJ) {
            parent[rootI] = rootJ;
        }
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6, 7, 8, 9};
        long startTime = System.nanoTime();
        int count = pairCheck(arr);
        long endTime = System.nanoTime();

        System.out.printf("Total number of disjoint pairs: %d%n", count);
        System.out.printf("Total time taken: %d ms%n", (endTime - startTime) / 1000000);
    }
}
