import org.apache.commons.math3.util.Precision;
import java.security.SecureRandom;

public RectF cropDrawable(RectF drawableBounds, RectF viewportRect) {
    float drawableRatio = drawableBounds.height() / drawableBounds.width();
    float viewportRatio = viewportRect.height() / viewportRect.width();

    RectF maxCrop = new RectF();
    if (drawableRatio > viewportRatio) {
        float r = Precision.round(viewportRect.width() * drawableRatio);
        float b = drawableBounds.height();
        maxCrop.set(0, 0, r, b);
    } else {
        float r = Precision.round(drawableBounds.width() * viewportRatio);
        float b = Precision.round(drawableBounds.width() * viewportRatio * drawableRatio);
        maxCrop.set(0, 0, r, b);
    }

    SecureRandom random = new SecureRandom();
    float factor = 1 - (new Float(Math.random()) * 0.5f); // Random number between 0 and 0.5
    float width = factor * maxCrop.width();
    float height = factor * maxCrop.height();

    int widthDiff = (int) (drawableBounds.width() - (float) width);
    int heightDiff = (int) (drawableBounds.height() - (float) height);

    int left = widthDiff > 0 ? random.nextInt(widthDiff) : 0;
    int top = heightDiff > 0 ? random.nextInt(heightDiff) : 0;

    return new RectF(left, top, left + (int) width, top + (int) height);
}
