import org.apache.hadoop.security.delegation.DelegationTokenIdentifier;
import org.apache.hadoop.security.delegation.DelegationTokenManager;

public boolean manageDelegationToken(String userCredentials, DelegationTokenIdentifier tokenIdentifier, DelegationTokenManager delegationTokenManager) {
    try {
        UserGroupInformation user = UserGroupInformation.getCredentials(userCredentials);
        Token currentToken = user.doAs(delegationTokenManager::getDelegationToken, tokenIdentifier);

        if (currentToken != null) {
            System.out.println("Token already exists: " + currentToken.toString());
            return true;
        }

        Token newToken = delegationTokenManager.createNewToken(user, tokenIdentifier);
        System.out.println("New token created: " + newToken.toString());
        return newToken != null;
    } catch (Exception e) {
        if (e instanceof AccessControlException) {
            System.err.println("Access control exception: " + e.getMessage());
            return false;
        }
        System.err.println("Error creating, verifying, renewing, or cancelling token: " + e.getMessage());
        return false;
    }
}

public Token verifyAndRenewOrCreateDelegationToken(String userCredentials, DelegationTokenIdentifier tokenIdentifier, DelegationTokenManager delegationTokenManager) {
    boolean tokenManaged = manageDelegationToken(userCredentials, tokenIdentifier, delegationTokenManager);
    if (!tokenManaged) {
        return null;
    }

    try {
        Token token = delegationTokenManager.getToken(tokenIdentifier);
        if (token != null && token.getRenewUntil() > System.currentTimeMillis()) {
            Token renewedToken = delegationTokenManager.renewToken(token);
            System.out.println("Token renewed: " + renewedToken.toString());
            return renewedToken;
        }
    } catch (Exception e) {
        System.err.println("Error renewing token: " + e.getMessage());
    }

    return manageDelegationToken(userCredentials, tokenIdentifier, delegationTokenManager);
}

