    public static List<SensorData> generateSensorData(List<LocationTime> locationTimes, List<double[]> accStds, double stepPerSec) {
        List<SensorData> sensorDataList = new ArrayList<>();
        double currentTime = locationTimes.get(0).getTimestamp();

