public class CommandChecker {
    private static final Pattern NOTES_PATTERN = Pattern.compile("(.*)Notes.*(.*)");
    private boolean patternFound = false;

    public boolean checkForNotesPresence(String command, String outputPattern, int sleepTime) throws InterruptedException, IOException {
        Process process = Runtime.getRuntime().exec(command);
        process.waitFor();

        if (process.exitValue() != 0) {
            throw new RuntimeException("Command execution failed with exit code: " + process.exitValue());
