import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class Server {
    private static final int PORT = 8080;
    private static Selector selector;
    private static Selector localSelector;
    private static Selector remoteSelector;
    private static ServerSocketChannel serverSocketChannel;

    public static void main(String[] args) throws IOException {
        TridentLogger.get().log("Creating server socket...");
        serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.socket().bind(new InetSocketAddress(PORT));
        serverSocketChannel.configureBlocking(false);

        selector = Selector.open();
        localSelector = Selector.open();
        remoteSelector = Selector.open();

        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        TridentLogger.get().log("Server started, listening on port " + PORT);

        while (true) {
            int numReady = selector.select();
            if (numReady > 0) {
                Set<SelectionKey> keys = selector.selectedKeys();
                Iterator<SelectionKey> it = keys.iterator();

                while (it.hasNext()) {
                    SelectionKey key = it.next();
                    it.remove();

                    if (key.isAcceptable()) {
                        SocketChannel clientChannel = serverSocketChannel.accept();
                        clientChannel.configureBlocking(false);

                        localSelector.register(clientChannel, SelectionKey.OP_READ);
                        remoteSelector.register(clientChannel, SelectionKey.OP_WRITE);

                        TridentLogger.get().log("New connection accepted: " + clientChannel.socket().getRemoteSocketAddress());
                    }
                }
            }
        }
    }

    public static void cleanup() throws IOException {
        if (serverSocketChannel != null) {
            serverSocketChannel.close();
        }

        if (selector != null) {
            selector.close();
        }

        if (localSelector != null) {
            localSelector.close();
        }

        if (remoteSelector != null) {
            remoteSelector.close();
        }
    }
}
