import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.security.MessageDigest;
import java.math.BigInteger;

public String getDateInterval(String dateRange) {
    if (dateRange == null || dateRange.isEmpty()) {
        throw new IllegalArgumentException("Date range cannot be empty.");
    }

    String[] dateParts = dateRange.split("/");
    if (dateParts.length != 2) {
        throw new IllegalArgumentException("Invalid date range format. Expected 'startDate/endDate'.");
    }

    LocalDate startDate = LocalDate.parse(dateParts[0], DateTimeFormatter.ISO_DATE);
    LocalDate endDate = LocalDate.parse(dateParts[1], DateTimeFormatter.ISO_DATE);

    if (startDate.isAfter(endDate)) {
        throw new IllegalArgumentException("End date must be later than or equal to start date.");
    }

    String input = String.format("%s/%s", dateParts[0], dateParts[1]);
    byte[] hash = new byte[32];

    try {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(input.getBytes());
        hash = md.digest();
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate hash.", e);
    }

    String hashHex = String.format("%064x", new BigInteger(1, new BigEndianByteArray(hash)));
    return String.format("%s/%s-%s", dateParts[0], dateParts[1], hashHex.substring(0, 8));
}
