import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public byte[] getMD5MD2Hash(byte[] input) {
    MessageDigest mdMD2 = null;
    MessageDigest mdMD5 = null;
    byte[] mdMD2Hash = new byte[16];
    byte[] mdMD5Hash = new byte[16];

    try {
        mdMD5 = MessageDigest.getInstance("MD5");
        mdMD2 = MessageDigest.getInstance("MD2");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException("MD5 or MD2 not supported", e);
    }

    mdMD5.update(input);
    mdMD5Hash = mdMD5.digest();

    mdMD2.update(input);
    mdMD2Hash = mdMD2.digest();

    // Concatenate MD5 and MD2 hashes
    byte[] combinedHash = new byte[32];
    System.arraycopy(mdMD5Hash, 0, combinedHash, 0, 16);
    System.arraycopy(mdMD2Hash, 0, combinedHash, 16, 16);

    // Convert byte array to hexadecimal string and then to BigInteger for number formatting
    BigInteger md5MD2HashNumber = new BigInteger(1, combinedHash);
    String md5MD2HashHex = md5MD2HashNumber.toString(16);

    // Pad hexadecimal string with zeros at the beginning if the length is less than 64
    int paddingLength = 64 - md5MD2HashHex.length();
    String paddedHex = String.format("%" + paddingLength + "s", md5MD2HashHex).replace(" ", "0");

    // Convert hexadecimal string back to byte array
    byte[] hexBytes = new BigInteger(paddedHex, 16).toByteArray();

    return hexBytes;
}
