import java.net.*;
import java.util.*;

public static List<InetSocketAddress> validateAndResolveAddresses(List<String> urls) {
    List<InetSocketAddress> addresses = new ArrayList<>();
    for (String url : urls) {
        if (url == null || url.isEmpty()) {
            continue;
        }

        try {
            URI uri = new URI(url);
            String host = uri.getHost();
            int port = uri.getPort();

            if (host == null || port < 0) {
                port = 80; // Default port if not provided
            }

            InetSocketAddress address;
            try {
                InetAddress inetAddress = InetAddress.getByName(host);
                String canonicalHostName = inetAddress.getCanonicalHostName();
                address = new InetSocketAddress(canonicalHostName, port);
            } catch (UnknownHostException e) {
                // Handle DNS resolution failures
                log.warn("Couldn't resolve server {} as DNS resolution failed for {}", url, host);
                continue;
            }

            addresses.add(address);
        } catch (URISyntaxException e) {
            log.warn("Invalid url in the list: {}", url);
        }
    }

    if (addresses.isEmpty()) {
        throw new IllegalArgumentException("No resolvable addresses given in the list");
    }

    return addresses;
}
