import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.ByteOrder;

public class SecureBytesToStreamInput {

    public static StreamInput bytesReferenceToStreamInput(BytesReference bytesReference) throws IOException {
        if (bytesReference == null) {
            throw new IOException("BytesReference is null");
        }

        byte[] bytes;
        if (bytesReference instanceof ByteArrayReference) {
            bytes = ((ByteArrayReference) bytesReference).getBytes();
        } else {
            bytes = ByteBuffer.allocate((int) bytesReference.size()).order(ByteOrder.LITTLE_ENDIAN).get(bytesReference.getBytes(), 0, (int) bytesReference.size()).array();
