import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public static String generateMD5Hash(String password) {
    if (password == null || password.isEmpty()) {
        throw new IllegalArgumentException("Password cannot be null or empty.");
    }

    String algorithm = "HmacMD5";
    byte[] hash;

    try {
        SecretKeySpec secretKey = new SecretKeySpec("JavaSecretKey".getBytes(), algorithm);
        Mac shaObject = Mac.getInstance(algorithm);
        shaObject.init(secretKey);
        hash = shaObject.doFinal(password.getBytes());
    } catch (Exception e) {
        throw new RuntimeException("Error generating MD5 hash.", e);
    }

    StringBuilder sb = new StringBuilder();
    for (byte b : hash) {
        sb.append(String.format("%02x", b & 0xff));
    }

    return sb.toString();
}
```

