import org.apache.mina.common.IoFilter;
import org.apache.mina.common.IoSessionConfig;
import org.apache.mina.common.address.InetSocketAddress;
import org.apache.mina.filter.executor.OrderedThreadPoolExecutor;
import org.apache.mina.filter.executor.UnorderedThreadPoolExecutor;
import org.apache.mina.filter.logger.LoggingFilter;
import org.apache.mina.filter.ssl.SslFilter;
import org.apache.mina.transport.socket.NioSocketConnector;

public class SecureSocketConnector {

    public NioSocketConnector setupSocketConnection(String uri) throws Exception {
        String host = uri.substringBefore(':');
        int port = Integer.parseInt(uri.substringAfter(':'));
        long timeout = 5000L; // default timeout
        List<IoFilter> filters = new ArrayList<>();
        int maxPoolSize = Runtime.getRuntime().availableProcessors() + 1;

        InetSocketAddress address = new InetSocketAddress(host, port);
        NioSocketConnector connector = new NioSocketConnector();

        IoSessionConfig connectorConfig = connector.getSessionConfig();
        connectorConfig.setTcpNoDelay(true);
        connectorConfig.setKeepAlive(true);
        connectorConfig.setSendBufferSize(1024);
        connectorConfig.setReceiveBufferSize(1024);

        if (configuration.isOrderedThreadPoolExecutor()) {
            workerPool = new OrderedThreadPoolExecutor(maxPoolSize);
        } else {
            workerPool = new UnorderedThreadPoolExecutor(maxPoolSize);
        }
        connector.getFilterChain().addLast("threadPool", new ExecutorFilter(workerPool));

        filters.add(new LoggingFilter());
        appendIoFiltersToChain(filters, connector.getFilterChain());

        if (configuration.getSslContextParameters() != null) {
            SslFilter sslFilter = new SslFilter(
                    configuration.getSslContextParameters().createSSLContext(getEndpoint().getCamelContext()),
                    configuration.isAutoStartTls());
            sslFilter.setUseClientMode(true);
            connector.getFilterChain().addFirst("sslFilter", sslFilter);
        }

        connector.setConnectTimeoutMillis(timeout);
        return connector;
    }

    private void appendIoFiltersToChain(List<IoFilter> filters, FilterChain filterChain) {
        for (IoFilter filter : filters) {
            filterChain.addLast(filter);
        }
    }
}
