import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class PartOfSpeechTagger {
    private HiddenMarkovModel hmm;
    private HmmDecoder decoder;

    public PartOfSpeechTagger(String modelPath) throws FileNotFoundException, IOException, ClassNotFoundException {
        FileInputStream fileIn = new FileInputStream(modelPath);
        ObjectInputStream objIn = new ObjectInputStream(fileIn);
        hmm = (HiddenMarkovModel) objIn.readObject();
        decoder = new HmmDecoder(hmm);
        objIn.close();
    }

    public Map<String, String> tagText(String text) {
        Map<String, String> taggedWords = new HashMap<>();
        String[] words = text.split("\\s+");
        for (String word : words) {
            String tag = decoder.decodeSingleWord(word);
            taggedWords.put(word, tag);
        }
        return taggedWords;
    }
}
