    public static void downloadAndReplaceDictionary(String url, String targetFile) throws IOException {
        // Validate URL is not blank
        if (url == null || url.isEmpty()) {
            throw new IllegalArgumentException("URL cannot be blank.");
        }

        // Download the dictionary from the URL
        Path tempFile = Files.createTempFile(TEMP_DIR, "dictionary_");
        try (InputStream inputStream = downloadUrl(url);
             OutputStream outputStream = new FileOutputStream(tempFile.toFile())) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }
        }

        // Check if target file exists and is a file
        Path targetPath = Paths.get(targetFile);
        if (Files.exists(targetPath) && Files.isRegularFile(targetPath)) {
            // Calculate MD5 hash of both files to ensure they are identical before replacement
            MessageDigest md = MessageDigest.getInstance("MD5");
            try (InputStream tempInputStream = new FileInputStream(tempFile.toFile());
                 InputStream targetInputStream = new FileInputStream(targetPath.toFile())) {
                byte[] tempBytes = new byte[4096];
                byte[] targetBytes = new byte[4096];
                int tempBytesRead, targetBytesRead;
                boolean filesMatch = true;
                while ((tempBytesRead = tempInputStream.read(tempBytes)) > 0 &&
                       (targetBytesRead = targetInputStream.read(targetBytes)) > 0) {
                    if (Arrays.equals(tempBytes, 0, tempBytesRead, targetBytes, 0, targetBytesRead)) {
                        continue;
                    }
                    filesMatch = false;
                    break;
                }
                if (filesMatch) {
                    // Replace the existing file with the downloaded one
                    Files.delete(targetPath);
                    Files.copy(tempFile, targetPath);
                }
            }
            tempFile.toFile().delete();
        } else {
            throw new FileNotFoundException("Target file does not exist or is not a regular file.");
        }
    }

    private static InputStream downloadUrl(String urlString) throws IOException {
