import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public void generateMD5Hash(String filePath) {
    File inputFile = new File(filePath);
    if (!inputFile.exists() || !inputFile.isFile()) {
        System.err.println("Invalid file path: " + filePath);
        return;
    }

    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] fileData = FileUtils.readFileToByteArray(inputFile);
        byte[] hash = md.digest(fileData);

        String hashHex = bytesToHex(hash);
        String outputFileName = inputFile.getName() + ".md5";
        File outputFile = new File(outputFileName);

        FileOutputStream fos = new FileOutputStream(outputFile);
        fos.write(hashHex.getBytes());
        fos.close();

        System.out.println("Generated MD5 hash for file: " + inputFile.getName());
    } catch (NoSuchAlgorithmException | IOException e) {
        System.err.println("Error generating MD5 hash: " + e.getMessage());
    }
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder();
    for (byte b : bytes) {
        result.append(String.format("%02x", b));
    }
    return result.toString();
}
