import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;

public class CommandExecutor {
    private static final int MAX_BUFFER_SIZE = 1024;

    public int executeCommandAndReadError(String command) {
        Process process;
        try {
            process = Runtime.getRuntime().exec(command);
        } catch (IOException e) {
            return -1;
        }

        InputStream errorStream = process.getErrorStream();
        ByteArrayOutputStream errorOutput = new ByteArrayOutputStream();

        int bytesRead;
        byte[] buffer = new byte[MAX_BUFFER_SIZE];

        try {
            while ((bytesRead = errorStream.read(buffer)) != -1) {
                errorOutput.write(buffer, 0, bytesRead);
            }
            errorOutput.flush();
        } catch (IOException e) {
            // Handle exceptions appropriately
            return -1;
        } finally {
            try {
                errorStream.close();
            } catch (IOException e) {
                // Handle exceptions appropriately
            }
        }

        byte[] errorBytes = errorOutput.toByteArray();
        int errorLength = errorBytes.length;

        // Validate the return code of the command execution
        int exitValue = process.exitValue();
        if (exitValue != 0) {
            // Handle non-zero exit values appropriately
            return -1;
        }

        return errorLength;
    }
}
