import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

public class SerializationExample implements Serializable {

    private static final long serialVersionUID = 1L;
    private String name;
    private transient int age; // Marking the age field as transient to avoid serialization

    public SerializationExample(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public static byte[] serialize(Object obj) throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        ObjectOutputStream out = new ObjectOutputStream(byteStream);
        out.writeObject(obj);
        return byteStream.toByteArray();
    }

    public static <T extends Serializable> T deserialize(byte[] bytes, Class<T> clazz) throws IOException, ClassNotFoundException {
        ByteArrayInputStream byteStream = new ByteArrayInputStream(bytes);
        ObjectInputStream in = new ObjectInputStream(byteStream);
        return (T) in.readObject();
    }

    public static void main(String[] args) throws IOException, ClassNotFoundException {
        SerializationExample original = new SerializationExample("Original", 42);
        byte[] serializedBytes = serialize(original);
        SerializationExample deserialized = deserialize(serializedBytes, SerializationExample.class);

        System.out.println("Original: name=" + original.getName() + ", age=" + original.getAge());
        System.out.println("Deserialized: name=" + deserialized.getName() + ", age=" + deserialized.getAge());

