import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class SafeProcessExecutor {

    public static boolean executeSafeProcess(String executablePath, List<String> arguments, String workingDirectory) {
        boolean success = false;
        Process process = null;
        try {
            process = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", constructCommand(executablePath, arguments, workingDirectory)});
            success = process.waitFor(30, TimeUnit.SECONDS); // Wait for 30 seconds
            if (success) {
                printExecutionDetails(process);
            } else {
                printErrorDetails(process);
            }
        } catch (IOException | InterruptedException e) {
            printErrorDetails(process);
            e.printStackTrace();
        } finally {
            process.destroy();
        }
        return success;
    }

    private static String constructCommand(String executablePath, List<String> arguments, String workingDirectory) {
        StringBuilder commandBuilder = new StringBuilder("#!/bin/sh\n");
        commandBuilder.append("cd ").append(workingDirectory).append("\n");
        commandBuilder.append(executablePath).append(" ");
        for (String arg : arguments) {
            commandBuilder.append("'").append(arg).append("' ");
        }
        return commandBuilder.toString();
    }

    private static void printExecutionDetails(Process process) {
        try (BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = input.readLine()) != null) {
                System.out.println("Output: " + line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        try (PrintWriter errorWriter = new PrintWriter(System.err)) {
            errorWriter.println("Error: " + process.errorStream);
        }

        System.out.println("Process exited with code: " + process.exitValue());
    }

    private static void printErrorDetails(Process process) {
        if (process != null) {
            process.destroy();
        }
        System.err.println("Error: Failed to execute process.");
    }
}
