public class SerializationBenchmark {
    private static final int NUM_SERIALIZATIONS = 500;

    public static void main(String[] args) throws IOException, ClassNotFoundException {
        SerializableObject serializableObject = new SerializableObject(UUID.randomUUID().toString());

        Instant start = Instant.now();
        long totalSize = 0;

        for (int i = 0; i < NUM_SERIALIZATIONS; i++) {
