import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Map;

public static Map<String, String> getWalkMap(String filePath) {
    File file = new File(filePath);
    if (!file.exists()) {
        return Map.of();
    }

    String fileName = file.getName();
    Path filePathObj = Paths.get(filePath);

    if (!Files.isRegularFile(filePathObj)) {
        return Map.of();
    }

    String fileExtension = fileName.substring(fileName.lastIndexOf(".") + 1);

    if (".objv".equalsIgnoreCase(fileExtension)) {
        try {
            ViewMap viewMap = new ViewMap();
            Files.lines(filePathObj)
                    .map(line -> line.split(","))
                    .forEach(parts -> viewMap.put(parts[0], parts[1]));
            return viewMap;
        } catch (IOException e) {
            return Map.of();
        }
    } else if (".objp".equalsIgnoreCase(fileExtension)) {
        try {
            PathsMap pathsMap = new PathsMap();
            Files.walk(filePathObj)
                    .filter(Files::isRegularFile)
                    .map(path -> path.getFileName().toString())
                    .forEach(pathsMap::put);
            return pathsMap;
        } catch (IOException e) {
            return Map.of();
        }
    } else if (".jrd3m".equalsIgnoreCase(fileExtension)) {
        try {
            ObjectInputStream objectInputStream = new ObjectInputStream(new FileInputStream(file));
            Object object = objectInputStream.readObject();
            if (object instanceof WalkMap) {
                return (Map<String, Object>) object;
            } else {
                objectInputStream.close();
                return Map.of();
            }
        } catch (IOException | ClassNotFoundException e) {
            return Map.of();
        }
    }

    return Map.of();
}
```

