public class DataExtractor {

    public static void main(String[] args) {
        List<String> files = new ArrayList<>();
        files.add("file1.xml");
        files.add("file2.txt");
        files.add("file3.db");

        for (String file : files) {
            try {
                if (file.endsWith(".xml")) {
                    extractXmlData(file);
                } else if (file.endsWith(".txt")) {
                    extractTxtData(file);
                } else if (file.endsWith(".db")) {
                    extractDbData(file);
                }
            } catch (Exception e) {
                System.err.println("Error processing file: " + file + ". Error message: " + e.getMessage());
            }
        }
    }

    private static void extractXmlData(String filePath) throws IOException, ParserConfigurationException, SAXException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parsenew File(filePath));

        extractDataFromXml(document);
    }

    private static void extractDataFromXml(Document document) {
        NodeList nodeList = document.getDocumentElement().getChildNodes();

        for (int i = 0; i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);

            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                System.out.println(element.getTagName() + ": " + element.getTextContent());
            }
        }
    }

    private static void extractTxtData(String filePath) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(filePath), StandardCharsets.UTF_8);
        String line;

        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }

        reader.close();
    }

    private static void extractDbData(String filePath) throws ClassNotFoundException, SQLException {
        String url = "jdbc:mysql://localhost:3306/mydatabase";
        String user = "username";
        String password = "password";

        Connection connection = DriverManager.getConnection(url, user, password);
        PreparedStatement statement = connection.prepareStatement("SELECT * FROM mytable");
        ResultSet resultSet = statement.executeQuery();

        while (resultSet.next()) {
            int id = resultSet.getInt("id");
            String name = resultSet.getString("name");
            System.out.println("ID: " + id + ", Name: " + name);
        }

        resultSet.close();
        statement.close();
        connection.close();
    }
}
