public class SecureHttpsConnection {

    private static final String JSON_CONTENT_TYPE = "application/json";

    public static HttpURLConnection establishSecureConnection(String hostname, int port, String jsonPayload) throws IOException, GeneralSecurityException {
        try {
            TrustManager[] trustAllCerts = new TrustManager[] {
                    new X509TrustManager() {
                        public X509Certificate[] getAcceptedIssuers() {
                            return new X509Certificate[0];
                        }

                        public void checkClientTrusted(X509Certificate[] certs, String authType) {
                        }

                        public void checkServerTrusted(X509Certificate[] certs, String authType) {
                        }
                    }
            };

            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, new SecureRandom());
            HttpsURLConnection connection = (HttpsURLConnection) new URL("https", hostname, port).openConnection();
            connection.setSSLSocketFactory(sslContext.getSocketFactory());

            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", JSON_CONTENT_TYPE);

            OutputStream outputStream = connection.getOutputStream();
            ByteArrayOutputStream jsonOutputStream = new ByteArrayOutputStream();
            try {
                ObjectMapper mapper = new ObjectMapper();
                mapper.writeValue(jsonOutputStream, parseJson(jsonPayload));
                jsonOutputStream.writeTo(outputStream);
                outputStream.flush();
            } finally {
                outputStream.close();
                jsonOutputStream.close();
            }

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                throw new IOException("Received HTTP error code: " + responseCode);
            }

            return connection;
        } catch (NoSuchAlgorithmException | KeyManagementException e) {
            throw new GeneralSecurityException("Error establishing secure connection", e);
        }
    }

    private static Map<String, Object> parseJson(String jsonString) {
        try {
            return new ObjectMapper().readValue(jsonString, Map.class);
        } catch (IOException e) {
