import org.xml.sax.Attributes;
import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class SAXParserWithPrefixes {

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Please provide XML file paths as command-line arguments.");
            return;
        }

        FrequencyHandler frequencyHandler = new FrequencyHandler();

        try {
            SAXParserFactory parserFactory = SAXParserFactory.newInstance();
            parserFactory.setFeature("http://xml.org/sax/features/namespace-prefixes", true);
            SAXParser saxParser = parserFactory.newSAXParser();

            for (String filePath : args) {
                File file = new File(filePath);
                if (!file.exists()) {
                    System.out.println("File not found: " + filePath);
                    continue;
                }

                saxParser.parse(file, frequencyHandler);
            }

            frequencyHandler.printPrefixesAndFrequencies();

        } catch (SAXException | IOException e) {
            e.printStackTrace();
        }
    }

    static class FrequencyHandler extends DefaultHandler {
        private Map<String, Integer> prefixFrequencies = new HashMap<>();
