import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.Serializable;

public class SingletonInstance implements Serializable {
    private static volatile SingletonInstance instance;
    private static final String SERIALIZED_FILE = "singleton.ser";

    private SingletonInstance() {}

    public static SingletonInstance getInstance() {
        if (instance == null) {
            synchronized (SingletonInstance.class) {
                if (instance == null) {
                    try {
                        FileInputStream fileInput = new FileInputStream(SERIALIZED_FILE);
                        ObjectInputStream objectInput = new ObjectInputStream(fileInput);
                        instance = (SingletonInstance) objectInput.readObject();
                        objectInput.close();
                        fileInput.close();
                    } catch (FileNotFoundException e) {
                        Logger.log("Singleton file not found, creating new instance.");
                        instance = new SingletonInstance();
                    } catch (IOException | ClassNotFoundException e) {
                        Logger.log("Error loading singleton instance, creating new instance.", e);
                        instance = new SingletonInstance();
                    }

                    try {
                        FileOutputStream fileOutput = new FileOutputStream(SERIALIZED_FILE);
                        ObjectOutputStream objectOutput = new ObjectOutputStream(fileOutput);
                        objectOutput.writeObject(instance);
                        objectOutput.close();
                        fileOutput.close();
                    } catch (IOException e) {
                        Logger.log("Error saving singleton instance.", e);
                    }
                }
            }
        }

        return instance;
    }
}
