import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;

public class UserInputSender {

    private static final String SERVER_URL = "http://example.com/api/userInput";

    public static void sendUserInput(HttpURLConnection client) throws IOException {
        Map<String, String> userInputMap = new HashMap<>();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        System.out.println("Enter key-value pairs (type 'done' when finished):");
        String line;
        while (!(line = reader.readLine()).equalsIgnoreCase("done")) {
            String[] parts = line.split(":");
            if (parts.length != 2) {
                throw new IllegalArgumentException("Invalid input format: " + line);
            }
            userInputMap.put(parts[0], parts[1]);
        }

        String json = mapToJson(userInputMap);
        sendRequest(client, json);
        System.out.println("User input sent to server.");
    }

    private static String mapToJson(Map<String, String> map) {
        StringBuilder jsonBuilder = new StringBuilder("{");
        for (Map.Entry<String, String> entry : map.entrySet()) {
            jsonBuilder.append(", \"");
            jsonBuilder.append(entry.getKey());
            jsonBuilder.append("\": \"");
            jsonBuilder.append(entry.getValue());
            jsonBuilder.append("\"");
        }
        jsonBuilder.setCharAt(0, '{');
        jsonBuilder.setCharAt(jsonBuilder.length(), '}');
        return jsonBuilder.toString();
    }

    private static void sendRequest(HttpURLConnection connection, String requestBody) throws IOException {
