import java.io.*;
import java.util.Arrays;

public class KeyboardEventSimulator {

    private static final String COMMAND = "xdotool key %s";

    public static void simulateKeyboardEvents(int[] keys) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder("bash", "-c");
        pb.redirectErrorStream(true);

        for (int key : keys) {
            String command = String.format(COMMAND, String.valueOf(key));
            Process process = pb.command(Arrays.asList(command.split(" "))).start();

            try {
                process.waitFor();
            } catch (InterruptedException e) {
                // Handle interruption and continue with the next key event
                Thread.currentThread().interrupt();
            }
        }

        if (!process.exitValue() == 0) {
            throw new RuntimeException("Failed to simulate keyboard events");
        }
    }

    public static void main(String[] args) {
        try {
            int[] keys = {32, 48, 49, 50}; // Space, 0, 1, 2
            simulateKeyboardEvents(keys);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
