import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public void executeBashCommand(String command) {
    if (command == null || command.isEmpty()) {
        logger.warn("Empty or null command provided.");
        return;
    }

    Process process;
    try {
        process = Runtime.getRuntime().exec("bash -c \"" + command + "\"");
    } catch (IOException e) {
        logger.warn("An exception occurred while executing the command '{}' : '{}'", command, e.getMessage());
        return;
    }

    StringBuilder outputBuilder = new StringBuilder();

    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
        String line;
        while ((line = reader.readLine()) != null) {
            outputBuilder.append(line).append("\n");
        }
    } catch (IOException e) {
        logger.warn("An exception occurred while reading the output of the command '{}' : '{}'", command, e.getMessage());
    }

    try {
        process.waitFor();
    } catch (InterruptedException e) {
        logger.warn("An exception occurred while waiting for the command '{}' to finish : '{}'", command, e.getMessage());
    }

    if (process.exitValue() != 0) {
        logger.warn("The command '{}' returned an error code '{}'", command, process.exitValue());
    } else {
        System.out.println("Output of command '{}' :\n{}", command, outputBuilder.toString());
    }
}
