import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.lang.reflect.InvocationTargetException;
import java.net.URL;
import java.nio.file.Files;
import java.security.AccessController;
import java.security.PrivilegedExceptionAction;

public class SecureCompiler {

    private static final String JAVAC_EXEC = "javac";

    public static void compileStringToFile(String inputCode, String outputFile) {
        if (inputCode == null || outputFile == null) {
            throw new IllegalArgumentException("Both inputCode and outputFile must be non-null.");
        }

        String tempFileName = null;
        try {
            tempFileName = createSecureTempFile(".java");
            File tempFile = new File(tempFileName);
            PrintWriter writer = new PrintWriter(new FileOutputStream(tempFile));
            writer.print(inputCode);
            writer.close();

            compileJavaFile(tempFile.getAbsolutePath(), outputFile);
            Files.deleteIfExists(new File(tempFileName).toPath());
        } catch (IOException e) {
            throw new RuntimeException("Failed to create temporary file.", e);
        }
    }

    private static File createSecureTempFile(String suffix) {
        return AccessController.doPrivileged((PrivilegedExceptionAction<File>) () -> {
            File tempFile = File.createTempFile("javac", suffix);
            tempFile.deleteOnExit();
            return tempFile;
        });
    }

    private static void compileJavaFile(String javaFile, String outputFile) {
        String[] command = new String[]{"java", "-cp", getClassPath(), JAVAC_EXEC, javaFile, "-d", new File(outputFile).getParent()};

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true);

        try {
            Process process = processBuilder.start();
            int exitValue = process.waitFor().exitValue();

            if (exitValue != 0) {
                throw new RuntimeException("Java compilation failed with exit code: " + exitValue);
            }
        } catch (InterruptedException | IOException e) {
            throw new RuntimeException("Failed to compile Java file.", e);
        }
    }

    private static String getClassPath() {
        return String.join(File.pathSeparator, getClass().getProtectionDomain().getCodeSource().getLocation().getPath(), ".");
    }
}
