public String executeCommand(String command, Map<String, String> environmentVariables) {
    ProcessBuilder pb = new ProcessBuilder(command.split(" "));
    pb.inheritIO(); // Inherit input and error streams from parent process

    if (environmentVariables != null) {
        pb.environment().putAll(environmentVariables);
    }

    try {
        Process process = pb.start();
        int exitValue = process.waitFor();

        if (exitValue != 0) {
            throw new RuntimeException("Command execution failed with exit code: " + exitValue);
        }

        InputStream inputStream = process.getInputStream();
        byte[] buffer = new byte[1024];
        int bytesRead;
        StringBuilder output = new StringBuilder();

        do {
            bytesRead = inputStream.read(buffer, 0, buffer.length);
            if (bytesRead > 0) {
                output.append(new String(buffer, 0, bytesRead));
            }
        } while (bytesRead >= 0);

        return output.toString();
    } catch (IOException | InterruptedException e) {
        throw new RuntimeException("Error executing command: " + command, e);
    }
}
