import java.io.File;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

public static boolean uploadFile(String serverUrl, String fileName, File fileToUpload) {
    int maxRetries = 3;
    for (int attempt = 1; attempt <= maxRetries; attempt++) {
        try {
            URL url = new URL(serverUrl + "/upload");
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", getContentType(fileToUpload.getName()));
            connection.setDoOutput(true);

            FileInputStream inputStream = new FileInputStream(fileToUpload);
            byte[] buffer = new byte[1024];
            int bytesRead;
            long totalBytesSent = 0;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                connection.getOutputStream().write(buffer, 0, bytesRead);
                totalBytesSent += bytesRead;
            }
            inputStream.close();

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                System.out.println("File uploaded successfully. Response code: " + responseCode);
                return true;
            } else {
                System.out.println("File upload failed. Response code: " + responseCode);
            }

            connection.disconnect();

            if (attempt < maxRetries) {
                Thread.sleep(5000); // Wait for 5 seconds before retrying
            }
        } catch (IOException e) {
            if (attempt < maxRetries) {
                System.out.println("File upload failed. Retrying in 5 seconds...");
                try {
                    Thread.sleep(5000);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            } else {
                System.out.println("File upload failed after " + maxRetries + " attempts.");
                e.printStackTrace();
            }
        }
    }

