import org.apache.http.HttpHost;
import org.apache.http.auth.AuthScope;
import org.apache.http.client.CredentialsProvider;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.client.protocol.HttpClientContext;
import org.apache.http.conn.ssl.SSLConnectionSocketFactory;
import org.apache.http.conn.ssl.TrustSelfSignedStrategy;
import org.apache.http.impl.client.BasicCredentialsProvider;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.impl.conn.PoolingHttpClientConnectionManager;
import org.apache.http.util.EntityUtils;

public class SecureHttpClientExample {

    public static void main(String[] args) throws Exception {
        String url = "https://example.com/api/resource";
        String proxyHost = "proxy.example.com";
        int proxyPort = 8080;
        String username = "proxy_user";
        String password = "proxy_password";

        // Create a credentials provider
        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        credentialsProvider.setCredentials(new AuthScope(proxyHost, proxyPort), new org.apache.commons.codec.net.UsernamePasswordCredentials(username, password));

        // Create a SSLConnectionSocketFactory
        SSLConnectionSocketFactory sslSocketFactory = new SSLConnectionSocketFactory(new TrustSelfSignedStrategy());

        // Create a PlainConnectionSocketFactory
        ConnectionSocketFactory plainSocketFactory = PlainConnectionSocketFactory.getSocketFactory();

        // Create a Registry
        Registry registry = RegistryBuilder.create().register("http", plainSocketFactory).register("https", sslSocketFactory).build();

        // Create a RegistryBuilder
        RegistryBuilder<ConnectionSocketFactory> registryBuilder = RegistryBuilder.create();

        // Register SSLConnectionSocketFactory and PlainConnectionSocketFactory
        registryBuilder.register("http", plainSocketFactory);
        registryBuilder.register("https", sslSocketFactory);

        // Create a ConnectionManager
        PoolingHttpClientConnectionManager connectionManager = new PoolingHttpClientConnectionManager(registry);

        // Create a CloseableHttpClient
        CloseableHttpClient httpClient = HttpClients.custom()
                .setConnectionManager(connectionManager)
                .setDefaultCredentialsProvider(credentialsProvider)
                .build();

        try {
            // Create a HttpGet request
            HttpGet httpGet = new HttpGet(url);

            // Set the request config
            RequestConfig requestConfig = RequestConfig.custom()
                    .setProxy(new HttpHost(proxyHost, proxyPort))
                    .build();

            // Set the request config for the request
            httpGet.setConfig(requestConfig);

            // Execute the request and retrieve the response entity
            CloseableHttpResponse response = httpClient.execute(httpGet, HttpClientContext.create());

            // Convert the response entity to a string
            String responseString = EntityUtils.toString(response.getEntity());

            // Print the response string
            System.out.println(responseString);

        } finally {
            // Close the resources
            httpClient.close();
        }
    }
}
