                System.err.println("Error executing command: " + error);
            }
            inputStream.close();
        }

        InputStream inputStream = process.getInputStream();
        byte[] outputBytes = new byte[1024];
        int bytesRead = 0;
        String output = "";
        while ((bytesRead = inputStream.read(outputBytes)) != -1) {
            output += new String(outputBytes, 0, bytesRead);
        }
        inputStream.close();

        process.waitFor();

        if (process.exitValue() != 0) {
            throw new RuntimeException("Command execution failed with exit code: " + process.exitValue());
        }

        System.out.println("Command output: " + output);
        return process;
    } catch (IOException | InterruptedException e) {
        throw new RuntimeException("Error executing command: " + e.getMessage(), e);
    }
}

public static String escapeCommand(String command) {
    if (command == null || command.isEmpty()) {
        throw new IllegalArgumentException("Command cannot be null or empty.");
    }

    String osName = System.getProperty("os.name").toLowerCase();
    boolean isWindows = osName.startsWith("windows");

    StringBuilder escapedCommand = new StringBuilder();
    for (int i = 0; i < command.length(); i++) {
