import com.example.GraphDatabase; // Assuming GraphDatabase is the graph database interface
import java.util.List;
import java.util.Optional;

public class EdgeCreator {

    private final GraphDatabase db;
    private final Cache cache;

    public EdgeCreator(GraphDatabase db, Cache cache) {
        this.db = db;
        this.cache = cache;
    }

    public void createEdges(List<VertexBuilder> vertexBuilders) {
        for (int i = 0; i < vertexBuilders.size(); i++) {
            VertexBuilder v1 = vertexBuilders.get(i);
            for (int j = i + 1; j < vertexBuilders.size(); j++) {
                VertexBuilder v2 = vertexBuilders.get(j);
                Optional<Edge> existingEdge = findEdge(v1.getId(), v2.getId());
                if (existingEdge.isEmpty()) {
                    createAndHashEdge(v1.getId(), v2.getId());
                }
            }
        }
    }

    private Optional<Edge> findEdge(int id1, int id2) {
        return db.findEdgeByVertices(id1, id2);
    }

    private void createAndHashEdge(int id1, int id2) {
        Edge edge = new Edge(id1, id2);
        db.createEdge(edge);
        cache.put(edge.hashCode(), edge);
    }
}

class Edge {
    final int id1;
    final int id2;

    Edge(int id1, int id2) {
        this.id1 = id1;
        this.id2 = id2;
    }
}

interface GraphDatabase {
    Optional<Edge> findEdgeByVertices(int id1, int id2);
    void createEdge(Edge edge);
}

class Cache {
    private final ConcurrentHashMap<Integer, Edge> cache = new ConcurrentHashMap<>();

    public void put(int hashCode, Edge edge) {
        cache.put(hashCode, edge);
    }
}
