import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class SecureHashFunction {

    private static final Map<String, MessageDigest> ALGORITHMS = new HashMap<>();

    static {
        try {
            ALGORITHMS.put("MD5", MessageDigest.getInstance("MD5"));
            ALGORITHMS.put("SHA-1", MessageDigest.getInstance("SHA-1"));
            ALGORITHMS.put("SHA-256", MessageDigest.getInstance("SHA-256"));
            ALGORITHMS.put("SHA-384", MessageDigest.getInstance("SHA-384"));
            ALGORITHMS.put("SHA-512", MessageDigest.getInstance("SHA-512"));
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unexpected error initializing hashing algorithms", e);
        }
    }

    public String hash(String input, String algorithm) {
        MessageDigest md;
        try {
            md = ALGORITHMS.get(algorithm);
        } catch (NullPointerException e) {
            throw new IllegalArgumentException("Invalid algorithm: " + algorithm);
        }

        byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexString = new StringBuilder(2 * hashBytes.length);

        for (byte b : hashBytes) {
            hexString.append(String.format("%02x", b));
        }

        return hexString.toString();
    }
}
