import org.apache.commons.codec.digest.DigestUtils;
import org.apache.commons.lang3.StringUtils;

import java.util.List;
import java.util.Optional;

public static String createServerGroup(List<String> inputStrings, List<String> existingServerGroups) {
    String concatenatedStrings = StringUtils.join(inputStrings, "");
    String md5Hash = DigestUtils.md5Hex(concatenatedStrings);
    Optional<String> existingGroup = existingServerGroups.stream().filter(s -> s.equals(md5Hash)).findFirst();

    if (existingGroup.isPresent()) {
        return "Server group with the given MD5 hash already exists.";
    }

    String newServerGroup = "Server group with MD5 hash: " + md5Hash;
    existingServerGroups.add(newServerGroup);

    return newServerGroup;
}
