```java
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public static String generateRandomString(double seed) {
    String keyStr = String.valueOf(seed);
    byte[] keyBytes = keyStr.getBytes();
    SecretKeySpec secretKey = new SecretKeySpec(keyBytes, "HmacSHA256");

    try {
        Mac sha256Hmac = Mac.getInstance("HmacSHA256");
        sha256Hmac.init(secretKey);
        byte[] hash = sha256Hmac.doFinal();

        String hexHash = bytesToHex(hash);
        return hexHash.substring(0, 64); // Keep only the first 32 digits for a 256-bit hash
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error generating hash", e);
    }
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder();
    for (byte b : bytes) {
        result.append(String.format("%02x", b));
    }
    return result.toString();
}
```

This code uses the HmacSHA256 algorithm to generate a hash from the seed value and returns the first 32 digits of the resulting hexadecimal string. It validates the algorithm and key before generating the hash, and handles any exceptions that may occur during the process. The `bytesToHex` helper method converts a byte array to a hexadecimal string.

