import javax.crypto.Mac;
import javax.crypto.spec.OAWMACKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.spec.KeySpec;
import java.util.Arrays;

public byte[] generateMask(int maskLength, byte[] seed) {
    try {
        Mac mac = Mac.getInstance("HmacSHA256"); // Use SHA-256 as a secure digest algorithm
        KeySpec keySpec = new OAWMACKeySpec(Arrays.copyOfRange(seed, 0, 32), "HmacSHA256");
        mac.init(keySpec);

        byte[] mask = new byte[maskLength];
        byte[] output = new byte[64]; // MGF1 output size for SHA-256
        int length = 0;

        while (length < maskLength) {
            mac.update(seed);
            mac.update((byte) 0x35); // MGF1 label
            mac.doFinal(output, 0, output.length);
            System.arraycopy(output, 0, mask, length, Math.min(output.length, maskLength - length));
            length += Math.min(output.length, maskLength - length);
        }

        return mask;
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error generating mask", e);
    }
}
