import org.apache.commons.codec.digest.SHA1;

public static String hashStringWithNamespace(String input, String namespace) {
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be empty or null.");
    }

    if (namespace == null) {
        throw new IllegalArgumentException("Namespace parameter cannot be null.");
    }

    SHA1 sha1 = new SHA1();
    byte[] inputBytes = input.getBytes();
    byte[] namespaceBytes = namespace.getBytes();

    byte[] hashInput = new byte[inputBytes.length + namespaceBytes.length];
    System.arraycopy(inputBytes, 0, hashInput, 0, inputBytes.length);
