function writeResultsToFile(command) {
  const { resultsTo, results } = command;

  if (!resultsTo || !results || !Array.isArray(results)) {
    throw new Error('Invalid command object');
  }

  function writeLine(file, line) {
    return new Promise((resolve, reject) => {
      const fileHandler = file.open('w');
      if (!fileHandler || fileHandler.error) {
        reject(new Error(`Failed to open file for writing: ${file.error}`));
      }

      fileHandler.writeText(line, 0, line.length, 'end', (err) => {
        if (err) {
          reject(new Error(`Failed to write line to file: ${err}`));
        } else {
          resolve();
        }
        fileHandler.close();
      });
    });
  }

  return Promise.all(results.map((result, index) => {
    const errorMessage = result.error ? `****ERROR ${result.error}` : result.result;
    return writeLine(resultsTo, errorMessage + '\n');
  })).then(() => {
    console.log('Results written to file successfully');
  }).catch((error) => {
    console.error('Error writing results to file:', error);
  });
}
