```javascript
const fs = require('fs');
const path = require('path');

function checkDirectoryExists(pathToCheck) {
  return new Promise((resolve, reject) => {
    fs.stat(pathToCheck, (err, stats) => {
      if (err) {
        if (err.code === 'ENOENT') {
          reject(new Error(`Directory ${pathToCheck} does not exist`));
        } else {
          reject(err);
        }
      } else {
        if (stats.isDirectory()) {
          resolve(pathToCheck);
        } else {
          reject(new Error(`${pathToCheck} is not a directory`));
        }
      }
    });
  });
}

async function checkFilesAndDirectoriesExist() {
  const cwd = process.cwd();
  const requiredFilesAndDirectories = ['file1.txt', 'dir1', 'file2.txt'];
  let currentPath = cwd;

  for (const requiredFileOrDirectory of requiredFilesAndDirectories) {
    const resolvedPath = path.resolve(currentPath, requiredFileOrDirectory);

    try {
      const stat = await checkDirectoryExists(resolvedPath);
      if (requiredFileOrDirectory.endsWith('/')) {
        // If it's a directory, recursively check its contents
        const directoryContents = await fs.promises.readdir(stat);
        for (const item of directoryContents) {
          const itemPath = path.join(stat, item);
          await checkFilesAndDirectoriesExist(itemPath);
        }
      } else {
        // If it's a file, check its existence
        const fileStat = await fs.promises.stat(resolvedPath);
        if (!fileStat.isFile()) {
          throw new Error(`File ${requiredFileOrDirectory} does not exist`);
        }
      }
    } catch (error) {
      console.error('Error checking file or directory:', error.message);
      return false;
    }

    currentPath = currentPath; // Reset currentPath for the next iteration
  }

  return true;
}

checkFilesAndDirectoriesExist().then((result) => {
  if (result) {
    console.log('All required files and directories exist');
  } else {
    console.log('Some required files or directories do not exist');
  }
}).catch((error) => {
  console.error('An error occurred:', error.message);
});
```

