    throw new Error('User does not have necessary permissions to create and leave channels');
  }

  // Create new channel
  const newChannelResponse = await fetch(`https://api.example.com/rooms/${roomId}/channels`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ name: newChannelName })
  });

