const fs = require('fs-extra');
const less = require('less');
const path = require('path');

async function compileLessFiles(dirPath) {
  try {
    const files = await fs.readdir(dirPath);

    const compiledFiles = {};

    for (const file of files) {
      const filePath = path.join(dirPath, file);
      const stat = await fs.lstat(filePath);

      if (stat.isDirectory()) continue;

      if (path.extname(filePath) === '.less') {
        const outputPath = path.join(
          dirPath,
          path.basename(file, '.less') + '.css'
        );

        await new Promise((resolve, reject) => {
          less.renderFile(filePath, (err, result) => {
            if (err) return reject(err);
            resolve();
          });
        });

        await fs.writeFile(outputPath, result.css.toString());

        compiledFiles[outputPath] = filePath;
      }

      await compileLessFiles(filePath);
    }

    return compiledFiles;
  } catch (error) {
    console.error('Error compiling Less files:', error);
    throw error;
  }
}
```

