function findAlertsWithJumpTarget(fileContent, duration, searchString) {
  if (duration <= 0 || !searchString) {
    return { count: 0, jumpTarget: null };
  }

  const lines = fileContent.split('\n');
  let count = 0;
  let jumpTarget = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.startsWith('alert:') && line.includes(searchString)) {
      count++;
      jumpTarget = i;
      const nextLineIndex = i + 1;
      if (nextLineIndex < lines.length && lines[nextLineIndex].startsWith('}')) {
        break;
      }
    }
  }

  if (count > 0) {
    return { count, jumpTarget };
  } else {
    return { count: 0, jumpTarget: null };
  }
}
