const lodash = require('lodash');
const sass = require('sass');
const typescript = require('typescript');

// Function to validate filename for unsafe characters
function isSafeFilename(filename) {
  const invalidChars = /[\\/:*?<>|"']/g;
  return !invalidChars.test(filename);
}

// Function to delete a file safely
async function deleteFile(filePath) {
  try {
    await fs.remove(filePath);
    console.log(`Deleted file: ${filePath}`);
  } catch (err) {
    console.error(`Error deleting file: ${filePath}`, err);
  }
}

// Function to insert text into a file
async function insertTextIntoFile(filePath, text, position) {
  try {
    const content = await fs.readFile(filePath, 'utf8');
    const newContent = lodash.insert(content, position, text);
    await fs.writeFile(filePath, newContent, 'utf8');
    console.log(`Inserted text into file: ${filePath}`);
  } catch (err) {
    console.error(`Error inserting text into file: ${filePath}`, err);
  }
}

// Function to compile Sass to CSS
function compileSass(filePath, outputPath) {
  const options = { data: fs.readFileSync(filePath, 'utf8') };
  sass.render(options, (err, result) => {
    if (err) {
      console.error(`Error compiling Sass: ${filePath}`, err);
      return;
    }
    fs.writeFileSync(outputPath, result.css.toString());
    console.log(`Compiled Sass to CSS: ${filePath} -> ${outputPath}`);
  });
}

// Function to compile TypeScript to JavaScript
function compileTypeScript(filePath, outputPath) {
  const compiler = typescript.createCompiler();
  compiler.addInputFile(filePath);
  compiler.compile((err, outputFiles) => {
    if (err) {
      console.error(`Error compiling TypeScript: ${filePath}`, err);
      return;
    }
    const jsOutputPath = outputFiles.find((file) => file.extensions[0] === '.js').path;
    fs.copyFileSync(jsOutputPath, outputPath);
    console.log(`Compiled TypeScript to JavaScript: ${filePath} -> ${outputPath}`);
  });
}

// Function to concatenate files
async function concatenateFiles(inputFiles, outputPath) {
  try {
    const content = lodash.concat(...inputFiles.map((file) => fs.readFileSync(file, 'utf8')));
    await fs.writeFile(outputPath, content, 'utf8');
    console.log(`Concatenated files: ${inputFiles.join(', ')} -> ${outputPath}`);
  } catch (err) {
    console.error(`Error concatenating files: ${outputPath}`, err);
  }
}

