const fs = require('fs-extra');
const path = require('path');

function isSubpath(subpath, root) {
  return path.parse(subpath).dir.toString() === root;
}

function findPackagesRecursively(dirPath, packages = []) {
  const files = syncReadDir(dirPath);

  for (const file of files) {
    const filePath = path.join(dirPath, file);
    const stat = fs.lstatSync(filePath);

    if (stat.isDirectory()) {
      packages = packages.concat(findPackagesRecursively(filePath));
    } else if (isSubpath(filePath, dirPath)) {
      packages.push(path.basename(filePath));
    }
  }

  return packages;
}

function syncReadDir(dir) {
  return fs.readdirSync(dir).map(file => path.join(dir, file));
}

function sortPackagesAlphabetically(packages) {
  return packages.sort();
}

function findPackagesInDirectory(dirPath) {
  const packages = findPackagesRecursively(dirPath);
  return sortPackagesAlphabetically(new Set(packages).values());
}

function findPackagesInDirectorySync(dirPath) {
  return findPackagesInDirectory(dirPath).catch(err => {
    if (err.code === 'ENOENT') {
      return [];
    }
    throw err;
  });
}

module.exports = {
  findPackagesInDirectory,
  findPackagesInDirectorySync,
};
