```javascript
const template = Handlebars.compile(document.getElementById('suggestion-template').innerHTML);

function initAutocomplete() {
  const input = document.getElementById('searchInput');
  const suggestionsList = document.getElementById('suggestionsList');

  input.addEventListener('input', (event) => {
    const term = event.target.value;

    if (!term) {
      suggestionsList.innerHTML = '';
      return;
    }

    fetch('/get-suggestions.php?q=' + encodeURIComponent(term))
      .then((response) => response.json())
      .then((data) => {
        if (data.length > 0) {
          suggestionsList.innerHTML = template({ suggestions: data });
        } else {
          suggestionsList.innerHTML = '';
        }
      })
      .catch((error) => {
        console.error('Error fetching suggestions:', error);
      });
  });

  suggestionsList.addEventListener('click', (event) => {
    if (event.target.tagName === 'DIV') {
      const selectedItem = event.target.dataset;
      input.value = selectedItem.name;
      input.dataset.productId = selectedItem.id;
      input.dataset.upc = selectedItem.upc;
      suggestionsList.innerHTML = '';
    }
  });
}

initAutocomplete();
```

