const crypto = require('crypto'); // Ensure crypto module is available

let keyMap = new Map();

function generateKeyIdentifier(key) {
  // Check if key is null or empty
  if (!key) {
    throw new Error('Invalid key');
  }

  // Generate a random postfix
  let randomPostfix = crypto.randomBytes(16).toString('hex');

  // Generate a unique identifier using a Symbol function
