const fs = require('fs');

function removeFile(filePath) {
  return new Promise((resolve, reject) => {
    fs.unlink(filePath, (err) => {
      if (err) {
        if (err.code === 'ENOENT') {
          // File does not exist, resolve with success
          resolve();
        } else {
          // Error occurred, reject with error
          reject(err);
        }
      } else {
        // File was removed successfully, resolve with success
        resolve();
      }
    });
  });
}
