function createTimeZoneRegex(pattern, timeZone) {
  const validPatterns = /^([Pp](acific|eastern|mountain|central|atlantic|alaskan|new|china|indian|japan|korea|system)\s+[Tt]ime|[A-Za-z]{1,32}\/[A-Za-z]{1,32}$)/;

