```javascript
const crypto = require('crypto');
let keyCache = new Map();

function generateUniqueIdentifier(key) {
  if (keyCache.has(key)) {
    return keyCache.get(key);
  }

  let counter = 0;
  let id = key;

  while (keyCache.has(id)) {
    counter++;
    id = key + '_' + counter;
  }

  keyCache.set(id, true);

  // Generate a random postfix using a cryptographically secure random number generator
  const randomBytes = crypto.randomBytes(16);
  const randomPostfix = btoa(String.fromCharCode.apply(null, randomBytes));

  id += '_' + randomPostfix;

  return id;
}
