  const combinators = /[>+~]/g;
  const groups = /(?:[^\s,]+|#([\w\-]+)|(\.[\w\-]+)|&[^\s]+\s*)/g;
  const attributeTest = /([\w\-]+)(?:\[(?:([^=\]]+)(=|!=[^\]]*)?(?:"([^"]*)"|'([^']*)'|([^\]]*))\])/g;

