Here's a secure JavaScript function that generates a unique session ID using a combination of a random number and a secret key:

```javascript
function generateSessionId(secretKey, sessionIdLength) {
  if (typeof secretKey !== 'string' || secretKey.length <= 0) {
    throw new Error('Invalid secret key');
  }
  if (typeof sessionIdLength !== 'number' || sessionIdLength <= 0 || sessionIdLength > 255) {
    throw new Error('Invalid session ID length');
  }

  const randomBytes = new Uint8Array(crypto.getRandomValues(new Uint8Array(32)));
  const sessionId = btoa(
    secretKey
      .slice(0, 16) // Use a portion of the secret key for better entropy
      .split('')
      .map((char) => char.charCodeAt(0))
      .concat(Array.from(randomBytes))
      .map((byte) => ('0' + (byte & 0xFF).toString(16)).slice(-2))
      .join('')
  );

  return sessionId.substring(0, sessionIdLength);
}
```

