class ListManager {
  constructor(initialList) {
    this.list = initialList.slice().sort((a, b) => a - b);
  }

  addNumber(number) {
    const index = this.list.findIndex(value => value === number);

    if (index !== -1) {
      throw new Error("Number already exists in the list.");
    }

    this.list.push(number);
  }

  removeNumber(number) {
    const index = this.list.findIndex(value => value === number);

    if (index === -1) {
