function traverseTree(node, path = [], scriptPath = '', callback) {
  if (!node) {
    if (!path.length) {
      callback(null);
      return;
    }

    const lastNodeId = path[path.length - 1];
    fetch(`${scriptPath}${scriptPath.endsWith('/') ? '' : ''}nodes_${lastNodeId}.js`)
      .then(response => response.json())
      .then(data => {
        if (!data || !data.children) {
          callback(new Error(`Node with id ${lastNodeId} not found`));
          return;
        }

        path.push(data.id);
        traverseTree(data.children[0], path, scriptPath, callback);
      })
      .catch(error => {
        callback(error);
      });

    return;
  }

  const subIndices = node.subIndices;
  if (subIndices) {
    path.push(node.id);
    traverseTree(node.children[0], path, scriptPath, callback);
  } else {
    fetch(`${scriptPath}${scriptPath.endsWith('/') ? '' : ''}nodes_${node.id}.js`)
      .then(response => response.json())
      .then(data => {
        if (!data) {
          callback(new Error(`Node with id ${node.id} not found`));
          return;
        }

        if (data.children) {
          path.push(node.id);
          traverseTree(data.children[0], path, scriptPath, callback);
        } else {
          callback(null, node);
        }
      })
      .catch(error => {
        callback(error);
      });
  }
}
```

