function initDraggable(object, minX, maxX, btnLeft, btnRight) {
  if (object.draggable) return; // Prevent initializing multiple times

  object.draggable = true;

  object.style.position = "absolute"; // Ensure position is absolute for dragging

  object.onmousedown = Drag.start.bind(object);

  object.minX = minX;
  object.maxX = maxX;

  object.onDragStart = function () {
    this.classList.add("dragging");
  };

  object.onDrag = function (event) {
    const newX = event.clientX - object.offsetLeft;
    if (newX < this.minX) this.style.left = this.minX + "px";
    else if (newX > this.maxX) this.style.left = this.maxX + "px";
    else this.style.left = newX + "px";
  };

  object.onDragEnd = function () {
    this.classList.remove("dragging");
  };

  btnLeft.onmousedown = Drag.start.bind(btnLeft);
  btnLeft.onmouseup = Drag.stop.bind(btnLeft);

  btnRight.onmousedown = Drag.start.bind(btnRight);
  btnRight.onmouseup = Drag.stop.bind(btnRight);

  if (!isNaN(parseFloat(object.style.left)) && isFinite(object.style.left)) {
    object.style.right = "0px";
  }

  function Drag() {}

  Drag.prototype.start = function (event) {
    this.dragging = true;
    this.startX = event.clientX;
    this.startY = event.clientY;

    document.addEventListener("mousemove", this.move.bind(this));
    document.addEventListener("mouseup", this.stop.bind(this));
  };

  Drag.prototype.move = function (event) {
    if (!this.dragging) return;

    const object = event.target.closest(".draggable");
    if (!object) return;

    object.style.left = event.clientX - object.offsetLeft + "px";
  };

  Drag.prototype.stop = function () {
    this.dragging = false;
    document.removeEventListener("mousemove", this.move);
    document.removeEventListener("mouseup", this.stop);

    object.dispatchEvent(new Event("dragend"));
  };
}
