```javascript
const fs = require('fs-extra');
const path = require('path');
const child_process = require('child_process');

function executeCommandWithFileCheck(command, watchList, callback) {
  // Validate input
  if (typeof command !== 'string') {
    throw new Error('Invalid command');
  }
  if (!Array.isArray(watchList)) {
    throw new Error('Invalid watchList');
  }

  // Check for --watch option
  const watchOptionIndex = watchList.findIndex(item => item.startsWith('--watch='));
  const watchOption = watchOptionIndex > -1 ? watchList[watchOptionIndex] : null;

  // Execute command
  child_process.exec(command, (error, stdout, stderr) => {
    if (error) {
      return callback(error);
    }

    // Check for --watch option and input files
    if (watchOption) {
      watchList.forEach(filePath => {
        fs.pathExists(filePath)
          .then(exists => {
            if (!exists) {
              const errorMessage = `File '${filePath}' does not exist`;
              return callback(new Error(errorMessage));
            }
          })
          .catch(err => {
            if (err.code === 'ENOENT') {
              const errorMessage = `File '${filePath}' does not exist`;
              return callback(new Error(errorMessage));
            }
            return callback(err);
          });
      });

      // Callback with success
      callback(null, stdout);
    } else {
      // Callback with success and command output
      callback(null, stdout);
    }
  });
}

