  console.log('a user connected');

  socket.on('message', (msg) => {
    try {
      const jMsg = JSON.parse(msg);
      const newLedState = jMsg.led;

      // Update Firebase database with new LED state
      db.ref('ledState').set(newLedState);

      // Synchronously write new state to LED device
      const led = require('./led');
      led.writeSync(newLedState);

      socket.emit('ledStateUpdated', { success: true });
    } catch (error) {
      console.error('Error processing message:', error);
      socket.emit('ledStateUpdated', { success: false, error: 'Invalid message format' });
    }
  });

  socket.on('disconnect', () => {
    console.log('user disconnected');
  });
});

