function safeSplit(str, delimiter) {
  const regex = /(.*)(\\.|[^]*(?=([^]|$))|(?<=[^])\1)/g; // Regex pattern for handling escape sequences
  const matches = [];
  let match;

  while ((match = regex.exec(str)) !== null) {
    matches.push(match[1]);
  }

  if (matches.length === 0) {
    // Handle empty input string
    return [];
  }

  const result = [];
  let currentSubstring = '';

  for (let i = 0; i < matches.length; i++) {
    if (matches[i].endsWith(delimiter)) {
      // If the substring ends with the delimiter, add it to the result and continue
      result.push(matches[i]);
      continue;
    }

    // Otherwise, add the substring before the delimiter to the result
    result.push(currentSubstring + matches[i]);

    // Update the current substring for the next iteration
    currentSubstring = matches[i];
  }

  // Add the last substring without the delimiter
  if (currentSubstring.length > 0) {
    result.push(currentSubstring);
  }

  return result;
}
