```javascript
const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');
const session = require('express-session');

const app = express();
app.use(express.json());
app.use(session({ secret: 'secretKey', resave: false, saveUninitialized: false }));

const register = async (req, res) => {
  const { username, password, firstName, lastName } = req.body;

  const errors = [];

  // Input validation using express-validator
  body('username').isLength({ min: 3 }).withMessage('Username must be at least 3 characters long');
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters long');

  const validationResult = await new Promise((resolve) => {
    req.sanitize('username').trim().escape();
    req.sanitize('password').trim().escape();
    req.sanitize('firstName').trim().escape();
    req.sanitize('lastName').trim().escape();

    const result = validationResult(req);
    resolve(result);
  });

  if (!validationResult.isEmpty()) {
    errors.push({ msg: validationResult.array() });
    return res.status(400).json({ errors });
  }

  // Hash the password
  const salt = await bcrypt.genSalt(10);
  const hashedPassword = await bcrypt.hash(password, salt);

  // Register the user with a service (replace with your user registration logic)
  const newUser = { username, firstName, lastName, password: hashedPassword };
  // Save the new user to your database or user management service

  // Generate a JWT token
  const token = jwt.sign({ id: newUser.id }, 'secretKey', { expiresIn: '1h' });

  // Save the session
  req.session.user = { id: newUser.id, username, firstName, lastName };

  res.status(201).json({ user: { id: newUser.id, username, firstName, lastName }, token });
};

app.post('/register', [
  body('username').isLength({ min: 3 }).withMessage('Username must be at least 3 characters long'),
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters long'),
], register);

app.listen(3000, () => console.log('Server running on port 3000'));
```

