                  throw new Error("Invalid length for sequenceNumber event: " + length);
                }
                return {
                  subtype: "timeSignature",
                  numerator: stream.getUint16(position),
                  denominator: stream.getUint16(position + 2),
                  metronome: stream.getUint16(position + 4),
                  thirtyseconds: stream.getUint16(position + 6),
                  data: []
                };
              case 0x01:
                if (length !== 1) {
                  throw new Error("Invalid length for text event: " + length);
                }
                return {
                  subtype: "keySignature",
                  key: stream.getUint8(position),
                  scale: stream.getUint8(position + 1),
                  data: []
                };
              case 0x51:
                if (length !== 3) {
                  throw new Error("Invalid length for setTempo event: " + length);
                }
                return {
                  subtype: "sequencerSpecific",
                  data: new Uint8Array(buffer, position, length)
                };
              default:
                throw new Error("Unknown meta event subtype: " + subtypeByte);
            }
        }

      default:
        throw new Error("Unknown meta event type: " + eventTypeByte);
    }
  }

  let event;
  while ((event = readMetaEvent()) !== null) {
    yield event;
  }
}
