use Doctrine\DBAL\Connection;

function truncateTableAndResetId(Connection $connection, string $tableName): int {
    $tableSchema = $connection->createSchemaManager()->listTableDetails($tableName);
    $idColumnName = $tableSchema['columns'][array_keys($tableSchema['columns'])[0]]['name'];

    try {
        // Disable foreign key checks
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 0');

        // Truncate the table
        $connection->executeStatement("TRUNCATE TABLE {$tableName}");

        // Reset the auto-incrementing ID column
        $connection->executeStatement("ALTER TABLE {$tableName} AUTO_INCREMENT = 1");

        return 0;
    } catch (\Exception $e) {
        // Handle specific errors appropriately
        if ($e->getCode() === 'ER_BAD_TABLE_ERROR') {
            return -1;
        }

        // Retry with foreign key checks enabled
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 1');
        throw $e;
    } finally {
        // Enable foreign key checks
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 1');
    }
}
