function generateContentTypeHash(array $sources): string {
    $validSources = array_filter($sources, function ($source) {
        return isset($source->_id, $source->minifier, $source->minifyOptions);
    });

    $info = array_map(function ($source) {
        return [$source->_id, $source->minifier, $source->minifyOptions];
    }, $validSources);

    $serializedInfo = serialize($info);
    $maxAllowedLength = 1024 * 1024; // 1MB

