import java.util.stream.Collectors;

public class MockableMethodFilter {
    private static final Set<String> WHITELISTED_METHODS = Set.of(
            "getSimpleName",
            "getName",
            "isInterface",
            "isAbstract"
    );

    public static List<Method> filterMockableMethods(Class<?>... classes) {
        List<Method> mockableMethods = new ArrayList<>();
        for (Class<?> clazz : classes) {
            Method[] methods = clazz.getDeclaredMethods();
            List<Method> filteredMethods = Arrays.stream(methods)
                    .filter(method -> !method.isSynthetic())
                    .filter(method -> WHITELISTED_METHODS.contains(method.getName().toLowerCase()))
                    .filter(method -> method.getAnnotation(MockAnnotation.class) != null)
                    .collect(Collectors.toList());
            mockableMethods.addAll(filteredMethods);
        }
        return mockableMethods;
    }

    private static final class MockAnnotation {
    }

    private MockableMethodFilter() {
    }
}
