function execute_safe_php_code(string $input_code): string {
    // Validate input code
    if (empty($input_code)) {
        throw new RuntimeException('Input code is empty.');
    }

    // Generate a unique and secure filename
    $filename = uniqid('', true) . '.php';

    // Modify the code to include the hashed filename and a fake syntax error
    $modified_code = $input_code;
    $modified_code .= "\n // Hashed filename: " . hash('sha256', $filename) . "\n";
    $modified_code .= "\n // Fake syntax error: echo 'zzz';\n";

    // Save the modified code to a temporary file
    $temp_file = tmpnam(sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'php_temp_');
    file_put_contents($temp_file, $modified_code);

    // Execute the temporary file and capture the output
    ob_start();
    $output = '';
    $descriptor_spec = array(
        0 => array('file', $temp_file, 'r'),
        1 => array('pipe', 'w'),
        2 => array('pipe', 'w'),
    );
    $process = proc_open('php ' . $temp_file, $descriptor_spec, $pipes);

    if ($process) {
        // Read the output
        $output .= stream_get_contents($pipes[1]);

        // Close the output stream
        fclose($pipes[1]);

        // Close the input and error streams
        fclose($pipes[0]);
        fclose($pipes[2]);

        // Delete the temporary file
        unlink($temp_file);

        // Close the process
        proc_close($process);
    } else {
        throw new RuntimeException('Failed to execute the temporary PHP file.');
    }

    return $output;
}
