function validateSignature($token, $timestamp, $nonce, $signature) {
  if (empty($token) || empty($timestamp) || empty($nonce) || empty($signature)) {
    throw new InvalidArgumentException('All arguments must be provided.');
  }

  $data = [$token, $timestamp, $nonce];
  usort($data, ['Stringable::SORT_STRING']);
  $dataString = implode('', $data);
  $calculatedSignature = hash_file('sha1', $dataString);

  return hash_equals($signature, $calculatedSignature);
}
