function generateTextImage($text, $x, $y, $direction = IMAGE_TEXT_TB, $fontFile, $fontSize, $color, $backgroundColor, $padding) {
    $image = imagecreatetruecolor(imagesx($backgroundImage) + 2 * $padding, imagesy($backgroundImage) + 2 * $padding); // create image with padding
    imagefill($image, 0, 0, imagecolorallocate($image, hexdec(substr($backgroundColor, 1)), hexdec(substr($backgroundColor, 2)), hexdec(substr($backgroundColor, 3)))); // set background color
    $font = imageftstype($fontFile); // load font
    $textColor = imagecolorallocate($image, hexdec(substr($color, 1)), hexdec(substr($color, 2)), hexdec(substr($color, 3))); // set text color
    imagettftext($image, $fontSize, $direction, $x + $padding, $y + $padding, $textColor, $fontFile, $text); // add text with padding
    imageftclose($font); // close font
    return $image;
}

