function generate_boundary_and_read_chunk($content_type, $chunk_length) {
  $boundary = '--' . hash('sha256', 'Content-Type:' . $content_type . '-' . microtime());

  $headers = ['Content-Type' => $content_type, 'Content-Length' => $chunk_length];
  $options = [
    'http' => [
      'method' => 'GET',
      'header' => http_build_query($headers),
    ],
  ];

  $context = stream_context_create($options);
  $fp = fopen('php://temp', 'r+', 0, 0);
  fseek($fp, 0, SEEK_SET); // Reset the file pointer to the beginning

  $chunk = '';
  while (($data = fread($fp, $chunk_length)) !== false) {
    $chunk .= $data;
  }
  fseek($fp, 0, SEEK_SET); // Reset the file pointer to the beginning

  $response = stream_get_contents($fp, $chunk_length, $context);
  if ($response === false) {
    throw new Exception('Failed to read response');
  }

  $this->validate_chunked_data($response); // Call a separate method to validate the chunked data

  return [$boundary, $chunk];
}

private function validate_chunked_data($data) {
  $chunks = explode("\r\n--$this->boundary\r\n", $data);
  foreach ($chunks as $chunk) {
    if (empty($chunk)) {
      continue;
    }

    list($size, $body) = explode("\r\n", $chunk, 2);

    if (empty($size) || !is_numeric($size) || intval($size) < 0) {
      throw new Exception('Invalid chunk size');
    }

    if (strlen($body) !== intval($size)) {
      throw new Exception('Chunk size does not match chunk data');
    }
  }
}
```

