function verifyPassword($plainTextPassword, $hashedPassword) {
    if (empty($plainTextPassword) || empty($hashedPassword)) {
        throw new InvalidArgumentException('Both plain text password and hashed password are required.');
    }

    $salt = random_bytes(16); // Generate a random salt
    $plainTextPasswordWithSalt = $plainTextPassword . $salt;
    $hashedPasswordWithSalt = $hashedPassword; // Assuming the hashed password already includes the salt

    $hashedPassword = hash_init('sha1'); // Initialize SHA-1 hashing
    hash_update($hashedPassword, $plainTextPasswordWithSalt); // Hash the plain text password with the salt
    $generatedHash = hash_final($hashedPassword); // Generate the final hash

    if (!hash_equals($generatedHash, $hashedPasswordWithSalt)) { // Compare the hashes
        return false;
    }

    return true;
}
