DELIMITER $$
CREATE FUNCTION create_new_user(p_username VARCHAR(255), p_password VARCHAR(255), p_name VARCHAR(255))
BEGIN
    -- Validate input
    IF LENGTH(p_username) > 255 OR LENGTH(p_password) > 255 OR LENGTH(p_name) > 255 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Input values are too long';
    END IF;

    -- Escape user input
    SET p_username = CommonsUtils.escapeSql(p_username);
    SET p_password = CommonsUtils.escapeSql(p_password);
    SET p_name = CommonsUtils.escapeSql(p_name);

    -- Create new user table for the user
    SET @table_name = CONCAT('user_', p_username);
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE TABLE_SCHEMA = 'kin'
          AND TABLE_NAME = @table_name
    ) THEN
        CREATE TABLE `kin`.`%` (
            id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
            username VARCHAR(255) NOT NULL UNIQUE,
            pwd VARCHAR(255) NOT NULL,
            name VARCHAR(255) NOT NULL,
            PRIMARY KEY (id)
        ) ENGINE=InnoDB;
    END IF;

    -- Insert new user into the 'users' table
    INSERT INTO `kin`.`users` (username, pwd, name)
    VALUES (p_username, SHA1(CONCAT(RAND(), p_password)), p_name);

    -- Commit transaction
    COMMIT;
END$$
