function executeCommandAndLog($command, $outputFilePath, $logFilePath, $escapeOutput = true) {
    // Validate input parameters
    if (!is_string($command) || empty($command)) {
        throw new InvalidArgumentException('Command cannot be empty.');
    }
    if (!is_writable(sys_get_temp_dir()) || !is_writable(dirname($outputFilePath)) || !is_writable(dirname($logFilePath))) {
        throw new RuntimeException('Output and log files must be writable.');
    }

    // Execute the command and capture output
    $output = shell_exec($command);
    $exitCode = shell_exec("echo $?", output_add_all: $output);
    $output = trim($output);

    // Log the command and output
    file_put_contents($logFilePath, "Command: {$command}\nOutput:\n{$output}\n", FILE_APPEND);

    // Modify output based on input parameter
    if ($escapeOutput) {
        $output = escapeshellarg($output);
    }

    return $output;
}
