use Respect\Validation\Validator as v;
use Psr\Container\ContainerInterface;
use PDO;

class User {
    private $db;
    private $password;

    public function __construct(ContainerInterface $container) {
        $this->db = $container->get(PDO::class);
    }

    public function validateAndStore($data) {
        $input = $this->validateInput($data);
        $this->password = $input['password'];
        $hashedPassword = $this->hashPassword($this->password);
        $this->storeUser($input, $hashedPassword);
    }

    private function validateInput($data) {
        $rules = [
            'username' => v::noWhitespace()->notEmpty()->alpha()->length(3, 32),
            'email' => v::email()->notEmpty(),
            'password' => v::noWhitespace()->notEmpty()->length(8, 32),
        ];

        $validation = new Validator($data, $rules);
        $input = [];

        if ($validation->isValid()) {
            $input = $data;
        } else {
            throw new Exception('Invalid input data');
        }

        return $input;
    }

    private function hashPassword($password) {
        return password_hash($password, PASSWORD_ARGON2ID);
    }

    private function storeUser($input, $password) {
        try {
            $stmt = $this->db->prepare("INSERT INTO users (username, email, password) VALUES (:username, :email, :password)");
            $stmt->bindParam(':username', $input['username']);
            $stmt->bindParam(':email', $input['email']);
            $stmt->bindParam(':password', $password);
            $stmt->execute();
        } catch (Exception $e) {
            throw new Exception('Error storing user data: ' . $e->getMessage());
        }
    }
}
```

