function deleteContentElement(&PDO $db, int $elementId) {
  $stmt = $db->prepare("SELECT id FROM content WHERE id < :id ORDER BY sort_order ASC LIMIT 1 FOR UPDATE");
  $stmt->bindParam(":id", $elementId);
  $stmt->execute();
  $prevElementId = $stmt->fetchColumn();

  if ($prevElementId) {
    $stmt = $db->prepare("UPDATE content SET sort_order = sort_order - 1 WHERE id = :prevId");
