function createTableAndQuery($dbname, $table, $columns, $primaryKey) {
    $columnDefines = implode(', ', array_map(function ($column) {
        return "$column VARCHAR(255)";
    }, array_keys($columns)));

    try {
        $pdo = new PDO("mysql:host=localhost;dbname=$dbname", "username", "password");
        $stmt = $pdo->prepare("CREATE TABLE IF NOT EXISTS $table (
            $primaryKey INT PRIMARY KEY,
            $columnDefines
        )");
        $stmt->execute();

        $query = "SELECT * FROM $table WHERE condition1 = :condition1 AND condition2 = :condition2";
        $stmt = $pdo->prepare($query);
        $stmt->bindParam(':condition1', $condition1);
        $stmt->bindParam(':condition2', $condition2);
        $stmt->execute();

        $result = $stmt->fetchAll(PDO::FETCH_ASSOC);
        $stmt->closeCursor();
        $pdo = null;

        return $result;
    } catch (PDOException $e) {
        return null;
    }
}
