function generateAndRedirectValidSlug($input_data, $base_url) {
  $allowed_characters = '-_a-zA-Z0-9';
  $slug = '';

  // Validate user input data
  if (!is_array($input_data) || !array_key_exists('url', $input_data) || empty($input_data['url'])) {
    header('Location: ' . $base_url . '/error');
    exit();
  }

  $user_provided_url = $input_data['url'];

  // Validate and sanitize user-provided URL
  $url_parts = parse_url($user_provided_url);
  if (!isset($url_parts['host']) || !filter_var($url_parts['host'], FILTER_VALIDATE_URL)) {
    header('Location: ' . $base_url . '/error');
    exit();
  }

  // Generate valid slug from user-provided URL
  $path = $url_parts['path'];
  $path_parts = explode('/', trim($path, '/'));
  array_shift($path_parts);
  $slug = implode('-', array_map('strtolower', $path_parts));

  // Validate slug format
  if (preg_match("/[^{$allowed_characters}]/", $slug)) {
    header('Location: ' . $base_url . '/error');
    exit();
  }

  // Redirect to new URL with success message or errors
  $redirect_url = $base_url . '/success';
  $errors = [];

  if (isset($input_data['errors'])) {
    $redirect_url .= '?errors=' . urlencode(serialize($input_data['errors']));
  }

  header("Location: {$redirect_url}");
  exit();
}
