function sort_and_write_leases($leases, $sort_field, $leases_file, $service) {
    // Validate input: ensure $leases is an array and each element is a lease record
    if (!is_array($leases)) {
        throw new Exception("Invalid input: $leases must be an array of lease records.");
    }

    // Sort the leases based on the specified field
    usort($leases, function ($a, $b) use ($sort_field) {
        return strcmp($a[$sort_field], $b[$sort_field]);
    });

    // Open the file for writing
    $fd = fopen($leases_file, 'w');

    // Check if file was opened successfully
    if ($fd === false) {
        throw new Exception("Failed to open file: $leases_file");
    }

    // Write the sorted leases to the file
    $leases_contents = array_map(function ($lease) {
        return implode("\t", array_values($lease)) . PHP_EOL;
    }, $leases);

    if (fwrite($fd, implode("\n", $leases_contents)) === false) {
        fclose($fd);
        throw new Exception("Failed to write to file: $leases_file");
    }

    fclose($fd);

    // Restart the service
    call_user_func($service . '_configure');
