function updateUserPassword($dao, $username, $newPassword) {
    // Validate password strength using zxcvbn library
    $passwordStrength = password_strength_check($newPassword);
    if (!$passwordStrength['status']) {
        throw new Exception('Password is too weak. Please choose a stronger password.');
    }

    try {
        // Hash the new password using bcrypt with a random salt
        $salt = openssl_random_pseudo_bytes(16);
        $hashedPassword = password_hash($newPassword . $salt, PASSWORD_BCRYPT);

        // Update the user's password hash in the database
        $stmt = $dao->prepare("UPDATE users SET password = :hashed_password WHERE username = :username");
        $stmt->bindParam(':username', $username);
        $stmt->bindParam(':hashed_password', $hashedPassword);
        $stmt->execute();

        // If the update was successful, notify other components
        event(new UserPasswordUpdatedEvent($username));

    } catch (Exception $e) {
        throw new Exception('Error updating user password: ' . $e->getMessage());
    }
}
