function enqueueScript(scriptName, source, version, dependencies, isRemote, currentPage) {
  if (document.querySelectorAll(`script[src="${source}"][type="text/javascript"]`).length > 0) {
    console.warn(`Script "${scriptName}" has already been enqueued.`);
    return;
  }

  if (currentPage && !matchesCondition(currentPage, scriptName)) {
    console.warn(`Script "${scriptName}" is not needed on the current page.`);
    return;
  }

  wp.enqueueScript(scriptName, source, dependencies, version, isRemote);
}

function matchesCondition(currentPage, scriptName) {
  switch (scriptName) {
    case 'jquery':
      return isJQueryPage();
    case 'comment-reply':
      return isCommentsPage();
    case 'gmaps':
      return isGoogleMapsPage();
    case 'custom':
      return isCustomScriptPage();
    default:
      throw new Error(`Unknown script name: "${scriptName}"`);
  }

  function isJQueryPage() {
    return document.documentElement.classList.contains('wp-core-ui') || document.documentElement.classList.contains('admin-bar');
  }

  function isCommentsPage() {
    return is_single() && comments_open() && get_option('thread_comments');
