function getUserID($cookieName, $cookieType = COOKIE_DEFAULT, $sessionName = 'session') {
    if ($cookieType === COOKIE_DEFAULT) {
        $cookieValue = isset($_COOKIES[$cookieName]) ? $_COOKIES[$cookieName] : '';
        if (filter_var($cookieValue, FILTER_VALIDATE_JSON)) {
            $cookieData = json_decode($cookieValue, true);
            if (isset($cookieData['userId']) && is_numeric($cookieData['userId'])) {
                return intval($cookieData['userId']);
            }
        }
    }

    if (session_status() === PHP_SESSION_ACTIVE) {
        $sessionValue = isset($_SESSION[$sessionName]) ? $_SESSION[$sessionName] : [];
        if (isset($sessionValue['userId']) && is_numeric($sessionValue['userId'])) {
            return intval($sessionValue['userId']);
        }
    }

    return 1;
}
