function insert($db, $tableName, $columns, $values) {
    $validColumns = array_diff($columns, ['password']); // Exclude password column from $columns

    $query = "INSERT INTO {$tableName} (";
    $query .= implode(", ", $validColumns);
    $query .= ") VALUES (";

    $bindValues = [];
    foreach ($validColumns as $column) {
        array_push($bindValues, ":{$column}");
    }

    if (in_array("password", $columns)) {
        $passwordIndex = array_search("password", $columns);
        $values[$passwordIndex] = password_hash($values[$passwordIndex], PASSWORD_DEFAULT);
    }

    $query .= implode(", ", $bindValues);
    $query .= ")";

    $statement = $db->prepare($query);

    for ($i = 0; $i < count($columns); $i++) {
        if (in_array($columns[$i], $validColumns)) {
            $statement->bindValue(":" . $columns[$i], $values[$i]);
        }
    }

    $statement->execute();

    $lastInsertId = $db->lastInsertId();

    return [$statement->rowCount(), $lastInsertId];
}
