def read_cached_response(cache_key):
    cache_file = f"cache/{cache_key}.json"
    if not os.path.exists(cache_file):
        return None
    with open(cache_file, 'r') as f:
        return json.load(f)

def write_cached_response(cache_key, response):
    cache_file = f"cache/{cache_key}.json"
    with open(cache_file, 'w') as f:
        json.dump(response, f)

def handle_get_request(request):
    cache_key = generate_cache_key(request)
    cached_response = read_cached_response(cache_key)
    if cached_response:
        return cached_response

    response = {}
    try:
        with request.urlopen() as response:
            response['status'] = response.status
            response['headers'] = {name: value.strip() for name, value in response.headers.items()}
            response['body'] = response.read()
            write_cached_response(cache_key, response)
    except error.HTTPError as e:
        response['error'] = str(e)
    except error.URLError as e:
        response['error'] = str(e.reason)
