use rand::prelude::*;
use std::slice;

fn get_subarray<T: Clone>(original: &[T], dimensions: Vec<usize>, intervals: Vec<(usize, usize)>) -> Vec<T> {
    let (num_elements, total_size): (usize, usize) = (original.len(), dimensions.iter().sum::<usize>());
    let mut rng = thread_rng();

    // Generate random indices for each dimension
    let mut indices: Vec<(usize, usize)> = Vec::new();
    for _ in 0..dimensions.len() {
        let (begin, end) = intervals[rng.gen_range(0..dimensions.len())];
        indices.push((begin, min(end, dimensions[begin])));
    }

    // Calculate the size of the subarray
    let subarray_size: usize = product(&indices.iter().map(|&(i, j)| j).collect::<Vec<usize>>());

    // Allocate memory for the subarray and copy the elements
    let mut subarray: Vec<T> = Vec::with_capacity(subarray_size);
    for _ in 0..subarray_size {
        let (x, y): (usize, usize) = indices.choose_multiple(&mut rng, 2).unwrap();
        subarray.push(original[x + y * dimensions[x]]);
    }

    subarray
}

fn product(iter: impl Iterator<Item = usize>) -> usize {
    iter.fold(1, |acc, i| acc * i)
}
