import random

def generate_dataset(columns, runs, size):
    dataset = [[] for _ in range(columns)]

    for col in range(columns):
        if col not in dataset:
            dataset[col] = []

        for _ in range(runs[col]):
            sample = [random.randint(0, size // runs[col] - 1) for _ in range(size // runs[col])]
            dataset[col].extend(sample)

    final_dataset = []
    for col in dataset:
        final_dataset.extend(col)

    return final_dataset
