import os
import time
import re
import tempfile
import subprocess

class AndroidScreenshot:
    def __init__(self, output_dir):
        self.output_dir = output_dir
        self.last_screenshot = 0
        self.adb = subprocess.Popen(["adb", "-s", self.get_device_serial()], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    def get_device_serial(self):
        devices = self.adb.stdout.readlines()
        if len(devices) > 1:
            return devices[1].decode().split()[1]
        else:
            raise Exception("No devices found")

    def take_screenshot(self):
        try:
            self.adb.stdin.write(b"screencap -p\n")
            self.adb.stdin.flush()
            self.adb.stdin.write(b"exit\n")
            self.adb.stdin.close()

            filename = tempfile.mktemp(prefix="screen_", dir=self.output_dir)
            self.adb.stdout.readinto(open(filename, "wb").write)
            os.rename(filename, os.path.join(self.output_dir, "screen_" + time.strftime("%Y-%m-%d_%H%M%S.png")))
            self.last_screenshot = time.time()
        except Exception as e:
            print(f"Error taking screenshot: {e}")

    def read_logcat(self):
        logcat_output = self.adb.stdout.readline().decode()
        if logcat_output:
            with open("log.txt", "a") as f:
                f.write(logcat_output)
                parsed_log = re.findall(r"(?P<tag>\S+):(?P<level>\S+):(?P<message>.*)", logcat_output)
                for log in parsed_log:
                    print(f"[{log['tag']}] [{log['level']}] {log['message']}")

    def run(self):
        while self.adb.poll() is None:
            try:
                if self.output_dir and (time.time() - self.last_screenshot) >= 5:
                    self.take_screenshot()

                self.read_logcat()
                self.adb.stdin.write(b"logcat -d\n")
                self.adb.stdin.flush()
            except Exception as e:
                print(f"Error reading logcat: {e}")

if __name__ == "__main__":
    output_dir = "/path/to/output/directory"
    android = AndroidScreenshot(output_dir)
    android.run()
