import os
import shutil
import subprocess
import pathlib

def is_valid_dimension(dimension):
    """Validate if the given dimension is within acceptable bounds."""
    if not dimension or not dimension.isdigit() or int(dimension) <= 0:
        return False
    return int(dimension)

def normalize_path(path):
    """Normalize the given path and ensure it does not contain traversal sequences."""
    path = pathlib.Path(path).absolute()
    path = path.with_suffix('')
    return str(path)

def resize_images(image_filenames, output_directory, dimension):
    """Resize each image to the specified dimension and save it to the output directory."""
    for filename in image_filenames:
        input_path = normalize_path(os.path.join(os.getcwd(), filename))
        output_path = normalize_path(os.path.join(output_directory, f"{os.path.basename(filename)}_resized_{dimension}px.jpg"))

