import os
import re
import subprocess
import sys
import tempfile

def tokens(text):
    """Tokenize text using regex."""
    return re.findall(r'\w+', text.lower())

def make_bow(tokens, vocab):
    """Create bag-of-words representation."""
    bow = {}
    for token in tokens:
        if token in vocab:
            bow[token] = bow.get(token, 0) + 1
    return bow

def words_to_dict(file):
    """Read words from file and return as dictionary."""
    return dict(map(lambda x: (x.strip().split()[0], int(x.strip().split()[1])),
                    filter(lambda x: x.strip(), file.read().splitlines())))

def extract_text_from_pdf(pdf_file):
    """Extract text from PDF using pdftotext."""
    base, ext = os.path.splitext(pdf_file)
    with tempfile.TemporaryFile() as temp_file:
        subprocess.run(["pdftotext", "-", "-"], stdin=open(pdf_file, "rb"), stdout=temp_file, check=True)
        text = temp_file.read().decode("utf-8")
        temp_file.close()
    return text

def save_bow_to_file(bow, output_file):
    """Save bag-of-words to file."""
    with open(output_file, "w") as out:
        out.write(str(len(bow)) + "\n")
        for token, count in bow.items():
            out.write(token + " " + str(count) + "\n")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python extract_text.py <pdf_file> <output_file>")
        sys.exit(1)

    pdf_file = sys.argv[1]
    output_file = sys.argv[2]

    text = extract_text_from_pdf(pdf_file)
    tokens = tokens(text)
    vocab = {}
    if os.path.exists("vocab.dat"):
        vocab = words_to_dict(open("vocab.dat"))

    bow = make_bow(tokens, vocab)
