    filter = {}

    try:
        # Open shelve file for writing if it doesn't exist, or read-only if it does
        if not os.path.exists(filename):
            self.shelf = shelve.open(filename, flag='c', protocol=2)
        else:
            self.shelf = shelve.open(filename, flag='r', protocol=2)

        # Store data in the filter with the corresponding data type
        if data_type is int:
            filter['int_data'] = []
        elif data_type is float:
            filter['float_data'] = []
        elif data_type is str:
            filter['str_data'] = []

        self.shelf['filter'] = filter
    except Exception as e:
        print(f"Error creating filter: {e}")
        return None

    return filter
