    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL
  );

  -- Insert first two rows with unique names
  INSERT INTO my_table (name) VALUES ('aaa');
  SET unique_name = (SELECT name FROM my_table ORDER BY RAND() LIMIT 1 OFF);
  INSERT INTO my_table (name) VALUES (unique_name);

  -- Acquire write lock
  SET @lock_name = p_lock_name;
  DECLARE lock_acquired BOOL DEFAULT FALSE;
  DECLARE lock_error INT;
  DO
    SET lock_error = 0;
    SET lock = GET_LOCK('my_table:_' || @lock_name, 5);
    IF lock.trx_state = 'locked' THEN
      SET lock_acquired = TRUE;
      LEAVE LOCK_LOOP;
    ELSEIF lock.trx_state = 'not locked' THEN
      SET lock_error = LOCK_WAIT_TIMEOUT;
    ELSE
      SET lock_error = LOCK_TABLES_FULL;
    END IF;
  LOOP LOCK_LOOP;

  -- Insert third row with non-unique name
  IF NOT lock_acquired THEN
    THROW OPERATIONAL ERROR 'Could not acquire lock';
  END IF;

  INSERT INTO my_table (name) VALUES ('bbb'); -- This will raise an OperationalError since 'bbb' is not unique

  -- Release lock
  RELEASE_LOCK('my_table:_' || @lock_name);

  -- Update output parameter
