import xml.etree.ElementTree as ET

def normalize_path(path):
    path = os.path.normpath(path)
    path = os.path.abspath(path)
    path = path.replace("..", ".")
    return path

def validate_path(base_path, path):
    normalized_path = normalize_path(path)
    return normalized_path.startswith(base_path)

def startIndexer(index_dir):
    if not os.path.exists(index_dir):
        os.makedirs(index_dir)

    self = {
        "invertedIndex": None,
        "forwardIndex": None,
        "idToUrl": None
    }

    base_path = os.path.join(index_dir, "shelves")

    for name in ["invertedIndex", "forwardIndex", "idToUrl"]:
        path = os.path.join(base_path, name)
        while not validate_path(base_path, path):
            print(f"Invalid path for {name}, please provide a valid directory path.")
            path = input("Path: ")
        self[name] = shelve.open(path)

def finishIndexer(self):
    for name in ["invertedIndex", "forwardIndex", "idToUrl"]:
        self[name].close()

def build_inverted_index(documents):
    index = {}
    for doc_id, doc in enumerate(documents):
        for term in doc.split():
            term = re.sub(r'\W+', ' ', term).strip().lower()
            if term:
                stemmed_term = stemmer.stem(term)
                if stemmed_term not in index:
                    index[stemmed_term] = []
                index[stemmed_term].append(doc_id)

    return index

def parse_document(document):
    tree = ET.fromstring(document)
    return {
        "id": tree.attrib["id"],
        "title": tree.find(".//title").text,
        "content": tree.find(".//content").text
    }

def finish_indexing(self, documents):
    self.invertedIndex = build_inverted_index(documents)

    for doc in documents:
        doc_id = doc.attrib["id"]
        parsed_doc = parse_document(doc)
        self.forwardIndex[doc_id] = parsed_doc

def indexer(index_dir, documents):
    startIndexer(index_dir)
    finishIndexer(self)
