class CommitHistoryAnalyzer:
    def __init__(self, repository_path, verbose=False):
        self.repository_path = repository_path
        self.commit_history = {}
        self.verbose = verbose

    def analyze(self):
        tip = self.get_tip()
        self.commit_history[tip] = Commit(tip)

        for commit_id in self.get_commit_ids_range(tip, 0):
            commit = self.commit_history[commit_id]
            parents = self.get_parents(commit_id)

            if self.verbose:
                print(f'Analyzing commit {commit_id}...')

            if parents:
                parent_ids = parents.split(' ')
                for parent_id in parent_ids:
                    if parent_id not in self.commit_history:
                        self.commit_history[parent_id] = Commit(parent_id)
                        self.commit_history[parent_id].parents.append(commit_id)
                        self.analyze_parent_relationship(parent_id, commit_id)

            commit.parents = parents.split(' ')

    def analyze_parent_relationship(self, parent_id, child_id):
        self.commit_history[parent_id].children = self.commit_history[parent_id].children or []
        self.commit_history[parent_id].children.append(child_id)

    def get_tip(self):
        tip = subprocess.check_output(f'hg id --rev --top --template "{node()}"', shell=True, cwd=self.repository_path).decode().strip()
        return tip

    def get_commit_ids_range(self, start_commit_id, end_commit_id):
        commit_ids = []
        commit_id = start_commit_id
        while commit_id != end_commit_id:
            commit_ids.append(commit_id)
            commit_id = self.get_prev_commit_id(commit_id)
        return commit_ids[::-1]

    def get_parents(self, commit_id):
        output = subprocess.check_output(f'hg log -r {commit_id} --template "{parents}"', shell=True, cwd=self.repository_path).decode()
        return output.strip()

    def get_prev_commit_id(self, commit_id):
        try:
            return next((parent_id for parent_id in self.commit_history[commit_id].parents), None)
        except StopIteration:
            return None

analyzer = CommitHistoryAnalyzer('/path/to/repository')
analyzer.analyze()

for commit in list(analyzer.commit_history.values()):
    print(f'Commit {commit.id}: {len(commit.parents)} parent(s)')
