import subprocess, io

def safe_popen(command, mode="r"):
    if not isinstance(command, str):
        raise TypeError("invalid command type (expected string)")
    if mode not in ("r", "w"):
        raise ValueError("invalid mode %r" % mode)

    if mode == "r":
