            args=command.split(),
            stdin=subprocess.PIPE,
            stdout=subprocess.DEVNULL,
            universal_newlines=True,
            preexec_fn=os.setpgrp
        )
        return _wrap_close(io.TextIOWrapper(process.stdin, newline=''), process)

def _wrap_close(stream, process):
    def close():
        stream.close()
        process.wait()

