from io import StringIO

class InputIterator:
    def __init__(self, input_source, buffer_size=1024, fail_on_missing_input=False):
        self.input_source = input_source
        self.buffer_size = buffer_size
        self.fail_on_missing_input = fail_on_missing_input
        self.buffer = StringIO()

        if callable(self.input_source.read):
            self.iterator = iter(self.input_source, b'')
        else:
            self.iterator = self.input_source

    def __iter__(self):
        return self

    def __next__(self):
        if not self.buffer.tell():
            try:
                data = next(self.iterator)
                self.buffer.write(data)
                if len(self.buffer.getvalue()) < self.buffer_size:
                    self.buffer.seek(0)
                    raise StopIteration
            except StopIteration:
                if self.fail_on_missing_input:
                    raise ValueError("Input source is empty")
                else:
                    return b''

        return self.buffer.getvalue()[:self.buffer_size].decode()

    @classmethod
    def from_json(cls, state):
        obj = state.get('input_iterator')
        if obj is None:
            obj = {}
        obj['iterator'] = json.loads(state.get('input_iterator_json', '[]'))
        obj['fail_on_missing_input'] = state.get('input_iterator_fail_on_missing_input', False)
        return cls(**obj)

    def to_json(self):
        return {
            'input_iterator': self,
            'input_iterator_json': json.dumps(self.iterator),
            'input_iterator_fail_on_missing_input': self.fail_on_missing_input
        }
