import os
from django.core.exceptions import PermissionDenied
from libiscsi import iSCSILogin, iSCSILogout, iSCSILoginContext, iSCSITask, iSCSITaskError, iSCSITaskComplete

class DellStorageCenterISCSIDriverConfig:
    def __init__(self, configuration):
        self.configuration = configuration
        self.driver = None

        self.validate_configuration()
        self.initialize_driver()

    def validate_configuration(self):
        if not self.is_valid_directory(self.configuration.dell_sc_server_folder):
            raise ValueError("Invalid server folder path.")

        if not self.is_valid_directory(self.configuration.dell_sc_volume_folder):
            raise ValueError("Invalid volume folder path.")

        self.driver = iSCSILoginContext()
        self.driver.iscsi_ip_address = self.configuration.iscsi_ip_address
        self.driver.iscsi_login = iSCSILogin(self.configuration.san_login, self.configuration.san_password)
        self.driver.iscsi_login_context = self.driver.iscsi_login.login(self.driver)

        if not self.driver.iscsi_login_context:
            raise ValueError("Failed to login to Dell Storage Center iSCSI.")

    def initialize_driver(self):
        self.driver.dell_sc_server_folder = self.configuration.dell_sc_server_folder
        self.driver.dell_sc_volume_folder = self.configuration.dell_sc_volume_folder

        self.driver.dell_sc_api_port = self.configuration.dell_sc_api_port

        self.driver.get_driver_data = self.get_driver_data
        self.driver.release_platform_device = self.release_platform_device

    def get_driver_data(self, platform_device):
        task = iSCSITask(self.driver.driver_session, "GetDriverData", {"Device": platform_device})
        task.dispatch()

        if task.isError():
            error = iSCSITaskError(task)
            self.driver.release_platform_device(platform_device)
            raise error

        return task.results["Data"]

    def release_platform_device(self, platform_device):
        if not self.driver.iscsi_login_context:
            raise PermissionDenied("Not logged in to Dell Storage Center iSCSI.")

        if not self.driver.iscsi_login.isLoggedIn():
            raise PermissionDenied("Logged out of Dell Storage Center iSCSI.")

        task = iSCSITask(self.driver.driver_session, "ReleaseTarget", {"Target": platform_device})
        task.dispatch()

        if task.isError():
            error = iSCSITaskError(task)
            raise error

    def is_valid_directory(self, directory):
        if not os.path.isdir(directory):
            raise ValueError("Invalid directory path.")

        if not self.has_write_permission(directory):
            raise PermissionDenied("User does not have write permission to the directory.")

        return directory

    def has_write_permission(self, directory):
        try:
            with open(os.path.join(directory, "test.txt"), "w") as file:
                file.write("test")
                os.remove(os.path.join(directory, "test.txt"))
                return True
        except PermissionError:
            return False
