import hmac, hashlib, os, json

def _get_session_config():
    session_file = os.path.expanduser("~/.config/my_app/session.json")
    if os.path.isfile(session_file):
        with open(session_file, "r") as f:
            session = json.load(f)
    else:
        session = {}
    return session

def _verify_user_permissions(session, directory):
    if "permissions" not in session:
        raise Exception("Missing permissions in session configuration")
    if directory not in session["permissions"]:
        raise Exception("User not allowed to access directory: {}".format(directory))
    return True

def _authenticate_env_vars(env_vars, auth_mechanism, session):
    if auth_mechanism not in ["OS", "ST"]:
        raise Exception("Invalid authentication mechanism: {}".format(auth_mechanism))

    if auth_mechanism == "OS":
        os_auth_url = env_vars.get("OS_AUTH_URL")
        os_username = env_vars.get("OS_USERNAME")
        os_password = env_vars.get("OS_PASSWORD")
        os_tenant_name = env_vars.get("OS_TENANT_NAME")
        auth = env_vars.get("AUTH")

        if not all([os_auth_url, os_username, os_password, os_tenant_name, auth]):
            raise Exception("Missing required environment variables for OS authentication")

        session["auth_version"] = "1.0"
    elif auth_mechanism == "ST":
        st_auth = env_vars.get("ST_AUTH")
        st_user = env_vars.get("ST_USER")
        st_key = env_vars.get("ST_KEY")

        if not all([st_auth, st_user, st_key]):
            raise Exception("Missing required environment variables for ST authentication")

        session_config = _get_session_config()
        session["session"] = session_config

        key = session_config.get("key")
        if not key:
            raise Exception("Missing key in session configuration")

        digest = hmac.new(key.encode(), msg=json.dumps(env_vars).encode(), digestmod=hashlib.sha256).hexdigest()
        if digest != st_auth:
            raise Exception("Invalid authentication token")

        session["auth_version"] = "2.0"

    return session

def authenticate_env_vars(env_vars):
    session = {}
    auth_mechanism = env_vars.get("AUTH_MECHANISM")

    try:
        session = _authenticate_env_vars(env_vars, auth_mechanism, session)
    except Exception as e:
        return {"error": str(e)}

    return session
