#!/bin/bash

download_file() {
  local url="$1"
  local temp_dir="$(mktemp -d)" || { echo "Failed to create temporary directory."; return 1; }
  local output_file="$(mktemp "$temp_dir/download.XXXXXX")"
  local curl_opts="-C -L --progress-bar --fail"

  curl "$curl_opts" --output "$output_file" "$url" || {
    echo "Download failed: $?"
    rm -rf "$temp_dir"
    return 1;
  }

  local file_ext="${output_file##*.}"
  local file_name="${output_file%.*}"
  local file_path="${temp_dir}/${file_name}.${file_ext}"
  mv "$output_file" "$file_path"

  echo "File downloaded successfully: $file_path"
  rm -rf "$temp_dir"
  echo
  exit 0
}
