import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.nio.charset.StandardCharsets;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.KeySpec;
import java.util.Base64;
import java.util.Scanner;

public class CryptographicProgram {

    public static void main(String[] args) {
        if (args.length != 3) {
            System.out.println("Usage: java CryptographicProgram <input> <algorithm> <password>");
            return;
        }

        String input = args[0];
        String algorithm = args[1];
        String password = args[2];

        try {
            byte[] inputBytes = input.getBytes(StandardCharsets.UTF_8);
            byte[] hash = generateHash(algorithm, inputBytes);
            System.out.println("Hash: " + bytesToHex(hash));

            byte[] key = deriveKey(password);
            byte[] decryptedData = decryptData(inputBytes, key);
            System.out.println("Decrypted data: " + new String(decryptedData, StandardCharsets.UTF_8));

        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static byte[] generateHash(String algorithm, byte[] input) throws NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance(algorithm);
        byte[] hash = messageDigest.digest(input);
        return hash;
    }

    private static byte[] deriveKey(String password) throws NoSuchAlgorithmException {
        KeyGenerator keyGenerator = KeyGenerator.getInstance("PBKDF2WithHmacSHA256");
        keyGenerator.init(128, new SecureRandom());
        KeySpec keySpec = keyGenerator.generateKeySpec();
        return ((KeySpec) keySpec).getEncoded();
    }

    private static byte[] decryptData(byte[] encryptedData, byte[] key) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        IvParameterSpec iv = new IvParameterSpec(new byte[16]);
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(key, "AES"), iv);
        byte[] decryptedData = cipher.doFinal(encryptedData);
        return decryptedData;
    }

    private static String bytesToHex(byte[] bytes) {
        return Base64.getEncoder().encodeToString(bytes);
    }
