import sqlalchemy as sa

def get_columns_for_table(db_engine, table_name, columns=None, named_tuples=False):
    try:
        if columns is None:
            query = sa.text("SHOW COLUMNS FROM :table_name")
            columns = [sa.bindparam("table_name")]
        else:
            query = sa.text("SHOW COLUMNS FROM :table_name WHERE COLUMN_NAME IN :columns")
            columns = [sa.bindparam("table_name"), sa.bindparam("columns")]

        with db_engine.connect() as connection:
            result = connection.execute(query, {table_name: table_name, "columns": columns})

            if named_tuples:
                return [row._as_record for row in result]
            else:
                return result.fetchall()
    except sa.exc.SQLAlchemyError as e:
        print("Error retrieving columns: {}".format(str(e)))
        return None
