class CaseInsensitiveRFPDupeFilter(RFPDupeFilter):

    def __init__(self):
        super().__init__()
        self.request_cache = {}

    def request_fingerprint(self, request):
        fp = hashlib.sha1()
        fp.update(to_bytes(request.url.lower().encode('utf-8')))
        return fp.hexdigest()

    def request_seen(self, request):
        request_fingerprint = self.request_fingerprint(request)
        return request_fingerprint in self.request_cache

    def request_not_seen(self, request):
        self.request_cache[self.request_fingerprint(request)] = True
        return True
