def fetch_and_validate_data(api_url, session_id, expected_structure):
    method = "fetch_and_validate_data"
    headers = {
        "Content-Type": "application/json",
    }
    params = {
        "session_id": session_id,
    }
    try:
        response = requests.get(api_url, headers=headers, params=params)
        response.raise_for_status()
    except requests.exceptions.HTTPError as err:
        self.logger.error(f"[{method}] Error fetching data: {err}")
        return

    content_type = response.headers.get("Content-Type")
    if content_type is None or "application/json" not in content_type:
        self.logger.error(f"[{method}] Unexpected content-type: {content_type}")
        return

    data = json.loads(response.content)
    if not isinstance(data, list):
        self.logger.error(f"[{method}] Response is not a list: {data}")
        return

    for item in data:
        if not isinstance(item, dict):
