use std::mem;
use std::os::raw::c_int;
use std::os::raw::c_uint;
use std::ptr;

#[derive(Debug)]
enum IPAddressType {
    IPv4,
    IPv6,
}

pub unsafe fn get_ip_address_type(sockaddr: *const libc::sockaddr) -> IPAddressType {
    let sockaddr_len = mem::size_of::<libc::sockaddr>();
    let addr_type = match sockaddr.as_ptr() {
        ptr::null() => IPv4,
        _ => {
            let addr = match sockaddr.as_ref() {
                libc::SockaddrV4::cast() => {
                    let addr_in = mem::transmute::<*, libc::sockaddr_in>(sockaddr);
                    mem::transmute::<*, &libc::sockaddr_in>(addr_in)
                }
                libc::SockaddrV6::cast() => {
                    let addr_in6 = mem::transmute::<*, libc::sockaddr_in6>(sockaddr);
                    mem::transmute::<*, &libc::sockaddr_in6>(addr_in6)
                }
                _ => return IPv4,
            };

            if addr.sa_family == libc::AF_INET {
                IPv4
            } else if addr.sa_family == libc::AF_INET6 {
                IPv6
            } else {
                // Unsupported address family
                IPv4
            }
        }
    };

    addr_type
}

pub unsafe fn is_ip4_addr(sockaddr: *const libc::sockaddr) -> bool {
    match sockaddr.as_ptr().as_ref() {
        libc::SockaddrV4::cast() => true,
        _ => false,
    }
}

pub unsafe fn is_ip6_addr(sockaddr: *const libc::sockaddr) -> bool {
    match sockaddr.as_ptr().as_ref() {
        libc::SockaddrV6::cast() => true,
        _ => false,
    }
}

pub unsafe fn as_sockaddr_in(sockaddr: *const libc::sockaddr) -> *mut libc::sockaddr_in {
    if is_ip4_addr(sockaddr) {
        mem::transmute::<*, *mut libc::sockaddr_in>(sockaddr)
    } else {
        ptr::null_mut()
    }
}

pub unsafe fn as_sockaddr_in6(sockaddr: *const libc::sockaddr) -> *mut libc::sockaddr_in6 {
    if is_ip6_addr(sockaddr) {
        mem::transmute::<*, *mut libc::sockaddr_in6>(sockaddr)
    } else {
        ptr::null_mut()
    }
}
