#include <iostream>
#include <rocksdb/db.h>
#include <rocksdb/options.h>
#include <string>
#include <vector>

class ColumnFamilyHandle {
 public:
  ColumnFamilyHandle(std::string column_family_name, rocksdb::DB* db)
      : db_(db), cf_(nullptr), status_(rocksdb::Status::OK()) {}

  ~ColumnFamilyHandle() {
    if (cf_) {
      db_->DestroyColumnFamily(cf_);
      cf_ = nullptr;
    }
  }

  rocksdb::Status Open() {
    status_ = db_->OpenColumnFamily(cf_, column_family_name.c_str());
    return status_;
  }

  rocksdb::ColumnFamily* GetColumnFamily() const { return cf_; }

  const rocksdb::Status& GetStatus() const { return status_; }

 private:
  rocksdb::DB* db_;
  rocksdb::ColumnFamily* cf_;
  rocksdb::Status status_;
};

class DatabaseHandle {
 public:
  DatabaseHandle(const std::string& db_path)
      : options_(rocksdb::DefaultOptions()), db_(nullptr), status_(rocksdb::Status::OK()) {
    options_.set_create_if_missing(true);
    status_ = rocksdb::DB::Open(options_, db_path, &db_);
  }

  ~DatabaseHandle() {
    if (db_) {
      db_->Close();
      db_ = nullptr;
    }
  }

  rocksdb::DB* GetDatabase() const { return db_; }

  const rocksdb::Status& GetStatus() const { return status_; }

 private:
  rocksdb::Options options_;
  rocksdb::DB* db_;
  rocksdb::Status status_;
};

int main(int argc, char** argv) {
  if (argc < 3) {
    std::cerr << "Usage: " << argv[0] << " <db_path> <column_family_name>" << std::endl;
    return 1;
  }

  std::string db_path = argv[1];
  std::string column_family_name = argv[2];

  DatabaseHandle db_handle(db_path);
  if (!db_handle.GetStatus().IsOK()) {
    std::cerr << "Error opening database: " << db_handle.GetStatus().ToString() << std::endl;
    return 1;
  }

  ColumnFamilyHandle cf_handle(column_family_name, db_handle.GetDatabase());
  if (!cf_handle.GetStatus().IsOK()) {
    std::cerr << "Error creating column family: " << cf_handle.GetStatus().ToString() << std::endl;
    return 1;
  }

  if (cf_handle.Open().IsOK()) {
    // Use the column family handle here
    db_handle.~DatabaseHandle();
    cf_handle.~ColumnFamilyHandle();
  } else {
    std::cerr << "Error opening column family: " << cf_handle.GetStatus().ToString() << std::endl;
    cf_handle.~ColumnFamilyHandle();
    db_handle.~DatabaseHandle();
  }

  return 0;
}
