pub struct Symbol {
    name: String,
    id: u32,
}

pub struct SymbolInterner {
    symbols: std::collections::HashMap<String, Symbol>,
    next_id: u32,
}

impl SymbolInterner {
    pub fn new() -> Self {
        SymbolInterner {
            symbols: std::collections::HashMap::new(),
            next_id: 0,
        }
    }

    pub fn intern(&mut self, string: &str) -> Symbol {
        let symbol = self.symbols.entry(string.to_owned()).or_insert_with(|| {
            let id = self.next_id;
            self.next_id += 1;
            Symbol {
                name: string.to_owned(),
                id,
            }
        });
        symbol.clone()
    }

    pub fn get_symbol_by_name(&self, name: &str) -> Option<&Symbol> {
        self.symbols.get(name)
    }

    pub fn get_symbol_by_id(&self, id: u32) -> Option<&Symbol> {
        self.symbols.iter().find(|symbol| symbol.1.id == id)
    }
}

pub struct SymbolStr<'a> {
    symbol: &'a Symbol,
}

impl<'a> SymbolStr<'a> {
    pub fn as_str(&self) -> &str {
        &self.symbol.name
    }

    pub fn as_u32(&self) -> u32 {
        self.symbol.id
