// Opaque type for the table of contents renderer
pub type TableOfContents = Box<dyn Fn(CStr) -> CString + Send + Sync>;

// Function signature for the table of contents renderer
pub extern "C" fn table_of_contents_renderer(input: *const i8, renderer: TableOfContents) -> *mut i8 {
    let input_str = unsafe { CStr::from_ptr(input) };
    let rendered_contents = renderer(input_str);
    let rendered_contents_ptr = rendered_contents.into_raw();
    Box::into_raw(renderer, rendered_contents_ptr) as *mut i8
}

