pub fn validate_input(input: &str) -> Result<CString, &'static str> {
    if input.is_empty() {
        return Err("Input string is empty");
    }

    Ok(CString::new(input).unwrap())
}

// Function to generate the formatted table of contents
pub fn generate_table_of_contents(input: &str, renderer: TableOfContents) -> String {
    let validated_input = validate_input(input).unwrap();
    let rendered_contents = renderer(validated_input.as_ptr());
    let rendered_contents_str = CStr::from_ptr(rendered_contents).to_str().unwrap();
    String::from(rendered_contents_str)
}

// Function to execute the table of contents generation
