use std::env;
use std::fs;
use std::path::PathBuf;

fn create_dir_and_set_env(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let base_dir = std::env::var("BASE_DIR")?;
    let base_path = PathBuf::from(&base_dir);
    let dir_path = base_path.join(dir_name);

    // Check if directory already exists
    if fs::path_exists(&dir_path) {
        println!("Directory already exists.");
        return Ok(());
    }

    // Create directory
    fs::create_dir_all(&dir_path)?;

    // Set environment variable
    let dir_path_str = dir_path.to_str().unwrap();
    let mut env_vars = env::vars();
    let mut dir_env_var_set = false;

    for (name, value) in env_vars {
        if name == "DIR_PATH" {
            let mut new_value = value;
            new_value.push_str(&format!(":{}", dir_path_str));
            env::set_var("DIR_PATH", new_value)?;
            dir_env_var_set = true;
            break;
        }
    }

    if !dir_env_var_set {
        env::set_var("DIR_PATH", dir_path_str)?;
    }

    Ok(())
}
