#[derive(Debug, Eq, PartialEq)]
enum ForkResult {
    Parent { child: i32 },
    Child,
}

impl fmt::Display for ForkResult {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ForkResult::Parent { child } => write!(f, "Parent: {}", child),
            ForkResult::Child => write!(f, "Child"),
        }
    }
}

