pub fn create_http_server(server_id: ServerId, ip_address: String, port: String) -> Result<ServerHandle, Box<dyn Error>> {
    let ip = IpAddr::from_str(&ip_address)?;
    let listener = TcpListener::bind(SocketAddr::from((ip, port.as_str().parse()?)))?;
    let server_addr = listener.local_addr()?;
    let token = Arc::new(ServerId::new(server_addr));

