use glib::prelude::*;
use gtk::prelude::*;
use gtk::{Inhibit, InitContext, TextTag, TextTagTable};

const EMPTY_TAG: &TextTag = unsafe { std::mem::zeroed() };

pub fn create_text_tag(name: &str) -> &TextTag {
    if gtk::glib::init().is_err() {
        panic!("GTK initialization failed.");
    }

    let inhibit = Inhibit::new();
    let context = InitContext::default();
    let tag_table = TextTagTable::new(&context);

    let tag = match tag_table.lookup_name(name) {
        Some(tag) => tag,
        None => {
            let new_tag = TextTag::new(&context, name);
            tag_table.add(&new_tag);
            new_tag
        }
    };

    inhibit.enable();
    tag.borrow()
}
