use std::boxed::Box;
use std::ptr::null_mut;

struct Node {
    data: Box<dyn std::any::Any + Send + Sync>,
    next: AtomicPtr<Node>,
}

struct ConcBag {
    head: AtomicPtr<Node>,
}

impl ConcBag {
    pub fn new() -> Self {
        ConcBag { head: AtomicPtr::new(null_mut()) }
    }

    pub fn insert(&self, bag: Box<dyn std::any::Any + Send + Sync>) {
        let n = Box::into_raw(Box::new(Node {
            data: bag,
            next: AtomicPtr::new(null_mut()),
        }) as *mut Node);

        loop {
            let head = self.head.load(Ordering::Relaxed);
            unsafe { (*n).next.store(head, Ordering::Relaxed) };
            if self.head.compare_and_swap(head, n, Ordering::Release) == head {
