use piston_window::*; // Import PistonWindow and related types
use std::rc::Rc; // Import Rc for managing the window's state

struct GameState {
    muted: bool,
    settings: bool,
}

impl Default for GameState {
    fn default() -> Self {
        Self { muted: false, settings: true }
    }
}

fn main() {
    let window: PistonWindow = WindowSettings::new("Game Window", [(1024, 768)])
        .exit_on_esc(true)
        .build()
        .unwrap();

    let mut state = Rc::new(RefCell::new(GameState::default()));
    let mut sounds = SoundHandler::new();

    let mut menu_items = vec!["Resume", "Mute", "Exit Game"];
    let mut selected_index = 0;

    while let Some(event) = window.next() {
        if let Some(args) = event.render_args() {
            window.set_lazy(true);
            window.draw_2d(&args.view, |c, g| {
                clear([1.0; 4], g);
                text::Text::new(Color::WHITE).draw("Game Paused", c.transform, g);
                let mut y_offset = 0.0;
                for item in &menu_items {
                    let color = if selected_index == menu_items.iter().position(|x| x == item).unwrap() {
                        Color::WHITE
                    } else {
                        Color::GRAY
                    };
                    text::Text::new(color).draw(item, c.transform.trans(100.0, y_offset), g);
                    y_offset += 25.0;
                }
            });
            window.set_lazy(false);
        }

        if let Some(args) = event.update_args() {
            if args.window.is_minimized() {
                continue;
            }

            if let Some(button) = args.press_args() {
                match button {
                    Button::Keyboard(key) => match key {
                        Key::Return => {
                            match selected_index {
                                0 => {
                                    state.borrow_mut().settings = false;
                                }
                                1 => {
                                    if state.borrow().muted {
                                        for sound in sounds.map.values_mut() {
                                            sound.set_volume(1.0);
                                        }
                                        state.borrow_mut().muted = false;
                                    } else {
                                        for sound in sounds.map.values_mut() {
                                            sound.set_volume(0.0);
                                        }
                                        state.borrow_mut().muted = true;
                                    }
                                }
                                2 => std::process::exit(1),
                                _ => (),
                            }
                        }
                        Key::Down => {
                            if selected_index == menu_items.len() - 1 {
                                selected_index = 0;
                            } else {
                                selected_index += 1;
                            }
                        }
                        Key::Up => {
                            if selected_index == 0 {
                                selected_index = menu_items.len() - 1;
                            } else {
                                selected_index -= 1;
                            }
                        }
                        Key::Escape => {
                            state.borrow_mut().settings = false;
                        }
                        _ => (),
                    },
                    _ => (),
                }
            }
        }
    }
}
