use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::PathBuf;

fn create_and_write_to_files(paths: Vec<String>) -> Result<(), Box<dyn std::error::Error>> {
    let mut writers = Vec::new();

    for path in paths {
        let file_path = PathBuf::from(path);
        let file = File::create(&file_path)?;
        let writer = BufWriter::new(file);
        writers.push(writer);
    }

    for mut writer in writers {
        writer.write_all(b"Some content to write to each file\n")?;
        writer.flush()?;
    }

    Ok(())
}
