pub fn run_compiler(input_slice: &[&str], set_exit_status: Box<dyn FnOnce(i32) + Send + Sync>,) -> Result<i32, Box<dyn Error>> {
    let input_strings: Vec<String> = input_slice.iter().map(|s| CString::new(s).unwrap().into_string()).collect();
    let input_str = input_strings.join(" ");

    let mut child = Command::new("rustc")
        .args(&["--", "-o", "temp.out", "-"])
        .stdin(std::process::Stdio::pipes())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::pipes())
        .spawn()?;

    child.stdin.write_all(input_str.as_bytes())?;
    child.stdin.flush()?;

    let output = child.wait_with_output()?;
    let exit_status = output.status.code();

    set_exit_status(exit_status);

    if exit_status.is_ok() {
        Ok(0)
    } else {
        Err(Box::new(CompilerError { message: format!("Compiler returned error: {}", exit_status) }))
    }
}

