fn print_usage(program_name: &str, options: &[(&str, char, &str)]) {
    let program_long_name = format!("{}: ", program_name);
    let mut opts = Options::new();
    opts.optflag("", "help", "Print this help message.");
    let matches = match opts.parse(std::env::args().skip(1)) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}Error parsing options: {}", program_long_name, e);
            std::process::exit(1);
        }
    };

    if matches.opt_present("help") {
        println!("{}Usage: {} [options]\n\nOptions:\n", program_long_name, program_name);
        for option in options {
            let long_option = option.0;
            let short_option = option.1;
            let description = option.2;
            println!(
                "- {} {}, {}: {}\n",
                if short_option.is_empty() { "-" } else { short_option },
                long_option,
                "    ",
                description
            );
        }
        println!();
        std::process::exit(0);
    }

    let usage = format!(
        "{}Usage: {} [options]\n\nOptions:\n",
        program_long_name, program_name
    );
    println!("{}", usage);

    for option in options {
        let long_option = option.0;
        let short_option = option.1;
        let description = option.2;
        println!(
            "- {} {}, {}: {}\n",
            if short_option.is_empty() { "" } else { short_option },
            long_option,
            "    ",
            description
        );
    }
}
