use std::fs::File;
use std::io::BufReader;
use std::io::BufRead;
use std::path::Path;
use std::error::Error;
use std::time::SystemTime;

#[derive(Debug)]
struct MenuItem {
    name: String,
    data: Option<String>,
    is_due: bool,
}

#[derive(Debug)]
struct Menu {
    items: Vec<MenuItem>,
}

impl Menu {
    fn new() -> Self {
        Menu { items: Vec::new() }
    }
}

fn load_file(path: &Path) -> Result<String, Box<dyn Error>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut contents = String::new();
    reader.lines().for_each(|line| {
        if let Ok(line) = line {
            contents.push_str(&line);
        }
        contents.push('\n');
    });
    Ok(contents)
}

fn check_task_and_update(task: &mut Option<Task>, current_time: SystemTime) -> bool {
    match task {
        Some(ref mut t) => {
            if t.due_time <= current_time {
                t.result = Some("Task completed".to_string());
                true
            } else {
                false
            }
        }
        None => false,
    }
}

fn load_menu_file(file_path: &Path, tasks: &mut Option<Vec<Task>>) -> Result<Menu, Box<dyn Error>> {
    let contents = load_file(file_path)?;
    let mut menu = Menu::new();
    for line in contents.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        let name = parts[0].to_string();
        let data = parts[1..].iter().collect::<Vec<&str>>().join(" ");
        let is_due = check_task_and_update(tasks, SystemTime::now());
        menu.items.push(MenuItem {
            name,
            data: Some(data),
            is_due,
        });
    }
    Ok(menu)
}

fn main() -> Result<(), Box<dyn Error>> {
    let file_path = Path::new("/path/to/menu.txt");
    let mut tasks = None;
    let menu = load_menu_file(file_path, &mut tasks)?;
    println!("{:?}", menu);
    Ok(())
}

#[derive(Debug)]
struct Task {
    due_time: SystemTime,
    result: Option<String>,
}
