use std::fmt;
use std::default::Default;
use std::error::Error;
use sha2::{Sha256, Digest};

struct Config {
    hash_is_enabled: bool,
}

impl Default for Config {
    fn default() -> Self {
        Config { hash_is_enabled: false }
    }
}

struct HashedPassword {
    username: String,
    salt: Option<String>,
    hashed_password: String,
}

impl fmt::Display for HashedPassword {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}:{}", self.username, self.hashed_password)
    }
}

impl Error for HashedPassword {}

fn hash_password(username: &str, password: &str, salt: Option<&str>) -> Result<HashedPassword, Box<dyn Error>> {
    let config = Config::default();

    if !config.hash_is_enabled {
        return Err(Box::new(HashedPassword {
            username: username.to_string(),
            salt: salt.map(String::from),
            hashed_password: "Hash functionality is disabled".to_string(),
        }));
    }

    let salt = match salt {
        Some(s) => s,
        None => return Err(Box::new(HashedPassword {
            username: username.to_string(),
            salt: None,
            hashed_password: "Salt is missing".to_string(),
        })),
    };

    let password = format!("{}{}", username, salt);
    let password_bytes = password.as_bytes();

    let mut hasher = Sha256::new();
    hasher.update(password_bytes);
    let result = hasher.finalize();

    let hashed_password = hex::encode(result);

    Ok(HashedPassword {
        username: username.to_string(),
        salt: Some(s),
        hashed_password,
    })
}

fn main() {
    let username = "testuser";
    let password = "testpassword";
    let salt = "test salt";

    match hash_password(username, password, Some(salt)) {
        Ok(hashed_password) => println!("{}", hashed_password),
        Err(error) => println!("Error: {}", error),
    }
}
```

