use reqwest::header::{HeaderMap, HeaderValue};
use reqwest::Error;
use std::str::FromStr;
use crypto::mac::Mac;
use crypto::sha1::Sha1;
use serde_json::Value;

fn process_request(req: &reqwest::Request, config: &Value) -> Result<reqwest::Response, Error> {
    let hmac_header = req.headers().get("X-HMAC-SHA1");
    match hmac_header {
        Some(hmac_header_value) => {
            let hmac_header_value_str = hmac_header_value.to_str().unwrap();
            let header_split: Vec<&str> = hmac_header_value_str.split("=").collect();
            let hmac_value = HeaderValue::from_str(&header_split[1]).unwrap();
            let hmac_value_str = hmac_value.to_str().unwrap();

            let hmac = Mac::new(Sha1::new(), config.secret.as_bytes());
            let body = req.body()?;
            let mut hmac_input = vec![];
            body.copy_to_vec(&mut hmac_input)?;

            let hmac_result = hmac.result();
            let hmac_expected = hex::decode(hmac_value_str)?;

            if hmac_result == hmac_expected {
                Ok(req.into_response()?)
            } else {
                Err(Error::new(
                    reqwest::ErrorKind::InvalidResponse,
                    "Invalid HMAC signature.",
                ))
            }
        },
        None => Err(Error::new(
            reqwest::ErrorKind::InvalidRequest,
            "Missing X-HMAC-SHA1 header.",
        )),
    }
}
