use std::env;
use std::ffi::OsStr;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

const TLS_KEY: usize = 0;

thread_local! {
    static TLS_IDENTIFIER: Mutex<Option<String>> = Mutex::new(None);
}

fn init_tls_identifier() {
    let mut rng = rand::thread_rng();
    let identifier = format!("{:x}", rng.gen());
    TLS_IDENTIFIER.with(|s| s.lock().unwrap().replace(Some(identifier), None));
}

fn get_executable_path() -> Result<PathBuf, io::Error> {
    let path = env::current_exe()?;
    Ok(path)
}

fn get_parent_path(path: &Path) -> Result<PathBuf, io::Error> {
    let parent = path.parent()?;
    Ok(parent.to_owned())
}

fn construct_task_dir_path() -> Result<PathBuf, io::Error> {
    let executable_path = get_executable_path()?;
    let parent_path = get_parent_path(&executable_path)?;
    let identifier = TLS_IDENTIFIER.with(|s| s.lock().unwrap().as_ref().unwrap().clone());
    let task_dir_name = format!("task_{}", identifier);
    let task_dir_path = parent_path.join(task_dir_name);
    Ok(task_dir_path)
}

fn check_path(path: &Path) -> Result<(), io::Error> {
    let parent = path.parent()?;
    if parent.to_str().map_or(false, |s| s.starts_with("/")) {
