```rust use iron::prelude::*; use std::net::SocketAddr; use std::path::PathBuf;

fn create_web_server(listen_addr: &str) -> Result<Manager<IronService>, Box<dyn std::error::Error>> {
    let mut config = Configuration::default();
    config.handle_connection_limit = Some(100);

    let mut router = Router::new();

    let static_dir = PathBuf::from("./static");
    let static_mount = Mount::new("/", Static::new(static_dir), "/");
    let api_mount = Mount::new("/api", api_handler, "/");

    router.mount("/", static_mount);
    router.mount("/api", api_mount);

    let chain = Chain::new(vec![
        Logger::new(),
        Compress::new(),
        BodyMiddleware::new(),
    ]);

    let service = IronService::new(chain.wrap_router(router));

    let addr = SocketAddr::try_new(listen_addr.parse()?, 80)?;

    Ok(Manager::new(service, addr))
}

fn api_handler(req: &mut Request) -> IronResult {
    let query_params: Vec<(&str, &str)> = req.query_pairs().collect();
    let room_id = query_params.iter().find(|&x| x.0 == "room_id").map(|x| x.1);

    match room_id {
        Some(room_id) => {
            let response = format!("Room ID: {}", room_id);
            Ok(Response::with((status::Ok, response)))
        }
        None => {
            let response = "Missing room ID query parameter.";
            Err(ErrorResponse::new(status::BadRequest, response))
        }
    }
}
