use std::env;
use std::fs;
use std::path::PathBuf;

fn check_and_perform_actions() -> Result<(), Box<dyn std::error::Error>> {
    let current_exe = env::current_exe()?;
    let os_name = match os_str::uname()?.name().to_lowercase().as_str() {
        "windows" => "Windows",
        _ => "Non-Windows",
    };

    let file_name = match os_name {
        "Windows" => "windows_file.txt".to_owned(),
        "Non-Windows" => "non_windows_file.txt".to_owned(),
    };

    let mut file_path = current_exe.parent().unwrap().join("output");
    file_path.push(file_name);

    if os_name == "Windows" {
        let source_file = PathBuf::from("windows_source_file.txt");
        fs::copy(source_file, &file_path)
            .map_err(|e| Box::new(e))?;
        println!("Copied windows file to {}", file_path.display());
    } else {
        fs::File::create(&file_path)
            .map_err(|e| Box::new(e))?;
        println!("Created non-windows file at {}", file_path.display());
    }

    Ok(())
}
