use std::iter;
use std::str;
use sha2::{Sha256, Digest};

struct HashedNumbersIterator {
    input: String,
    hasher: Sha256,
}

impl HashedNumbersIterator {
    fn new(input: String) -> Self {
        let hasher = Sha256::new();
        Self { input, hasher }
    }
}

impl Iterator for HashedNumbersIterator {
    type Item = String;

    fn next(&mut self) -> Option<Self::Item> {
        let input_bytes = self.input.as_bytes();
        let mut input_hashed = [0u8; 32];

        self.hasher.update(input_bytes);
