use std::fs::File;
use std::io::{Read, Write};
use std::os::unix::io::AsRawFd;
use std::ptr;

const SHA1_DIGEST_LENGTH: usize = 20;

#[no_mangle]
pub extern "C" fn hash_string(message: *const u8) -> *const u8 {
    let message_len = message.len();
    let mut input = vec![0u8; message_len];
    unsafe {
        ptr::copy_nonoverlapping(message, &mut input[..message_len], 1);
    }

    let mut input_fd = match File::open("/dev/urandom") {
        Ok(file) => file,
        Err(_) => return ptr::null(),
    };

    let mut hash = [0u8; SHA1_DIGEST_LENGTH];
    let mut hash_output = [0u8; SHA1_DIGEST_LENGTH];

    let mut input_buffer = [0u8; 4096];
    let mut read_bytes = 0;

    let context = sha1::Sha1::new();

    loop {
        read_bytes = match input_fd.read(&mut input_buffer) {
            Ok(n) => n,
            Err(_) => break,
        };

        context.update(&input_buffer[..read_bytes]);

        if read_bytes < input_buffer.len() {
            break;
        }
    }

    input_fd.write_all(&input).expect("Failed to write input to SHA-1 context");

    context.finalize().expect("SHA-1 computation failed");

    unsafe {
        ptr::copy_nonoverlapping(
            &context.result() as *const [u8; SHA1_DIGEST_LENGTH],
            hash_output.as_mut_ptr(),
            SHA1_DIGEST_LENGTH,
        );
    }

    let mut output_file = File::create("/dev/stdout").expect("Failed to open output file");

    output_file.write_all(hash_output).expect("Failed to write hash to output file");

    let mut output = vec![0u8; SHA1_DIGEST_LENGTH * 2];
    for byte in hash_output {
        let hex = match byte.to_string().len() {
            1 => format!("0{:x}", byte),
            _ => format!("{:x}", byte),
        };
        output.push(hex[0]);
        output.push(hex[1]);
    }

    let hex_hash = String::from_utf8_lossy(&output);

    let mut output_str = Vec::new();
    output_str.push_str(b"SHA-1:\n");
    output_str.push_str(hex_hash.as_bytes());
    output_str.push_str(b"\n");

    let output_len = output_str.len();
    let mut output_buffer = vec![0u8; output_len];

    unsafe {
        ptr::copy_nonoverlapping(
            output_str.as_ptr(),
            output_buffer.as_mut_ptr(),
            output_len,
        );
    }

    box output_buffer
}

extern "C" {
    fn malloc(size: size_t) -> *mut u8;
    fn free(ptr: *mut u8);
}

fn main() {
