use std::error::Error;

#[derive(Debug)]
struct CustomError {
    original_error: Box<dyn Error>,
    custom_message: String,
}

impl From<(Box<dyn Error>, &str)> for CustomError {
    fn from((error, message): (Box<dyn Error>, &str)) -> Self {
