fn copy_recursively(src: &PathBuf, dest: &PathBuf) -> Result<(), Box<dyn std::error::Error>> {
    if src == dest {
        return Ok(());
    }

    if src.is_dir() {
        let src_files = fs::read_dir(src)?;
        for entry in src_files {
            let src_entry = entry?;
            let src_path = src_entry.path();
            let dest_path = dest.join(src_entry.file_name());

            if src_path.file_type()?.is_dir() {
                copy_recursively(src_path, dest_path)?;
            } else if src_path.file_type()?.is_file() && !dest_path.exists() {
                let src_data = fs::read_to_string(src_path)?;
                fs::write(dest_path, src_data)?;
            }
        }
    } else if dest.is_dir() && !dest_path.exists() {
        fs::create_dir_all(dest_path)?;
        let src_data = fs::read_to_string(src)?;
        fs::write(dest_path, src_data)?;
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let src_path = PathBuf::from("/path/to/source");
    let dest_path = PathBuf::from("/path/to/destination");
    copy_recursively(&src_path, &dest_path)?;
