fn setup_db(db_url: &str) -> Result<(Transaction, Box<Middleware<fn(Request, Response) -> Result<Response, Error>>, ()>, ()> {
    let migrate_cmd = Command::new("sh")
        .arg("-c")
        .arg("cargo run migrate")
        .env("DATABASE_URL", db_url)
        .output()
