fn get_file_lines(input: &str, libs: Vec<String>, externs: Vec<String>, test_args: Vec<String>, crate_name: Option<String>) -> Result<i32, i32> {
    let input_path = Path::new(input);
    let input = config::Input::File(input_path.clone());

    let sessopts = config::SessionOptions::new();
    let mut config = config::Config::new(&input, sessopts)?;

    config.set_search_paths(libs);
    config.set_externs(externs);

    if let Some(crate_name) = crate_name {
        config.set_crate_name(crate_name);
    }

    let mut codemap = CodeMap::new();
    let diagnostic_handler = diagnostic::Handler::default();
    config.set_diagnostic_handler(Box::new(diagnostic_handler));

    let file = File::open(input_path)?;
    let mut file_contents = String::new();
    file.read_to_string(&mut file_contents)?;
    drop(file);

    codemap.attach(&config.source_file());
    codemap.push(&config.source_file().span());

    let lines: Vec<&str> = file_contents.split('\n').collect();

    config.set_code_map(Some(Box::new(codemap)));
    config.finish()?;

    Ok(lines.len() as i32)
}
```

