fn json_file_hash(path: &str, disable_checks: bool) -> Result<String, Box<dyn Error>> {
    let file = match File::open(path) {
        Ok(file) => file,
        Err(e) => return Err(Box::new(e)),
    };

    let mut contents = Vec::new();
    file.read_to_end(&mut contents)?;

    if disable_checks {
        Ok(sha1::Sha1::digest(&contents).to_string())
    } else {
