struct History {
    file: Option<File>,
    buffers: Vec<Vec<u8>>,
}

impl History {
    fn new() -> Self {
        History {
            file: None,
            buffers: Vec::new(),
        }
    }

    fn set_file_name(&mut self, file_name: Option<String>) {
        let file_name = file_name.unwrap();
        self.file = Some(match File::create(Path::new(&file_name)) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Failed to create file: {}", file_name);
                return;
            }
        });
    }

    fn set_max_file_size(&mut self, max_file_size: u64) {
        if max_file_size <= 0 {
            eprintln!("Invalid maximum file size: {}", max_file_size);
            return;
        }
        self.max_file_size = max_file_size;
    }

    fn push(&mut self, buffer: Vec<u8>) -> Result<(), ()> {
        if self.buffers.len() >= self.max_file_size as usize {
            eprintln!("History size limit reached: {}", self.max_file_size);
            return Err(());
        }
        self.buffers.push(buffer);
        Ok(())
    }

    fn commit_history(&mut self) -> Result<(), ()> {
        if self.file.is_none() {
            eprintln!("No file name set for history");
            return Err(());
        }

        let mut writer = BufWriter::new(self.file.as_ref().unwrap());

        for buffer in &self.buffers {
            if writer.write_all(buffer.as_slice()) < buffer.len() {
                eprintln!("Failed to write history to file");
                return Err(());
            }
        }

        self.buffers.clear();

        Ok(())
    }
}

