use reqwest::Client;
use futures::stream::{self, StreamExt};
use std::collections::HashMap;
use MismatchResult::*;

async fn xfs_dinode_verify_fork(
    provider: &ProviderInfo,
    interaction: &Interaction,
    options: &VerificationOptions,
    provider_state_executor: &ProviderStateExecutor,
) -> Result<Option<String>, MismatchResult> {
    let client = Client::builder()
        .danger_accept_invalid_certs(options.disable_ssl_verification)
        .build()
        .unwrap_or_else(|_| Client::new());

    let mut provider_states_results = HashMap::new();

    let states_stream = stream::iter(
        interaction.provider_states().iter().map(|state| (state, client.clone())),
    )
    .map(|(state, client)| {
        let state_name = state.name.clone();
        async move {
            let response = client
                .get(&format!("{}/{}", provider.api_url, state.api_endpoint))
                .send()
                .await
                .map_err(|e| MismatchResult::Error(format!("Failed to get state '{}': {}", state_name, e)))?;

            let state_result = response.json::<ProviderStateResult>().await.map_err(|e| {
                MismatchResult::Error(format!("Failed to parse state '{}' response: {}", state_name, e))
            })?;

            provider_states_results.insert(state.name, state_result);

            Ok(state_result)
        }
    });

    let results = states_stream.collect::<Vec<_>>().await.map_err(|e| {
        MismatchResult::Error(format!("Failed to get provider states: {}", e))
    })?;

    if results.iter().any(|result| result.is_err()) {
        return Err(MismatchResult::Mismatch);
    }

    Ok(Some(format!("Provider states verified: {:?}", results)))
}
