use base64::{engine::general_purpose as b64, StdEngine as Engine};

type Result<T> = result::Result<T, HashError>;

#[derive(Debug, PartialEq)]
pub enum HashError {
    IoError(io::Error),
    HashError(Box<dyn std::error::Error + Send + Sync + 'static>),
}

