pub fn hash_and_encode(data: &[u8]) -> Result<String> {
    let mut combined = Vec::with_capacity(data.len() + 16); // 16 bytes for the guid
    combined.extend_from_slice(data);
    let guid = b"2b5468a7-7244-47da-a41e-4f6ee14ab7f6"; // Fixed GUID
