```rust use std::fs::File; use std::io::{BufReader, BufRead, Write}; use std::path::Path; use textwrap::TextWrapper;

fn print_binary_name(binary_path: &str) {
    let wrapper = TextWrapper::new(80, 4).unwrap();

    let path = Path::new(binary_path);
    let file_name = path.file_name().unwrap().to_str().unwrap();

    let mut signal_muted = false;
    let old_mask = unsafe { libc::signal(libc::SIGPIPE, SignalHandler) };

    println!("{}: {}", "Printing binary name".bold(), file_name);
    println!("{}", wrapper.wrap("Binary path:").unwrap());
    println!("{}", wrapper.wrap(binary_path).unwrap());
    println!("{}", wrapper.wrap("File name:").unwrap());
    println!("{}", wrapper.wrap(file_name).unwrap());

    let mut file = File::open(binary_path).expect("Failed to open binary file");
    let mut reader = BufReader::new(file);

    let mut buffer = [0; 1024];
    loop {
        let bytes_read = reader.read(&mut buffer).expect("Failed to read from binary file");
        if bytes_read == 0 {
            break;
        }
        let output = String::from_utf8_lossy(&buffer[..bytes_read]);
        print!("{}", wrapper.wrap(output).unwrap());
        write(stdout(), b"\n").expect("Failed to write to console");
    }

    if old_mask != 0 {
        unsafe { libc::signal(libc::SIGPIPE, old_mask) };
    }
    signal_muted = false;
}

