fn create_request_response_channel(request_channel_id: u64, reply_channel_id: u64) -> Result<Metadata, Box<dyn std::error::Error>> {
    let tmp_dir = env::temp_dir().join("request_response");
    let _ = tmp_dir.create_dir()?;

    let (request_tx, request_rx) = mpsc::channel();
    let (reply_tx, reply_rx) = mpsc::channel();

    let request_thread = std::thread::spawn(move || {
        let mut reader = request_rx;
        let mut writer = reply_tx;

        loop {
            match reader.recv() {
                Ok(msg) => {
                    let id = msg;
                    let response = id + 1;
                    writer.send(response).unwrap();
                }
                Err(e) => {
                    if e.kind() == std::sync::mpsc::RecvError::Disconnected {
                        break;
                    } else {
                        panic!("Error in request thread: {:?}", e);
                    }
                }
            }
        }
    });

    let metadata = Metadata::new(request_channel_id, reply_channel_id, Duration::from_secs(5), 1024);

    let request_file = File::create(Path::new(&tmp_dir.join("request.txt")))?;
    let _ = BufWriter::new(request_file).write_all(request_channel_id.to_le_bytes());

    let reply_file = File::create(Path::new(&tmp_dir.join("reply.txt")))?;
    let _ = BufWriter::new(reply_file).write_all(reply_channel_id.to_le_bytes());

    Ok(metadata)
}
