use std::env;
use std::error::Error;
use std::fmt;
use std::fs;
use std::path::PathBuf;

#[derive(Debug, PartialEq)]
enum ParseError {
    InvalidArgumentCount,
    UnrecognizedOption(String),
    InvalidPortNumber(String),
    PathTraversal(PathBuf),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ParseError::InvalidArgumentCount => write!(f, "Invalid argument count"),
            ParseError::UnrecognizedOption(ref name) => write!(f, "Unrecognized option: {}", name),
            ParseError::InvalidPortNumber(ref port) => write!(f, "Invalid port number: {}", port),
            ParseError::PathTraversal(ref path) => write!(f, "Path traversal attempt: {}", path.display()),
        }
    }
}

impl Error for ParseError {}

#[derive(Debug)]
struct Args {
    server_port: u16,
    user_data_path: PathBuf,
    rally_point_port: u16,
}

impl Args {
    fn new(server_port: u16, user_data_path: PathBuf, rally_point_port: u16) -> Self {
        Args {
            server_port,
            user_data_path,
            rally_point_port,
        }
    }
}

fn parse_args() -> Result<Args, ParseError> {
    let args: Vec<String> = env::args().collect();
    let mut options: HashMap<String, String> = HashMap::new();

    if args.len() < 4 {
        return Err(ParseError::InvalidArgumentCount);
    }

    // Skip the executable path and the first argument (command name)
    let server_args: Vec<&str> = &args[2..];

    for arg in server_args {
        let parts: Vec<&str> = arg.splitn(2, "=").collect();
        if parts.len() != 2 {
            return Err(ParseError::UnrecognizedOption(arg.to_string()));
        }

        let key = parts[0].to_owned();
        let value = parts[1].to_owned();

        match key.as_str() {
            "port" => match value.parse::<u16>() {
                Ok(port) => {
                    options.insert(key, value);
                }
                Err(_) => {
                    return Err(ParseError::InvalidPortNumber(value));
                }
            },
            "user_data_path" => {
                let path = PathBuf::from(value);
                if path.is_absolute() {
                    options.insert(key, value);
                } else {
                    let cwd = env::current_dir().unwrap();
                    let user_data_path = cwd.join(value);
                    if user_data_path.is_absolutepath() {
                        options.insert(key, value);
                    } else {
                        return Err(ParseError::PathTraversal(user_data_path));
                    }
                }
            },
            "rally_point" => {
                match value.parse::<u16>() {
                    Ok(port) => {
                        options.insert(key, value);
                    }
                    Err(_) => {
                        return Err(ParseError::InvalidPortNumber(value));
                    }
                }
            },
            _ => {},
        }
    }

    let server_port = options.get("port").unwrap().parse::<u16>().unwrap();
    let user_data_path = PathBuf::from(options.get("user_data_path").unwrap());
    let rally_point_port = options.get("rally_point").unwrap().parse::<u16>().unwrap();

