use md5::Md5;

const SALT: &[u8] = b"some_salt_value";

fn hash_string(input: &str) -> Vec<u8> {
    let mut hasher = Md5::new();
    hasher.update(input.as_bytes());
    hasher.finalize().into()
}

fn hash_stretch(input: &str, iterations: usize) -> Result<String, Box<dyn Error>> {
    let input_bytes = input.as_bytes();
    let mut hashed = Vec::with_capacity(input.len() * 2 * iterations);

    for _ in 0..iterations {
