use std::fs;
use std::path::PathBuf;
use std::io::Error;
use std::io::ErrorKind;
use tempfile::NamedTempFile;
use tempdir::TempDir;
use rand::Rng;
use uuid::Uuid;
use serde_json::Value;

fn generate_pact_file(pact: &Pact, dest_dir: &PathBuf) -> Result<Value, Error> {
    let temp_dir = TempDir::new("pact_file_temp").unwrap();
    let temp_file = NamedTempFile::new_in_dir(&temp_dir, "pact_file")?;
    let mut file = temp_file.file()?;

    serde_json::to_writer(&mut file, pact)?;
    file.flush()?;

    let pact_content = fs::read_to_string(temp_file.path())?;

    fs::remove_dir_all(temp_dir)?;

    let dest_file_path = dest_dir.join(format!("interaction_{}.pact", Uuid::new_v4().to_string().replace("-", ""))).unwrap();
    fs::write(dest_file_path, pact_content)?;

    Ok(serde_json::from_str(&pact_content)?)
}

fn write_pact_file(pact: &Pact, dest_dir: &PathBuf) -> Result<Value, Error> {
    match generate_pact_file(pact, dest_dir) {
        Ok(pact_content) => Ok(pact_content),
        Err(ref e) if e.kind() == ErrorKind::AlreadyExists => {
            let pact_content = fs::read_to_string(dest_file_path())?;
            Ok(serde_json::from_str(&pact_content)?)
        },
        Err(e) => Err(e),
    }
}

fn dest_file_path() -> PathBuf {
    let current_dir = std::env::current_dir().unwrap();
    current_dir.join("generated_pact_file.pact")
}
