use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::fmt;
use std::str::Chars;

const MAX_LINE_LENGTH: usize = 72; // Adjust as needed

#[derive(Debug, PartialEq)]
enum FoldingError {
    InputStringEmpty,
    InvalidInputString,
}

impl fmt::Display for FoldingError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            FoldingError::InputStringEmpty => write!(f, "Input string is empty"),
            FoldingError::InvalidInputString => write!(f, "Invalid input string"),
        }
    }
}

impl Error for FoldingError {}

fn fold_header(input: &str) -> Result<String, FoldingError> {
    if input.is_empty() {
        return Err(FoldingError::InputStringEmpty);
    }

    let mut lines = Vec::new();
    for (line, chars) in Chars::from(input).filter(|c| c != '\r' && c != '\n').map(|c| c.to_string()) {
        if line.len() > MAX_LINE_LENGTH {
            line.push('\r');
            line.push('\n');
            lines.push(line);
        } else {
            lines.push(line);
        }

        if chars.next().is_none() {
            break;
        }
    }

    Ok(lines.join(""))
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <input_string>", args[0]);
        std::process::exit(1);
    }

    let input = &args[1];
    match fold_header(input) {
        Ok(output) => println!("Folded header: {}", output),
        Err(error) => println!("Error: {}", error),
    }
}
