use reqwest::Certificate;
use reqwest::ClientBuilder;
use std::fs::File;
use std::io::Read;

pub fn get_http_client(user_agent: &str, cert_path: &str) -> Result<reqwest::Client, reqwest::Error> {
    let mut builder = ClientBuilder::new();

    // Set custom User-Agent header
    builder = builder.user_agent(user_agent);

    // Set Connection header to 'close'
    builder = builder.connection_default(reqwest::ConnectionDefault::Close);

    // Load custom certificate(s) from file(s)
    let mut files = std::fs::DirEntry::open(cert_path)?;
    let mut certificates: Vec<Certificate> = Vec::new();

    while let Some(entry) = files.next_entry()? {
        if entry.file_type().is_file() {
            let mut file = File::open(&entry.path())?;
            let mut certificate_bytes = Vec::new();
            file.read_to_end(&mut certificate_bytes)?;
            certificates.push(Certificate::from_pem(&certificate_bytes[..])?);
        }
    }

    // Add custom certificate(s) to the client
    for cert in certificates {
        builder = builder.add_root_certificate(cert);
    }

    builder.build()
}
