use openssl::ssl::{SslContext, SslMethod, SslStream};
use std::net::{Ipv4Addr, Ipv6Addr, SocketAddr, TcpStream};
use std::result::Result;
use std::error::Error;

pub type ConnectionError = Box<dyn Error>;

pub fn new(host: SocketAddr, verify: bool, nodelay: bool) -> Result<SslStream<TcpStream>, ConnectionError> {
    let context = match SslContext::new(SslMethod::Tlsv1) {
        Ok(context) => context,
        Err(err) => return Err(Box::new(ConnectionError::Ssl(err))),
    };

    if verify {
        context.set_verify(SslMethod::Tlsv1, None)?;
    }

    let addr = match host.ip() {
        Ipv4Addr::v4(ip) => (ip as u32, host.port()),
        Ipv6Addr::ipv6(ip) => {
            let parts: Vec<&str> = ip.split(":").collect();
            (
                match parts[0].parse::<u32>() {
                    Ok(ip) => ip,
                    Err(_) => return Err(Box::new(ConnectionError::InvalidHost("Invalid IPv6 address"))),
                },
                parts[1].parse::<u16>().unwrap_or(0),
            ),
        },
        _ => return Err(Box::new(ConnectionError::InvalidHost("Invalid socket address"))),
    };

    let mut stream = match TcpStream::connect(SocketAddr::new(addr, host.port())) {
        Ok(stream) => stream,
        Err(err) => return Err(Box::new(ConnectionError::Tcp(err))),
    };

    stream.set_nodelay(nodelay)?;

